window.__D("text/maamarim-melukatim/c002",{"p":[[1500360023,"<h3>בס\"ד. אור לי\"ג תשרי, הילולא דכ\"ק אדמו\"ר מהר\"ש, ה'תש\"מ<sup data-n=\"1503\">*</sup>.</h3>\n<b>בסוכות</b> תשבו שבעת ימים כל האזרח בישראל ישבו בסוכות (והטעם על זה) למען ידעו דורותיכם כי בסוכות הושבתי את בנ\"י בהוציאי אותם מארץ מצרים גו'<sup data-n=\"1504\">1</sup>. ומלשון הכתוב (<i>למען</i> ידעו גו') למדים<sup data-n=\"1505\">2</sup> שידיעה זו היא (לא רק ענין בכוונת המצוה, אלא) חלק בקיום המצוה (כדמוכח גם מלשון כ\"ק אדמו\"ר הזקן בשולחנו<sup data-n=\"1506\">3</sup>). וידועים דיוקי רבותינו נשיאינו בזה, מה נוגע כ\"כ ידיעה זו<sup data-n=\"1507\">4</sup> עד שהיא חלק מהמצוה. וגם מהו בסוכות תשבו, הרי סוכה הוא בחי' מקיף וענין ההתיישבות (דתשבו כולל גם הפירוש דהתיישבות) שייך בבחי' פנימי דוקא<sup data-n=\"1508\">5</sup>, ומזה שאומר <i>בסוכות</i> תשבו מוכח שגם לאחרי הישיבה נשאר הוא בחי' מקיף<sup data-n=\"1509\">6</sup>, וענין ההתיישבות צ\"ל בבחי' המקיף. גם צריך להבין מ\"ש כל האזרח בישראל ישבו בסוכות, הרי הציווי בסוכות תשבו הוא לכל ישראל ומה מוסיף דכל האזרח בישראל ישבו בסוכות<sup data-n=\"1510\">7</sup> ובהציווי בסוכות תשבו אומר שבעת ימים משא\"כ בהציווי כל האזרח גו' אומר ישבו בסוכות סתם<sup data-n=\"1509\">6</sup>. והנה מפסוק זה (כל האזרח בישראל ישבו בסוכות) למדים<sup data-n=\"1511\">8</sup> דכל ישראל ראוים לישב בסוכה אחת. וצ\"ל, הרי ענין האחדות דכל ישראל (ענין אתם נצבים היום כולכם<sup data-n=\"1512\">9</sup>) הוא גם במשך כל השנה, ועד שמצות אהבת ישראל [שהטעם לזה הוא לפי שכולם מתאימות ואב אחד לכולנה (ענין האחדות) כמבואר בתניא<sup data-n=\"1513\">10</sup>] היא כל התורה כולה ואידך פירושה הוא<sup data-n=\"1514\">11</sup>, היינו שכל מצוה היא כמו פירוש ופרט בענין האחדות דכל ישראל<sup data-n=\"1515\">12</sup>, ולמה מודגש זה במצות סוכה דוקא. וגם צריך להבין מ\"ש (לפנ\"ז<sup data-n=\"1516\">13</sup>) ולקחתם לכם ביום הראשון פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל, וידוע<sup data-n=\"1517\">14</sup> שמצוה זו יש לה שייכות לענין הסוכה, שלכן מצוה מן המובחר שנטילת ד' מינים תהי' בסוכה<sup data-n=\"1518\">15</sup>. דזהו גם השייכות דנטילת ד' מינים לבחי' הדעת (בדוגמת למען ידעו דסוכה),כדאיתא בכתבי האריז\"ל<sup data-n=\"1519\">16</sup> שענין כוונת הנענועים דלולב הוא להמשיך דעת לנוק' דז\"א העומדת בחזה דז\"א (שלכן צריך שהלולב ומיניו יגעו בחזה).\nב) <b>ויובן</b> זה בהקדם ענין המשכת המקיף בהתיישבות (בסוכות תשבו) בעבודת ה' כמו שהוא במשך חיי האדם בכלל, ועד\"ז בכל יום ויום. דהגם שענין זה בעיקרו הוא בחג הסוכות, בסוכות תשבו, מ\"מ התורה כללות ופרטות נאמרה<sup data-n=\"1520\">17</sup>, ויש מעין ענין זה גם במשך כל השנה. והענין הוא, הנה ב' הענינים דמקיף ופנימי בעבודת ה' בכלל הם אמונה והשגה. ותחלה צ\"ל ענין המקיף דסוכה, ואח\"כ צ\"ל בסוכות תשבו, כי תחלת העבודה היא בבחי' אמונה. דכל אחד ואחד מישראל, מיד שיצא לאויר העולם, יש בו בחי' אמונה, כמארז\"ל<sup data-n=\"1521\">18</sup> שישראל הם מאמינים בני מאמינים. דזהו תואר אמיתי ע\"פ תורת אמת של כאו\"א מישראל. ולאחרי שהגיע לחינוך וכו' ובא לכלל דיעה, הנה מה שתחלה הי' אצלו בבחי' אמונה ומקיף, נמשך בבחי' פנימיות והתיישבות, ועד שזה נעשה כל מציאותו. ומ\"מ גם אז יש לו בחי' אמונה, כי לאחרי וע\"י המשכת המקיף (מה שמקודם הי' בבחי' מקיף) בפנימיות, נמשך בחי' מקיף עליון יותר<sup data-n=\"1522\">19</sup>, ומקיף זה הוא בבחי' אמונה. ועד\"ז הוא במשך כל ימי חייו, דכל מה שמתעלה יותר בעבודתו ובהשגתו, הנה מה שבתחלה הי' אצלו בבחי' אמונה, נמשך בהבנה והשגה, והאמונה שלו היא בבחי' נעלית יותר [ובדוגמת כללות בנ\"י, שבתחלה היו בכלל אוה\"ע, שהאמונה שלהם היא רק בבחי' כח הפועל בנפעל, ואח\"כ נתעלו כו' להיות אמונתם בבחי' סוכ\"ע, וכמבואר בסידור שער חג המצות בתחלתו]. ועד שארז\"ל<sup data-n=\"1523\">20</sup> יאמין לכל דבר זה משה רבינו, הגם שמשה הי' תכלית שלימות החכמה, הרי גם לאחרי שלימות ההשגה יש ענינים שהם בבחי' אמונה למעלה מהשגה. ואדרבה, כל מה שמשיג יותר הנה ההשגה גופא מחייבת יותר שיש ענינים שהם למעלה מהשכל, ועד כהמאמר<sup data-n=\"1524\">21</sup> תכלית הידיעה שלא נדעך.\nג) <b>ועד\"ז</b> הוא בעבודת האדם בכל יום ויום, יצא אדם לפעלו ולעבודתו עדי ערב<sup data-n=\"1525\">22</sup>, שהעבודה בתחלת היום היא בבחי' אמונה, מודה אני כו' רבה אמונתך, וגם בהתחלת התפלה אומרים הודו לה', הודאה בלבד. ואח\"כ היא העבודה דהתבוננות והשגה בפסוד\"ז, ובפרט בברכות ק\"ש וק\"ש. ולאחרי זה הוא הביטול דשמו\"ע, שהוא ביטול בתכלית, כמו הביטול דאמונה (אלא שאמונה זו היא האמונה שלאחרי ההשגה). ובכח כ\"ז יצא גו' ולעבודתו עדי ערב, שעושה עבודתו במשך כל היום עדי ערב כפירוש הפשוט דעדי ערב, וגם הפירוש בעדי ערב מלשון ערבות ומתיקות<sup data-n=\"1526\">23</sup>, דע\"ישעוסק (במשך כל היום) בעניני העוה\"ז הגשמי שאין תחתון למטה ממנו<sup data-n=\"1527\">24</sup>, שמצד עצמם הם בבחי' ערב וחושך, ומהפכם לקדושה, הנה עי\"ז נעשה אמיתית הערבות ומתיקות, כי כאשר מהפכים דבר מר למתוק היא מתיקות גדולה יותר מכמו שהוא בדבר מתוק מתחלתו<sup data-n=\"1528\">25</sup>. ועי\"ז יצא אדם לפעלו ולעבודתו עדי ערב (גם כפשוטו), שפעולתו ועבודתו במשך כל היום עדי ערב היא בשלימות, כי יש לו סייעתא דשמיא, וסיוע בשלימות, בכל פרטי עבודתו.\nד) <b>וזהו</b> בסוכות תשבו, דבתחלה צ\"ל ענין הסוכה, בחי' מקיף. וזה עצמו (עשיית המקיף דסוכה), גם לפני קיום מצות בסוכות תשבו (ובפרט קודם שנמשך בהתיישבות), הוא ענין נעלה ביותר [כדמוכח גם ממ\"ש<sup data-n=\"1529\">26</sup> חג הסוכות תעשה לך, שיש מצוה גם בעשיית הסוכה<sup data-n=\"1530\">27</sup>]. ובפרט לפי המבואר בדרושי בעל ההילולא<sup data-n=\"1531\">28</sup> שסכך הסוכה [שהוא עיקר הסוכה, והסוכה נקראת ע\"ש הסכך<sup data-n=\"1532\">29</sup>] נעשה מענן הקטורת דיום הכפורים, וידוע<sup data-n=\"1533\">30</sup> גם דסכך בגימטריא מאה כנגד מאה קולות דשופר שנהגו<sup data-n=\"1534\">31</sup> ישראל (דמנהג ישראל תורה היא<sup data-n=\"1535\">32</sup>) לתקוע בראש השנה. וגם פרטי הקולות מרומזים בהאותיות דסכך, ס' קולות דתקיעה, כ' קולות דשברים וכ' דתרועה<sup data-n=\"1533\">30</sup>. והיינו שההמשכה בראש השנה (מה שממשיכים ע\"י המאה קולות) היא באופן דבכסא (בהעלם), ואח\"כ באה לידי גילוי (ליום חגינו) בחג הסוכות<sup data-n=\"1536\">33</sup> בסכך הסוכה. דכל זה הוא מעלת המקיף דסוכה כמו שהוא מצ\"ע. ואח\"כ צ\"ל בסוכות תשבו, להמשיך המקיף דסוכה בהתיישבות ובפנימיות, והמשכה זו צ\"ל שבעת ימים שכוללים כל ימי ההיקף, ועי\"ז נמשך אח\"כ בשמע\"צ (שהמקיף נכנס בפנימיות ועצרת, ונמשך) מקיף עליון יותר, בחי' יום השמיני ששומר את ההיקף<sup data-n=\"1537\">34</sup>, שעכ\"ז נאמר<sup data-n=\"1538\">35</sup> ביום השמיני עצרת תהי' לכם, יהיו לך לבדך ואין לזרים אתך<sup data-n=\"1539\">36</sup>.\nה) <b>וזהו</b> גם השייכות דנטילת ד' מינים לסוכה, וכנ\"ל שמצות נטילת ד' מינים בסוכה היא מצוה מן המובחר, כי המשכת המקיף דסוכה בבחי' פנימיותוהתיישבות נעשה בעיקר ע\"י נטילת ד' מינים. ויובן זה ע\"פ המבואר בסידור<sup data-n=\"1540\">37</sup> ובדרושי בעל ההילולא<sup data-n=\"1541\">38</sup> שד' מינים אלו רומזים על ענין האחדות. דבלולב כתיב כפות תמרים, ודרשו רז\"ל<sup data-n=\"1542\">39</sup> שצ\"ל כפות, שכל העלים (עם היות שבעצם הם נפרדים זה מזה) צריכים להיות דבוקים ואחוזים זה בזה כאילו הם אחד, וגם כל עלה כפול מב', היינו דב' העלים שבו מתחברים ומתאחדים לעלה אחד. וכן הוא בההדסים שנק' ענף עץ עבות, עבות דוקא, תלתא בחד קינא<sup data-n=\"1543\">40</sup>. וכן הוא בערבי נחל שגדלים באחוה<sup data-n=\"1544\">41</sup>. ומכ\"ש באתרוג שדר באילנו משנה לשנה<sup data-n=\"1545\">42</sup>, דלא רק שסובל את כל שינויי האוירים דד' תקופות השנה (קיץ וחורף קור וחום), אלא שהוא גם גדל מכל ד' אוירים אלו<sup data-n=\"1546\">43</sup>. ויתירה מזו שגידולו בשלימות (של האתרוג) הוא במשך ג' שנים, היינו דענין הנ\"ל (מה שהוא סובל את כל שינויי האוירים וגם גדל מהם) מתחדש בו ג' פעמים<sup data-n=\"1546\">43</sup>, דבג' פעמים הוי חזקה<sup data-n=\"1547\">44</sup>. ועפ\"ז יובן מה שהמשכת המקיף (דסוכה) בפנימיות נעשה בעיקר ע\"י נטילת ד' מינים, כי ענין האחדות שבד' המינים מורה על בחי' הדעת<sup data-n=\"1548\">45</sup> (שלכן נמשך על ידם בחי' הדעת, כנ\"ל מכתבי האריז\"ל). וע\"ד כמו שהוא באדם, דמי שיש לו מוחין דגדלות ודעתו רחבה יכול לסבול גם היפוכו<sup data-n=\"1549\">46</sup>. ובפרט שהאחדות שבד' מינים, ובפרט באתרוג, הוא לא רק שהוא סובל הפכים, אלא שההפכים נעשים למציאות אחת, שזה מורה על <i>ריבוי</i> הדעת. ולכן המשכת המקיף דסוכה בפנימיות נעשה בעיקר ע\"י נטילת ד' מינים, כי דעת הוא ענין הפנימיות, כמבואר בתניא בסיום וחותם פרק שלישי<sup data-n=\"1550\">47</sup> בענין המעלה שבדעת על חכמה ובינה שדעת הוא מלשון התקשרות כו'.\nו) <b>וזהו</b> גם השייכות של ענין האחדות דכל ישראל לענין הסוכה (כל ישראל ראוים לישב בסוכה אחת), כי המקיף דסוכה הוא סובב ומקיף את כל ישראל כאחד, בדוגמת ענני הכבוד (בסוכות הושבתי גו'<sup data-n=\"1551\">48</sup>) שהקיפו את כל ישראל כולם כאיש אחד. וזהו גם בסוכות תשבו, תשבו כעין תדורו<sup data-n=\"1552\">49</sup>, דכמו שהסוכה מקיף את כל ישראל כאחד, מראשיכם שבטיכם עד חוטב עציך ושואב מימיך, עד\"ז הוא בכאו\"א מישראל בפרט, שכל עניניו צריכים להיות בהמקיף דסוכה. ומדייק בסוכות תשבו שכולל (לא רק הפירוש תשבו כעין תדורו אלא) גם הפירוש דהתיישבות, שצריך להמשיך בחי' המקיף דסוכה בבחי' ההתיישבות. ומוסיף למען ידעו גו', שצריך להמשיך זה גםבהשגה, ובהשגה גופא במוח הדעת שבו הוא עיקר ההתיישבות והפנימיות. ומדייק למען ידעו דורותיכם גו', שגם הדורות הבאים (לאחרי הדור שיצאו ממצרים) יקיימו מצות סוכה לא רק במעשה בפועל, אלא שקיום מצוה זו זאָל זיי דורכנעמען בפנימיות, עד שגם יורגש במוח הדעת. ומוסיף שבעת ימים, שהמשכה זו צריכה להיות בכל ז' ימי ההיקף, היינו בכל הבחי' דהשתלשלות עד לבחי' המלכות, וכנ\"ל שע\"י נטילת הד' מינים נמשך הדעת (גם) בנוק', ועד\"ז הוא באדם שבחי' המקיף דסוכה דאַרף דורכנעמען את כל הכוחות שלו עד לכח המעשה שלו (שהרי קיום מצות סוכה צריכה להיות ועיקרה בעשי' בפועל), ומזה באים אח\"כ לביום השמיני עצרת בחי' שמיני שלמעלה מההיקף דהשתלשלות, וגם בחינה זו נמשכת ע\"י הדעת, כי הדעת מחליף מקום הכתר, בחי' אנת<sup data-n=\"1553\">50</sup> הוא חד ולא בחושבן, כמבואר בהמשך וככה<sup data-n=\"1554\">51</sup>.\nז) <b>וממשיך</b> בכתוב כל האזרח בישראל ישבו בסוכות, שבזה הוא מבאר הטעם והכח על העבודה בסוכות תשבו כו'<sup data-n=\"1555\">52</sup>. והענין הוא, אזרח לשון עתיד קאי על בחי' עצם הנשמה שתזרח ותאיר לע\"ל<sup data-n=\"1556\">53</sup>. בחי' איתן שבנשמה כמ\"ש<sup data-n=\"1557\">54</sup> משכיל לאיתן האזרחי, איתן מלשון תוקף ומלשון יושן, והוא התוקף דנשמה הבא מבחי' שם ע\"ב שאינו מחודש (יושן), דלהיות ששם ע\"ב הוא למעלה מתוהו שבו הי' השבירה, לכן נמשך מזה התוקף בכאו\"א מישראל בעבודה הנ\"ל<sup data-n=\"1558\">55</sup>. והגם שגילוי בחי' זו יהי' בעיקר לע\"ל, מ\"מ (ומכיון שבחי' זו היא למעלה מהזמן, לכן) היא פועלת פעולתה גם עכשיו, ובפרט בסוכות. וזהו בסוכות תשבו גו' כל האזרח בישראל ישבו בסוכות, שע\"י בחי' האזרח בישראל שתהי' לעתיד, יש כח גם עכשיו שיהי' בסוכות תשבו<sup data-n=\"1559\">56</sup>, וגם ולקחתם לכם גו' פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל, כולל גם הפירוש<sup data-n=\"1560\">57</sup> פרי עץ הדר זה הקב\"ה כו' כפות תמרים זה הקב\"ה כו' וענף עץ עבות זה הקב\"ה כו' וערבי נחל זה הקב\"ה, כל הדרגות כביכול באלקות, ובאופן דולקחתם לכם שלוקחים את הקב\"ה בבחי' פנימיות, מכיון שישראל (ע\"י אורייתא) וקוב\"ה כולא חד<sup data-n=\"1561\">58</sup>.\n<b>כן</b> תהי' לנו בההכנה למצות סוכה ובקיום מצות סוכה ומצות ד' מינים בשנה זו, ובקרוב ממש בשנה זו נזכה להגילוי בפועל דכל האזרח בישראל ישבו בסוכות, בביאת משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות<sup data-n=\"1562\">59</sup> לארצנו, במהרה בימינו ממש.\n**********",[["1503","*","יצא לאור בשעתו, \"<i>ערחה\"ס</i>,<i> ה'תש\"מ</i>\"."],["1504","1","אמור כג, מב-מג."],["1505","2","ב\"ח או\"ח ר\"ס תרכה."],["1506","3","או\"ח שם."],["1507","4","ראה המשך וככה תרל\"ז פפ\"ד. ד\"ה בסוכות תשבו תש\"ד ותש\"ה. ועוד."],["1508","5","המשך תרס\"ו ע' כה. שסד. ד\"ה בסוכות תשבו תש\"ד. תש\"ה. תש\"י. ועוד."],["1509","6","ד\"ה הנ\"ל תש\"י."],["1510","7","ד\"ה בסוכות שבהערה 5. ועוד."],["1511","8","סוכה כז, ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191361\" data-slug=\"likkutei-sichot\" data-id=\"1300191361\">לקו\"ש חי\"ט ע' 348</a> ואילך."],["1512","9","ר\"פ נצבים. וראה לקו\"ת שם."],["1513","10","פרק לב. וראה גם סהמ\"צ להצ\"צ מצות אהבת ישראל. קונטרס אהבת ישראל."],["1514","11","שבת לא, א."],["1515","12","ראה סהמ\"צ שם כט, ב."],["1516","13","אמור שם, מ."],["1517","14","סידור שער הלולב רסה, סע\"א. המשך תרס\"ו ע' לב. ובכ\"מ."],["1518","15","סידור אדה\"ז לפני הלל."],["1519","16","מ\"ח מס' ימי מצוה וסוכה פ\"ה מ\"ג – הובא ונתבאר בסידור רסג, סע\"ג ואילך. המשך וככה הנ\"ל פפ\"ד ואילך. המשך תרס\"ו שם. ועוד."],["1520","17","חגיגה ו, ריש ע\"ב. ועוד."],["1521","18","שבת צז, א."],["1522","19","לקו\"ת ואתחנן ז, ג."],["1523","20","ראה שמו\"ר רפ\"ג."],["1524","21","ראה בחינות עולם ח\"ח פ\"ב. עיקרים מ\"ב ספ\"ל. של\"ה קצא, ב."],["1525","22","תהלים קד, כג."],["1526","23","סה\"מ אידיש ס\"ע 203."],["1527","24","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a> בתחלתו."],["1528","25","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ\"ז (לד, ב</a>)."],["1529","26","ראה טז, יג."],["1530","27","ורק שאי\"ז גמר המצוה (שו\"ע אדה\"ז או\"ח ר\"ס תרמא)."],["1531","28","וככה הנ\"ל פפ\"ד. וראה גם עט\"ר שער יוהכ\"פ לו, סע\"א ואילך. אוה\"ת סוכות ע' א'תשכב ואילך. ד\"ה והוא כחתן תרנ\"ז פי\"א ואילך. ועוד."],["1532","29","פרש\"י ד\"ה כשרין (סוכה יב, א. וראה פרש\"י שם ב, א ד\"ה ושחמתה). שו\"ע אדה\"ז או\"ח סתרל\"ח ס\"א."],["1533","30","תורת לוי\"צ ע' שג."],["1534","31","שו\"ע אדה\"ז שם סתקצ\"ו ס\"א."],["1535","32","ראה תוד\"ה נפסל – מנחות כ, ב."],["1536","33","ראה סידור רלה, ב. ובכ\"מ. וראה גם לקו\"ת ר\"ה נד, ריש ע\"ד."],["1537","34","שו\"ת הרשב\"א ח\"א ס\"ט."],["1538","35","פינחס כט, לה."],["1539","36","לשון הכתוב – משלי ה, יז. ובד\"ה ביום השמע\"צ תש\"י בסופו הובא זה (ע\"פ שמו\"ר פט\"ו, כג) לענין ביום השמיני עצרת תהי' לכם."],["1540","37","רסא, ג."],["1541","38","וככה הנ\"ל פפ\"ז."],["1542","39","סוכה לב, א."],["1543","40","שם, ב."],["1544","41","ראה שבת כ, א ובפרש\"י שם."],["1545","42","סוכה לה, א."],["1546","43","וככה הנ\"ל פצ\"ד."],["1547","44","ב\"מ קו, ב."],["1548","45","ראה גם סידור (רסה, א. וככה הנ\"ל פצ\"ג), השייכות דענין האחדות (שבד' המינים) להמשכת הדעת."],["1549","46","ראה וככה הנ\"ל פצ\"ד."],["1550","47","והרי דעת היא ספירה השלישית."],["1551","48","ראה סוכה יא, ב (לפי דיעה אחת) שענני כבוד היו. וכ\"ה בפרש\"י עה\"פ. וכ\"ה להלכה (שו\"ע אדה\"ז שם ר\"ס תרכה)."],["1552","49","סוכה כח, ב."],["1553","50","הקדמת תקו\"ז – פתח אליהו."],["1554","51","פצ\"ג."],["1555","52","ד\"ה בסוכות תשבו תש\"ג בסופו."],["1556","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת ראה יח, א</a>. שמע\"צ פח, ג."],["1557","54","תהלים פט, א. וראה לקו\"ת ראה שם. יהל אור לתהלים שם. מקומות שבהערה הבאה."],["1558","55","ראה בארוכה ד\"ה לעולם יהא אדם תש\"ג בתחלתו. קונטרס לימוד החסידות פ\"ג. וש\"נ."],["1559","56","כ\"מ גם בד\"ה בסוכות הנ\"ל שם."],["1560","57","ויק\"ר פ\"ל, ט."],["1561","58","ראה זח\"ג עג, א."],["1562","59","דשייך לבחי' אזרח הנ\"ל, כמובן בדרושים עה\"פ."]]],[1500360024,"<h3>בס\"ד. אור לי\"ג תשרי, הילולא דאדמו\"ר מהר\"ש נ\"ע, ה'תשמ\"א<sup data-n=\"1563\">*</sup></h3>\n<b>בסוכות</b> תשבו שבעת ימים גו' למען ידעו דורותיכם כי בסוכות הושבתי את בני ישראל בהוציאי אותם מארץ מצרים<sup data-n=\"1564\">1</sup>. הנה פסוק זה מביא רבינו הזקן בשו\"ע ריש הלכות סוכה<sup data-n=\"1565\">2</sup> ומדייק בלשונו הזהב (דבסוכות הושבתי גו') הם היו ענני כבודו שהקיפם בהם לצל כו'<sup data-n=\"1566\">3</sup> ודוגמא לזה צונו לעשות סוכות העשויות לצל. ומבאר אדמו\"ר מהר\"ש בעל ההילולא בהמאמרים דחג הסוכות שנאמרו לפני מאה שנה<sup data-n=\"1567\">4</sup>, דסכך הסוכה נעשה מענן הקטורת דיוהכ\"פ<sup data-n=\"1568\">5</sup>, דענן הוא כמו צל. אלא שביום הכפורים הוא בהעלם עדיין (בכסא<sup data-n=\"1569\">6</sup>), ובא בגילוי ליום חגינו<sup data-n=\"1569\">6</sup>, בחג הסוכות<sup data-n=\"1570\">7</sup>. והנה בסוכה צ\"ל צלתה מרובה מחמתה<sup data-n=\"1571\">8</sup>, היינו שבסוכה יש גם חמתה<sup data-n=\"1572\">9</sup>, אלא שצלתה צ\"ל מרובה מחמתה. ועד\"ז ביוהכ\"פ יש גם הענין דחמתה, אלא שעיקר העבודה דיוהכ\"פ הוא ענין הצל. דהנה ב' הענינים דחמתה וצלתה בהעבודות בביהמ\"ק, ועד\"ז בתפלות שבמקום קרבנות תקנום<sup data-n=\"1573\">10</sup>, הם עבודת הקרבנות ועבודת הקטורת<sup data-n=\"1574\">11</sup>. דבקרבנות כתיב<sup data-n=\"1575\">12</sup> לחמי לאשי גו', ואשי, אש שבאה מן ההדיוט וגם אש שירד מן השמים<sup data-n=\"1576\">13</sup>, הו\"ע החום, חמתה. ועבודת הקטורת, שעיקרה הוא הענן, הו\"ע צלתה כנ\"ל. וזהו מה שביוהכ\"פ יש הענין דחמתה, שהרי גם אז יש עבודת הקרבנות. אלא שעיקר העבודה דיוהכ\"פ היא העבודה דקטורת, בחי' צל, ומזה נמשך גם בסוכות, ליום חגינו, שצ\"ל צלתה מרובה מחמתה.ב) <b>וביאור</b> ההפרש בין קרבנות לקטורת, יובן משמם אשר יקראו להם בלשון הקודש [כתורת הבעש\"ט הידועה<sup data-n=\"1577\">14</sup>]. הנה קרבן הוא מלשון קירוב<sup data-n=\"1578\">15</sup>, וכמו שמבאר כ\"ק מו\"ח אדמו\"ר בדרושי ההילולא שלו<sup data-n=\"1579\">16</sup> שקרבנות הו\"ע קירוב הכחות והחושים, ורזא דקורבנא עולה עד רזא דא\"ס<sup data-n=\"1580\">17</sup>. וקטורת הוא לשון קשר [כי כל קשר שבפסוק מתורגם בלשון קטר<sup data-n=\"1581\">18</sup>], דלא רק שהוא מקורב לאלקות, ומקורב בתכלית הקירוב, אלא שהוא גם מקושר עם אלקות, ומקושר בתכלית. וההפרש בין קירוב (קרבנות) והתקשרות (קטורת) הוא, דכאשר הוא מקורב לאלקות גם כשהוא מקורב בתכלית הקירוב, הוא בבחי' מציאות עדיין. וזהו שבקרבנות כתיב לחמי לאשי [והעבודה דקרבנות הו\"ע חמתה, כנ\"ל], כי העבודה דקרבנות היא בדרך כלל עבודה שע\"פ טעם ודעת<sup data-n=\"1582\">19</sup>, וגם זה שנמשך מלמעלה ע\"י עבודה זו, נחת רוח לפני שאמרתי ונעשה רצוני<sup data-n=\"1583\">20</sup>, שייך לטעם ודעת, והאהבה שע\"פ טעם ודעת היא בבחי' מורגש<sup data-n=\"1584\">21</sup>, ולכן שייך בה בחי' חום, ותוקפו שלהובא<sup data-n=\"1585\">22</sup> דרחימותא&lt;11&gt;. משא\"כ העבודה דקטורת היא בדרך כלל העבודה ברעותא דלבא שלמעלה מטעם ודעת<sup data-n=\"1586\">23</sup>, שבבחי' זו אין שייך ענין המורגש. וזהו שקטורת הוא לשון קשר, שהוא ההתקשרות והדביקות באוא\"ס ב\"ה בלי שום הרגש&lt;11&gt;, שאינו שום מציאות לעצמו וכל מציאותו הוא רק מה שהוא מקושר עמו, עד שנעשים כולא חד. ובלשון הידוע<sup data-n=\"1587\">24</sup> בחד קטירא אתקטרנא בי' בקוב\"ה בי' אחידא [דהגם שממשיך גם בי' להיטא, הרי מכיון שבי' להיטא (שם) הוא לאחרי בי' אחידא אין בזה הרגש], דענין בי' אחידא הוא שנעשה חד ממש עם אור אין סוף.\n<b>וזהו</b> גם שהקרבנות היו מקריבים על מזבח החיצון, והקטורת הי' על מזבח הפנימי<sup data-n=\"1588\">25</sup>. דהנה ידוע שב' מזבחות אלה בנפש האדם הם חיצוניות הלב ופנימיות הלב,כמבואר בלקו\"ת<sup data-n=\"1589\">26</sup> ובארוכה בדרושי כ\"ק אדמו\"ר הצ\"צ<sup data-n=\"1590\">27</sup>. ולכן עבודת הקרבנות היא במזבח החיצון, כי העבודה שבבחינת התלהבות היא בחיצוניות הלב. וגם לפי שבחיצוניות הלב שייך ענין הבירורים, היינו שיש עדיין מציאות שצריך לבררו ולהעלותו לקדושה. משא\"כ פנימיות הלב היא למעלה מענין הבירורים, והעבודה דפנימיות הלב היא האהבה וההתקשרות שמצד עצם הנשמה שלמעלה מטעם ודעת<sup data-n=\"1591\">28</sup>.\nג) <b>והנה</b> החילוק שבין עבודת הקרבנות להעבודה דקטורת היא גם בנוגע להדברים המתבררים על ידם. דקרבנות הם מדברים המותרים דוקא<sup data-n=\"1592\">29</sup>, וכמו כל הענינים דתומ\"צ שלא הוכשר למלאכת שמים אלא טהורים ומותרים בפיך<sup data-n=\"1593\">30</sup>. משא\"כ בסממני הקטורת היו גם דברים טמאים, וכמו המור שהיא דם של חי' ידוע<sup data-n=\"1594\">31</sup>. וגם<sup data-n=\"1595\">32</sup> בקטורת צ\"ל י\"א סממנים דוקא (ועד שאם חיסר אחד מכל סממני' חייב מיתה<sup data-n=\"1596\">33</sup>, היפך הענין דקטורת<sup data-n=\"1597\">34</sup>), דמספר י\"א הוא בסט\"א. דהנה ידוע דבקדושה הוא מספר עשר כמאמר<sup data-n=\"1598\">35</sup> עשר ולא תשע עשר ולא אחד עשר, ומספר י\"א הוא בסט\"א, י\"א כתרין דמסאבותא<sup data-n=\"1599\">36</sup>. והענין הוא, דהנה כתיב<sup data-n=\"1600\">37</sup> ואתה מחי' את כולם, אל תקרי מחי' אלא מהוה<sup data-n=\"1601\">38</sup>, שכל הנבראים שבעולם חיותם וגם עצם מציאותם היא מאוא\"ס, ומצד עצמם אינם שום מציאות כלל. וכמו שמבאר בעל ההילולא בד\"ה מי כמוכה באלים הוי' מי כמוך נאדר בקודש<sup data-n=\"1602\">39</sup> (שהי' אומרו פעם בשתים או בשלש שנים כדי לטהר את אויר העולם<sup data-n=\"1603\">40</sup>), דהגם שהעולם הוא מציאות ולא אחיזת עינים, מ\"מ לית בר מינך<sup data-n=\"1604\">41</sup>, לפי שעיקר ואמיתית מציאותו של כל דבר הוא הכח האלקי המהוה אותו. דמזה מובן, שגם הסט\"א וגקה\"ט הכרח לומר שנמשך להם חיות מאוא\"ס, דאל\"כ לא היו שום מציאות כלל. אלא שהחיות המחי' אותם הוא בבחי' מקיף עליהם מלמעלה. [דהגם שיש ניצוץ דקדושה גם בפנימיותם, הרי ניצוץ זה הוא בבחי' גלותבתוכם (ועד שגם הניצוץ עצמו נעשה כמו רע כמו שמבאר אדמו\"ר (מהורש\"ב) נ\"ע בד\"ה פדה בשלום נפשי<sup data-n=\"1605\">42</sup>), וזה שהם חיים וקיימים הוא מהחיות דקדושה שבבחי' מקיף עליהם מלמעלה<sup data-n=\"1606\">43</sup>]. וזהו שבקדושה הוא מספר עשר ובסט\"א מספר י\"א. דהנה כל דבר שבעולם הוא מורכב מעשר ענינים כמ\"ש בפרדס<sup data-n=\"1607\">44</sup>, ולכן בקדושה הוא מספר עשר, לפי שהחיות מתאחד עם הדבר שמחי' אותו ואינו נמנה בפ\"ע. משא\"כ בקליפות וסט\"א שהחיות הוא בבחי' מקיף עליהם מלמעלה לכן החיות נמנה בפ\"ע<sup data-n=\"1608\">45</sup>. וזהו שבקטורת צ\"ל י\"א סממנים דוקא, כי ע\"י העבודה דקטורת, גם הסט\"א שהיא במספר י\"א נהפכת לקדושה. ויש לומר, דחילוק זה שבין עבודת הקרבנות לעבודת הקטורת בנוגע להדברים המתבררים על ידם הוא מצד החילוק שביניהם בהאדם העובד, שהעבודה דקרבנות היא בחיצוניות הלב והעבודה דקטורת היא בפנימיות הלב. והענין הוא, שכאשר העבודה היא במדידה והגבלה והאדם העובד הוא בבחי' מציאות עדיין, צ\"ל זהירות שלא תהי' בעבודתו שום נגיעה, ועאכו\"כ שלא תהי' נגיעה מענינים השייכים להמציאות שלו. משא\"כ כשהעבודה היא למעלה ממדידה והגבלה הנה ע\"י עבודה זו, גם הרע נהפך לטוב<sup data-n=\"1609\">46</sup>, כמו בתשובה שהזדונות נעשות לא רק כשגגות אלא כזכיות<sup data-n=\"1610\">47</sup> [ועד שנעשים לא רק כזכיות (בכ\"ף הדמיון) אלא זכיות ממש<sup data-n=\"1611\">48</sup>], כמבואר בארוכה בתו\"א<sup data-n=\"1612\">49</sup>.\n<b>וזהו</b> גם הקישור והשייכות דעבודת הקטורת ליוהכ\"פ, כי התשובה דיוהכ\"פ היא עצם ענין התשובה (תשובה עילאה)<sup data-n=\"1613\">50</sup>, וכללות העבודה דעשרת ימי תשובה [ומכ\"ש דיוהכ\"פ<sup data-n=\"1614\">51</sup>] היא בבחי' יחידה, וכידוע תורת אדמו\"ר הזקן<sup data-n=\"1615\">52</sup> בפירוש מאמר רז\"ל<sup data-n=\"1616\">53</sup> כאן ביחיד שהעבודה דעשי\"ת היא בבחי' יחידה, ומכיון שכנגד בחי' יחידה לא יש בלעו\"ז, בבואה דבבואה לית להו<sup data-n=\"1617\">54</sup>, לכן ע\"י העבודה והתשובה דיוהכ\"פ גם הזדונות נהפכים לזכיות.\nד) <b>וזהו</b> בסוכות תשבו גו' למען ידעו דורותיכם כי בסוכות הושבתי גו', דידיעה זו היא (לא רק ענין בכוונת המצוה, אלא גם) חלק בקיום המצוה<sup data-n=\"1618\">55</sup> (כדמוכחגם מלשון אדמו\"ר הזקן בשלחנו<sup data-n=\"1619\">56</sup>). דהנה סכך הסוכה נעשה (כנ\"ל) מענן הקטורת דיוהכ\"פ [והשייכות דסוכה לענן הקטורת היא הן מצד זה שהסוכה היא עשוי' לצל וענן הוא כמו צל (כנ\"ל), וגם מצד זה שבסוכות הושבתי הם <i>ענני</i> הכבוד], דענין ענן הקטורת דיוהכ\"פ הוא בחי' המקיף שלמעלה מטעם ודעת, ובחג הסוכות צריך להמשיך מקיף זה בפנימיות, בסוכות <i>תשבו</i>, וההמשכה בפנימיות היא ע\"י הדעת דוקא, כמבואר בארוכה בהמשך וככה של בעל ההילולא<sup data-n=\"1620\">57</sup>. ובפרט ע\"י נטילת ד' מינים, שמורים על ענין האחדות<sup data-n=\"1621\">58</sup>, שעי\"ז נמשך הדעת (גם בבחי' נוקבא<sup data-n=\"1622\">59</sup>) למטה יותר, בפנימיותו של כאו\"א מישראל<sup data-n=\"1623\">60</sup>.\nה) <b>וביאור</b> הענין בעומק יותר יובן ע\"פ מה שמבאר בעל ההילולא בהמשך המאמרים הנ\"ל<sup data-n=\"1624\">61</sup> בענין ירידת הנשמה בגוף, ועד\"ז בענין ירידת המצוות והתלבשותם בדברים גשמיים [וכמו במצות הקרבנות שצריך להקריב בהמה גשמית דוקא, וכן הקטורת היא מי\"א סממנים גשמיים דוקא, וכן סכך הסוכה (שהוא דוגמת ענין הקטורת) הוא מדבר גשמי מפסולת גורן ויקב<sup data-n=\"1625\">62</sup>, ועד\"ז הוא בשאר המצוות], שהיא ירידה צורך עלי'. דשרש הנשמה היא מבחי' התיקון, ושרש הגוף ונה\"ב, וכן שרש הדברים הגשמיים שבהם נתלבשו המצוות, הוא בבחי' התוהו שקדם לתיקון. וע\"י שהנשמה יורדת למטה ומתלבשת בגוף ונה\"ב ועוסקת בתומ\"צ שנתלבשו בדברים גשמיים, עי\"ז היא מבררת את הניצוצות דתוהו שנפלו למטה בהגוף ונה\"ב ובדברים הגשמיים (שהמצוות מלובשות בהם) ומעלה אותם לשרשם, ועי\"ז נמשך להם האורות דתוהו שלמעלה מהאורות דתיקון, כידוע שהאורות דתיקון הם אורות מועטים ובתוהו היו אורות מרובים<sup data-n=\"1626\">63</sup>. ובפרט לפי המבואר שם<sup data-n=\"1627\">64</sup> שריבוי האור דתוהו הוא לא רק ריבוי בכמות (היינו שהוא באותו הסוג של האורות דתיקון ורק שהוא בריבוי גדול מאד), כי אם, שהאורות דתוהו הם בסוג אחר לגמרי. ובמכ\"ש מזה שאמרו רז\"ל<sup data-n=\"1628\">65</sup> על אור שנברא ביום הראשון שהי' אדם מביט בו מסוף העולם ועד סופו, שביאור הלשון מסוף העולם ועד סופו (אף שלכאורה הי' צ\"ל מתחלת העולם ועד סופו) הוא דכללות כל העולמות נחלקים לב' בחינות, עלמא דאתכסיא ועלמא דאתגליא, והכוונה במסוף העולם ועד סופו היא מסוף העולם דעלמא דאתגליאמלמעלמ\"ט ועד סופו דעלמא דאתכסיא מלמטלמ\"ע, דמזה מובן שענין הריבוי דאור זה (אור שנברא ביום הראשון) לגבי האור דשאר הימים הוא לא רק ריבוי בכמות אלא שהוא ריבוי שאינו בערך כלל. וכל זה הוא בעולם התיקון גופא [שהרי גם אור שנברא ביום ראשון הוא מבחי' התיקון], שכללות האורות דתיקון הם אורות מועטים. ומזה מובן במכ\"ש בענין ריבוי האור שהי' בבחי' התוהו, שנוסף על הריבוי בכמות, הי' (וזהו <i>עיקר</i> מעלתו) אור נבדל בערך לגמרי מהאור דתיקון. וע\"י שהנשמה, ששרשה מבחי' התיקון, מבררת ומתקנת את הניצוצות שנפלו למטה בדברים הגשמיים, עי\"ז נמשכים האורות מרובים דתוהו בכלים מרובים דתיקון.\n<b>וזהו</b> שירידת הנשמה בגוף היא ירידה צורך עלי', דשרש הנשמה הוא (כנ\"ל) בבחי' התיקון [אלא שבתיקון גופא היא בבחי' הכי עליונה, דישראל <i>עלו</i> במחשבה<sup data-n=\"1629\">66</sup>], וע\"י שיורדת מאיגרא<sup data-n=\"1630\">67</sup> רמה לבירא עמיקתא ומבררת את הניצוצות שנפלו למטה מטה (לבירא עמיקתא), דזה גופא שנפלו למטה מטה ביותר הוא מצד זה ששרשם הוא למעלה מעלה ביותר<sup data-n=\"1631\">68</sup>, עי\"ז נעשה בה תוספת עילוי למעלה יותר מכמו שהיתה קודם ירידתה<sup data-n=\"1632\">69</sup>. וכידוע תורת האריז\"ל עה\"פ כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם<sup data-n=\"1633\">70</sup>, דזה שהלחם מחי' את האדם (אף שהלחם הוא צומח והאדם הוא מדבר) הוא לא מצד הלחם לבדו, כי אם, מצד מוצא פי הוי' שבהלחם, היינו מהמאמר<sup data-n=\"1634\">71</sup> תדשא הארץ דשא. וזה שהאדם צריך להמוצא פי הוי' שבהלחם דוקא (אף שגם באדם מלובש דבר הוי' מהמאמר<sup data-n=\"1635\">72</sup> נעשה אדם) הוא לפי שמוצא פי הוי' שבהלחם הוא מבחי' התוהו, ולכן על ידו דוקא יחי' האדם שמבחי' התיקון. וכמו שהוא בלחם, עד\"ז הוא בכל עניני האדם [דלחם כולל כל עניני אכילה ושתי'<sup data-n=\"1636\">73</sup> וגם כל צרכי האדם<sup data-n=\"1637\">74</sup>], כולל גם עבודת האדם בתומ\"צ, שע\"י שהאדם מברר את הדברים הגשמיים [ע\"י שעושה אותם לשם שמים<sup data-n=\"1638\">75</sup>, ועאכו\"כ ע\"י קיום המצוות בדברים הגשמיים עצמם], הנה על מוצא פי הוי' שבדברים הגשמיים יחי' האדם, שמתוסף עילוי בנשמת האדם למעלה יותר מכמו שהיתה קודם ירידתה. ומכיון שהאור דתוהו הוא נבדל בערך לגמרי (כנ\"ל), לכן גם העילוי שמתוסף בהנשמה הוא עילוי שלא בערך כלל<sup data-n=\"1639\">76</sup>.ו) <b>ועפ\"ז</b> יובן בעומק יותר גודל העילוי דעבודת הקטורת על עבודת הקרבנות, כי ע\"י העבודה דקטורת מתבררים גם הניצוצות שנפלו בגקה\"ט, ועד שגם זדונות נעשות כזכיות, ומכיון שכל שנפל למטה מטה ביותר מורה ששרשו הוא למעלה מעלה ביותר, הרי מובן<sup data-n=\"1640\">77</sup> שניצוצות אלו (שנפלו בגקה\"ט ובפרט בזדונות) הם מלמעלה יותר גם מהניצוצות ודברים הגשמיים (המותרים) שמתבררים ע\"י עבודת הקרבנות. והיינו שבתוהו גופא הם בבחי' נעלית יותר. דזהו שאמרו רז\"ל<sup data-n=\"1641\">78</sup> במקום שבעלי תשובה עומדין אין צדיקים גמורין יכולים לעמוד בו, לפי שבעלי תשובה מבררים מגקה\"ט וצדיקים גמורים מבררים רק מנוגה<sup data-n=\"1642\">79</sup>. וזהו גם שהגילויים דלע\"ל תלויים (בעיקר) במעשינו ועבודתנו במשך זמן הגלות<sup data-n=\"1643\">80</sup> דוקא [ובזמן הגלות גופא בהזמן דעקבתא דמשיחא], כי עיקר הענין די\"א כתרין דמסאבותא הוא בזמן הגלות [ובפרט בעקבתא דמשיחא], ולכן ע\"י מעשינו ועבודתנו בזמן הגלות ממשיכים אור בלתי מוגבל, אלה תולדות פרץ<sup data-n=\"1644\">81</sup> תולדות מלא<sup data-n=\"1645\">82</sup>, שהוא נעלה יותר גם מתולדות מלא שהי' בעת הבריאה<sup data-n=\"1646\">83</sup> (אלה תולדות השמים והארץ בהבראם<sup data-n=\"1647\">84</sup>), שעולם על מילואו נברא<sup data-n=\"1648\">85</sup>.\n<b>וזהו</b> גם מעלת הקטורת דיוהכ\"פ על הקטורת דכל השנה, כי הקטורת דיוהכ\"פ הו\"ע התשובה שזדונות נעשות כזכיות<sup data-n=\"1649\">86</sup> [כי העבודה דיוהכ\"פ היא בבחינת יחידה שבנפש, והיינו דבעשי\"ת גופא (כאן ליחיד) הנה עיקר הגילוי (והעבודה) דבחינת יחידה הוא ביום הכפורים אחת בשנה<sup data-n=\"1650\">87</sup>, וזה שזדונות נעשות לזכיות ממש הוא על ידי העבודה דבחי' יחידה], וענין זה [שזדונות נהפכים לזכיות] מגיע בבחי' פנימיות עתיק<sup data-n=\"1649\">86</sup>. וגם ענין זה שייך ליוהכ\"פ, כידוע<sup data-n=\"1651\">88</sup> דביוהכ\"פ הוא עליית המלכות בבחי' עתיק. וזה נעשה גם הכנה והקדמה להגילוי דלע\"ל [שיהי' ג\"כ ע\"י עבודת התשובה דוקא, כמאמר<sup data-n=\"1652\">89</sup> משיח אתא לאתבא צדיקייא בתיובתא], שאז יהי' הגילוי דפנימיות עתיק<sup data-n=\"1653\">90</sup>.ז) <b>והנה</b> כל העילויים הנ\"ל שנעשים בהנשמה ע\"י העבודה בעוה\"ז דוקא, ובעוה\"ז גופא במשך זמן הגלות, היו בה גם לפני ירידתה. וכמובן מתורת הרב המגיד<sup data-n=\"1654\">91</sup> בפירוש מאמר רז\"ל&lt;66&gt; ישראל עלו במחשבה, שהוא כמשל הבן שצורתו חקוקה במחשבת האב, ומכיון שאצל השי\"ת העבר והעתיד אחד לכן גם קודם שנבראו ישראל הי' נחקק צורתם במחשבה. דמזה מובן, שגם העילוי שנעשה בהנשמה ע\"י ירידתה מאיגרא רמה לבירא עמיקתא ועבודתה שם בבחי' עומק ופנימיות הלב, ובזה גופא בדרגא הכי נעלית (עצמות נקודת הלב)<sup data-n=\"1655\">92</sup>, שעי\"ז היא מתעלית למעלה יותר מכפי שהיתה בשרשה בבחי' האלקים אשר נתנה<sup data-n=\"1656\">93</sup>, גם צורה זו (של הבן, כמו שהוא בתכלית השלימות) היתה חקוקה במחשבתו ית'. אלא שזהו בכח, ובכדי שיהי' עילוי זה בפועל<sup data-n=\"1657\">94</sup>, הנה זה נעשה ע\"י ירידתה למטה ועבודתה בפועל בלימוד התורה ובקיום המצוות, ובפרט ע\"י העבודה דקטורת דיוהכ\"פ שהיא עבודת התשובה, וע\"י הישיבה בסוכה ונטילת ד' מינים שעי\"ז נעשה המשכת וגילוי המקיף דענן הקטורת דיוהכ\"פ. ועד\"ז בהימים שבין יוהכ\"פ לסוכות, דזה עוסק בסוכתו וזה בלולבו<sup data-n=\"1658\">95</sup>. דזהו הטעם של זה שיום א' דסוכות הוא ראשון לחשבון עונות<sup data-n=\"1659\">96</sup>, לפי שבמשך ד' ימים אלו כל ישראל עסוקים (רק) במצוות, ובמילא אין שייך שיעשו איזה דבר בלתי רצוי. ומובן, דכאשר ד' ימים אלו הם כדבעי הנה גם לאחרי שמתחיל החשבון, הוא באופן אחר לגמרי, וע\"ד הידוע בענין מה שגם צדיקים גמורים אומרים על חטא<sup data-n=\"1660\">97</sup>, חטא מלשון חסרון<sup data-n=\"1661\">98</sup>, בדקות דדקות. ומ\"ש ראשון לחשבון עונות הכוונה בזה היא לא לעונות כפשוטם (כולל גם מי שיש בידו למחות ולא מיחה<sup data-n=\"1662\">99</sup>) אלא לעונות מלשון עיוות ועיקום, ועד שגם זה אינו שייך, ועיוות ועיקום הוא בתכלית הדקות, וכמו שנתבאר לעיל<sup data-n=\"1663\">100</sup> בפירוש הכתוב<sup data-n=\"1664\">101</sup> כי כשלת בעונך. ועי\"ז, הנה גם הקטורת דיוהכ\"פ, שענינה הוא תשובה דזדונות נהפכים לזכיות, הוא ג\"כ על עונות (וזדונות) שבתכלית הדקות. ולאחרי יוהכ\"פ ממשיכים בחי' המקיף דענן הקטורת בהענינים דסוכה ולולב כמו שהם דברי הרשות עדיין וישראל מכינים ומכשירים אותם למצוה, ובפרט לאחרי שמקיימים בהם מצות ישיבה בסוכה ונטילת ד' מינים בחג הסוכות זמן שמחתנו, ונמשך שמחה על כל השנהכולה<sup data-n=\"1665\">102</sup>, שמחה תמידית<sup data-n=\"1666\">103</sup>, שעובדים את ה' בתמידות בשמחה ובטוב לבב<sup data-n=\"1667\">104</sup>, וזה נעשה הכנה קרובה לשמחת עולם על ראשם<sup data-n=\"1668\">105</sup> שתהי' בגאולה האמיתית והשלימה ע\"י משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, במהרה בימינו ממש.\n**********",[["1563","*","יצא לאור ב<b>קונטרס חג הסוכות – תשמ\"ח</b>, \"לקראת חג הסוכות . . <i>י\"ג תשרי שנת תשמ\"ח</i>\"."],["1564","1","אמור כג, מב-מג."],["1565","2","סי' תרכה."],["1566","3","ראה סוכה יא, סע\"ב. תו\"כ עה\"פ אמור שם, מג. תיב\"ע, ת\"א ופרש\"י עה\"פ אמור שם. וראה גם מכילתא עה\"פ בא יב, לז. בשלח יג, כ. תנחומא עה\"פ בא שם (סי' ט). ועוד."],["1567","4","משנת אמירת מאמר זה (תשמ\"א), בד\"ה סוכה שחמתה כו' תרמ\"א. וראה גם מאמר דפ' וירא תרמ\"א (נדפס בהמשך יונתי תר\"ם ע' נד ואילך) ס\"ע נו."],["1568","5","ראה גם עט\"ר שער יוהכ\"פ פ\"ב (כח, א). שם לו, סע\"א ואילך. מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' א'קלד. שם ע' א'קמ. אוה\"ת סוכות ע' א'תשכב ואילך. המשך וככה תרל\"ז פפ\"ד (ע' קלז). ד\"ה והוא כחתן תרנ\"ז פי\"א ואילך (סה\"מ תרנ\"ז ע' קסב ואילך). ועוד."],["1569","6","לשון הכתוב – תהלים פא, ד.\nבתהלים שם: בכס<i>ה</i> (בה\"א), אבל כ\"ה (בכס<i>א</i>, באל\"ף) בלקו\"ת, סידור, ומאמרי אדמו\"ר האמצעי שבהערה הבאה (<i>ובכ\"מ</i> בדא\"ח). וכ\"ה בביצה טז, א. שאילתות פ' בא שאילתא מו. וראה אוה\"ת לתהלים (יהל אור) עה\"פ (ע' רפה ואילך)."],["1570","7","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380937\" data-slug=\"likkutei-torah\" data-id=\"4001380937\">ראה ד</a>\"ה תקעו בלקו\"ת דרושים לר\"ה נד, סע\"ג ואילך; סידור (עם דא\"ח) שער ר\"ה רלה, ב; עט\"ר דרוש לעשי\"ת נז, א; מאמרי אדמו\"ר האמצעי שם ע' א'ה ואילך. ובכ\"מ."],["1571","8","סוכה כב, א. רמב\"ם הל' סוכה פ\"ה הי\"ט. טושו\"ע (ודאדה\"ז) או\"ח הל' סוכה סתרל\"א."],["1572","9","ראה ב\"ח וב\"י לטור שם (ד\"ה וצריך). שו\"ע אדה\"ז שם ס\"ה, מט\"ז שם סק\"ב."],["1573","10","ראה ברכות כו, ב. זח\"ב כ, ב."],["1574","11","מאמר דפ' וירא הנ\"ל ס\"ע נו."],["1575","12","פינחס כח, ב."],["1576","13","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381038\" data-slug=\"likkutei-torah\" data-id=\"4001381038\">ראה עירובין סג, א</a>. יומא כא, ב. תו\"כ (הובא בפרש\"י) עה\"פ ויקרא א, ז. רמב\"ם הל' תמידין ומוספין רפ\"ב. וראה לקו\"ת דרושים לסוכות ד\"ה ושאבתם הא' (עח, סע\"ג ואילך)."],["1577","14","שעהיוה\"א בתחלתו."],["1578","15","ראה ספר הבהיר סי' מו (קט). הובא ברקאנטי עה\"פ בראשית ד, ג (טז, א). תצוה כט, יח (טו, א). ובשל\"ה ריא, ב. וראה זח\"ג ה, רע\"א (הובא בשל\"ה שם). וראה פע\"ח שער א (שער התפלה) פ\"ה. בחיי עה\"פ ויקרא א, ט. רמב\"ן עה\"פ שם בסופו."],["1579","16","ד\"ה באתי לגני ה'שי\"ת פ\"ב (סה\"מ ה'שי\"ת ע' 113). וראה גם ד\"ה טעמה ה'תש\"ט פ\"ב (סה\"מ ה'תש\"ט ע' 29 (השני))."],["1580","17","ראה זהר ח\"ב רלט, א. ח\"ג כו, ב. הובא בהמשך באתי לגני הנ\"ל פי\"ח (סה\"מ שם ס\"ע 153). ד\"ה טעמה הנ\"ל רפ\"ד (סה\"מ שם ע' 31 (השני))."],["1581","18","אוה\"ת תולדות קנב, סע\"א. מאמר דפ' וירא הנ\"ל שם."],["1582","19","המשך תער\"ב ח\"א פ' ריב. שם פ' ריח (ע' תכט ואילך. שם ע' תמא)."],["1583","20","פרש\"י עה\"פ ויקרא א, ט. ספרי (הובא בפרש\"י) עה\"פ פינחס כח, ח."],["1584","21","המשך תער\"ב הנ\"ל פ' ריז (ע' תלט)."],["1585","22","ראה זח\"ג פד, א."],["1586","23","המשך תער\"ב הנ\"ל פ' ריב. שם פ' רכא (ע' תכט ואילך. שם ס\"ע תמו ואילך)."],["1587","24","לשון זה (בחד קטירא . . בי' להיטא) הובא בכ\"מ בדא\"ח, ולע\"ע מצאתיו באדרא זוטא (זח\"ג רפח, א): פתח ר\"ש ואמר כו' בחד קטירא אתקטרנא בי' בקוב\"ה כו'. ושם (רצב, א): נשמתי בי' אחידא בי' להיטא.\nוראה המשך יונתי שם. המשך תער\"ב הנ\"ל פ' ריב."],["1588","25","ראה גם המשך יונתי שם ע' נז."],["1589","26","דרושים לסוכות עח, ד."],["1590","27","אוה\"ת ויקהל ע' ב'רה ואילך (וראה גם סה\"מ תקס\"ד ע' סו ואילך). סהמ\"צ להצ\"צ מצות בנין מקדש פ\"ב (דרמ\"צ פז, א). וראה גם המשך תער\"ב הנ\"ל שם."],["1591","28","ראה בכ\"ז – אוה\"ת שם. דרמ\"צ שם (פו, ב ואילך). המשך תער\"ב שם."],["1592","29","ראה מנחות ה, ב ואילך. רמב\"ם הל' איסורי המזבח פ\"ב ה\"י. פ\"ה ה\"ט."],["1593","30","ראה שבת כח, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["1594","31","רמב\"ם הל' כלי המקדש פ\"א ה\"ג. וראה מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' א'קלו. וש\"נ."],["1595","32","בהבא להלן ראה גם מאמרי אדמו\"ר האמצעי שם ע' א'קלד ואילך."],["1596","33","כריתות ו, א. ירושלמי יומא פ\"א ה\"ה. פ\"ד ה\"ה. רמב\"ם הל' כלי המקדש פ\"ב ה\"ח."],["1597","34","ראה פרש\"י עה\"פ קרח יז, יג."],["1598","35","ספר יצירה פ\"א מ\"ד. וראה זח\"ב קפז, ב. פרדס שער א (שער עשר ולא תשע) פ\"ו."],["1599","36","ראה ע\"ח שער יא (שער המלכים) פ\"י. פע\"ח שער ו (שער הקדישים) פ\"ד. וראה בהנסמן להלן בהערה 45."],["1600","37","נחמי' ט, ו."],["1601","38","שעהיוה\"א פ\"ב. וראה פרדס שער ו (שער סדר עמידתן) פ\"ח. ר\"ח שער הקדושה ספ\"ז. של\"ה מח, ב. ע, א."],["1602","39","תרכ\"ט. נדפס בסה\"מ תרכ\"ט ע' קמג ואילך. – ראה שם ע' קמח-קמט."],["1603","40","\"היום יום\" כ\"ח תמוז. הוספות לסה\"מ תרנ\"ט ע' רכב. אגרות-קודש לכ\"ק אדמו\"ר מהוריי\"צ נ\"ע כרך ו ע' רסז."],["1604","41","תרגום אונקלוס עה\"פ (בשלח טו, יא)."],["1605","42","דשנת תרע\"ה (בהמשך תער\"ב ח\"ב ריש ע' תשע). וראה גם סה\"מ עת\"ר ריש ע' קג."],["1606","43","ראה המשך תער\"ב ח\"א ר\"פ רי (ע' תכד). וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370095\" data-slug=\"torah-or\" data-id=\"3901370095\">תו\"א תולדות כ, רע\"ג</a>."],["1607","44","שער ב (שער טעם האצילות)."],["1608","45","ראה בכ\"ז – תו\"א שם, סע\"ב ואילך. ובהגהות הצ\"צ לשם (אוה\"ת תולדות קנב, א ואילך). מאמרי אדמו\"ר האמצעי שם ע' א'קלז. וש\"נ. המשך יונתי הנ\"ל ס\"ע נד ואילך. המשך תער\"ב הנ\"ל פ' רי ואילך."],["1609","46","ראה תו\"א שבהערה 49."],["1610","47","יומא פו, ב."],["1611","48","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171183\" data-slug=\"likkutei-sichot\" data-id=\"1300171183\">לקו\"ש חי\"ז ע' 183</a> ואילך ובהערות 15, 48 שם."],["1612","49","מג\"א צט, א."],["1613","50","ראה ברכת ערב יוהכ\"פ אחרי תפלת מנחה ה'תשמ\"ז ס\"ג [התוועדויות תשמ\"ז ח\"א ע' 115]. <i>וש\"נ</i>."],["1614","51","ראה ברכת עריוכ\"פ הנ\"ל ס\"ב [שם ע' 113 ואילך]. <i>וש\"נ</i>."],["1615","52","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380892\" data-slug=\"likkutei-torah\" data-id=\"4001380892\">לקו\"ת תבוא מג, סע\"ד</a>. וראה גם חנה אריאל האזינו מד, ב."],["1616","53","ר\"ה יח, א. יבמות מט, ב. קה, א."],["1617","54","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">גיטין סו, א</a>. לקו\"ת תצא לז, ג. מאמרי אדמו\"ר האמצעי דברים ח\"ב ס\"ע תקמב ואילך."],["1618","55","ב\"ח או\"ח ריש הל' סוכה (ר\"ס תרכה). וכ\"ה גם בב\"ח או\"ח ס\"ח (ד\"ה ונקראים ציצית)."],["1619","56","או\"ח ריש הל' סוכה שם."],["1620","57","תרל\"ז – פפ\"ד ואילך."],["1621","58","סידור (עם דא\"ח) שער הלולב רסא, ג ואילך. שם רסד, ד ואילך. המשך וככה הנ\"ל פפ\"ז. וראה ד\"ה וחג האסיף תשמ\"ג ס\"ב ואילך (לקמן ע' קעג ואילך). וש\"נ."],["1622","59","ראה פע\"ח שער כט (שער הלולב וד' מיניו) פ\"א-ג. שער הכוונות דרושי חג הסוכות דרוש ה. מ\"ח מס' ימי מצוה וסוכה פ\"ה מ\"ג. – הובא ונתבאר בסידור שם רסג, סע\"ג ואילך. המשך וככה הנ\"ל פפ\"ד ואילך. ד\"ה וחג האסיף הנ\"ל ספ\"ו (לקמן ע' קעו). וש\"נ."],["1623","60","ראה המשך וככה הנ\"ל פצ\"ח (ע' קנט)."],["1624","61","המשך יונתי הנ\"ל פי\"ב ואילך (ע' יז ואילך)."],["1625","62","סוכה יב, רע\"א. שו\"ע אדה\"ז או\"ח הל' סוכה ר\"ס תרכט."],["1626","63","ראה ע\"ח שער י (שער התיקון) פ\"ה. שער יא (שער המלכים) פ\"א-ב."],["1627","64","בהמאמר דשמיני עצרת (ע' מח). וראה גם שם פ\"ז (ס\"ע ט)."],["1628","65","חגיגה יב, א. ירושלמי ברכות פ\"ח ה\"ה. ב\"ר פי\"א, ב. פי\"ב, ו. ועוד."],["1629","66","ב\"ר פ\"א, ד."],["1630","67","ע\"פ ל' חז\"ל – חגיגה ה, ב."],["1631","68","ראה גם ד\"ה נתת ליראיך ה'תשל\"ו ס\"ז (לקמן ח\"ד ע' נד). וש\"נ."],["1632","69","ראה ד\"ה הנ\"ל ס\"ו (לקמן ח\"ד ע' נג)."],["1633","70","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">עקב ח, ג</a>. ל\"ת וס' הליקוטים להאריז\"ל עה\"פ. וראה תו\"א בשלח סה, ד ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380129\" data-slug=\"likkutei-torah\" data-id=\"4001380129\">לקו\"ת צו יג, ב</a> ואילך. אוה\"ת שלח כרך ו ע' א'תשע ואילך. וש\"נ. ד\"ה נתת ליראיך שבהערה 68. וש\"נ."],["1634","71","בראשית א, יא."],["1635","72","בראשית שם, כו."],["1636","73","ראה פרש\"י עה\"פ ויצא לא, נד. ויקרא ג, יא. וראה גם שו\"ע אדה\"ז או\"ח סקפ\"ח ס\"י."],["1637","74","ראה סנהדרין לח, א ובפרש\"י שם ד\"ה שיכנס לסעודה מיד."],["1638","75","ראה אבות פ\"ב מי\"ב. רמב\"ם הל' דעות ספ\"ג. טושו\"ע או\"ח סרל\"א."],["1639","76","ראה המשך יונתי הנ\"ל ספ\"ז."],["1640","77","וראה גם ד\"ה נתת ליראיך הנ\"ל ס\"ח (לקמן ח\"ד ע' נה)."],["1641","78","רמב\"ם הל' תשובה פ\"ז ה\"ד, מברכות לד, ב."],["1642","79","דרמ\"צ קפו, סע\"א."],["1643","80","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["1644","81","רות ד, יח."],["1645","82","ב\"ר פי\"ב, ו. שמו\"ר פ\"ל, ג."],["1646","83","ב\"ר ושמו\"ר שם."],["1647","84","בראשית ב, ד."],["1648","85","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["1649","86","המשך תער\"ב ח\"א פ' רכב (ע' תמח ואילך)."],["1650","87","ס\"פ תצוה. אחרי טז, לד. וראה תוד\"ה עד אחת – מנחות יח, א."],["1651","88","פע\"ח שער כז (שער יוה\"כ) ספ\"א. שם פ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380197\" data-slug=\"likkutei-torah\" data-id=\"4001380197\">לקו\"ת אחרי כח, ב</a>. דרושים לש\"ש סה, ריש ע\"ד. מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' א'קה. וש\"נ."],["1652","89","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">לקו\"ת שמע\"צ צב, ב</a>. שה\"ש נ, סע\"ב. מאמרי אדמו\"ר האמצעי שם ע' א'קכט. <i>וש\"נ</i>."],["1653","90","פע\"ח שער ז (שער הק\"ש) פט\"ו. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381313\" data-slug=\"likkutei-torah\" data-id=\"4001381313\">לקו\"ת שה\"ש מו, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381213\" data-slug=\"likkutei-torah\" data-id=\"4001381213\">וראה גם שם כא, א</a>. נא, ג."],["1654","91","בספרו או\"ת (הוצאת קה\"ת) בתחלתו (ב, סע\"ג). וראה המשך תער\"ב ח\"ב ע' תתקב ואילך."],["1655","92","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380861\" data-slug=\"likkutei-torah\" data-id=\"4001380861\">לקו\"ת תצא לו, א</a>."],["1656","93","לשון הכתוב – קהלת יב, ז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381011\" data-slug=\"likkutei-torah\" data-id=\"4001381011\">לקו\"ת</a> ר\"פ האזינו. שם עב, רע\"א. וראה ד\"ה מים רבים תשל\"ח סוף ס\"ד ואילך, ובהערות 41, 47 שם (לקמן ע' רמח ואילך)."],["1657","94","ראה ד\"ה הנ\"ל ס\"ה (שם)."],["1658","95","ויק\"ר פ\"ל, ז."],["1659","96","ראה ויק\"ר שם ובמת\"כ ויפ\"ת שם."],["1660","97","ראה (באופן אחר) סה\"מ תרנ\"א ע' עה ואילך. שם ע' ריב. שם ע' ריד ואילך. תרנ\"ט ע' סד."],["1661","98","ראה פרש\"י עה\"פ ויצא לא, לט. מלכים-א א, כא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. ובכ\"מ."],["1662","99","ראה שבועות לט, סע\"א וריש ע\"ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>."],["1663","100","בד\"ה שובה ישראל דש\"פ האזינו, שבת שובה שנה זו (תשמ\"א (לעיל ע' קיא ואילך). וראה ד\"ה שובה תרע\"ג (המשך תער\"ב ח\"א פע\"ח – ע' קמו ואילך). ד\"ה הנ\"ל דשנת תרח\"צ (סה\"מ תרח\"צ ע' לד ואילך) ותשמ\"ח."],["1664","101","הושע יד, ב."],["1665","102","ראה אוה\"ת סוכות ע' א'תשנו. ברכה ס\"ע א'תתסו ואילך. ד\"ה צהר תעשה ה'תש\"ב פ\"ג (סה\"מ ה'תש\"ב ע' 49). ועוד."],["1666","103","מכיון שעבודת ה' צריכה להיות תמיד (רמב\"ם הל' דעות ספ\"ג. טושו\"ע או\"ח סרל\"א)."],["1667","104","ראה רמב\"ם סוף הל' לולב. ד\"ה שמח תשמח ה'תשמ\"א ס\"ד (לקמן ח\"ד ס\"ע רמא ואילך). וש\"נ."],["1668","105","ישעי' לה, י. נא, יא."]]],[1500360025,"<h3>בס\"ד. אור לי\"ג תשרי (הילולא דאדמו\"ר מהר\"ש נ\"ע), ה'תשמ\"ג<sup data-n=\"1669\">*</sup></h3>\n<b>וחג</b> האסיף גו' באספך את מעשיך מן השדה<sup data-n=\"1670\">1</sup>, ומבאר בעל ההילולא<sup data-n=\"1671\">2</sup>, דמה שהרגלים נקבעו בזמני התבואה, המכוון הוא (בעיקר) לתבואה ברוחניות<sup data-n=\"1672\">3</sup>. וזהו מה שנקבע חג הסוכות בזמן אסיפת התבואה, ועד שנקרא בשם חג האסיף<sup data-n=\"1673\">4</sup>, מפני שענינו של חג הסוכות קשור ובא לאחרי העבודה דאסיפת התבואה (ואספת<sup data-n=\"1674\">5</sup> דגנך ותירושך ויצהרך<sup data-n=\"1675\">6</sup>) ברוחניות. וכמו שאסיפת התבואה כפשוטה בגשמיות היא לפני כניסת החג, דביו\"ט מי שרי<sup data-n=\"1676\">7</sup>, כ\"ה גם ברוחניות, שלאחרי העבודה דבאספכם את תבואת הארץ (הנה אז) תחוגו את חג ה' שבעת ימים<sup data-n=\"1677\">8</sup>. וצריך להבין השייכות דחג הסוכות, דשמו (חג הסוכות) הוא על שם בסוכות<sup data-n=\"1678\">9</sup> תשבו שבעת ימים<sup data-n=\"1679\">10</sup>, לבאספכם את תבואת הארץ. וגם צריך להבין (כהדיוק בכמה דרושים<sup data-n=\"1680\">11</sup>) מ\"ש<sup data-n=\"1678\">9</sup> בסוכות תשבו שבעת ימים כל האזרח בישראל ישבו בסוכות, דלכאורה, הרי הציווי בסוכות תשבו גו' הוא לכללות ישראל ולכל אחד מישראל, ומה מוסיף במ\"ש כל האזרח בישראל ישבו בסוכות. וגם צריך להבין<sup data-n=\"1681\">12</sup> מה שבהציווי בסוכות תשבו אומר תשבו שבעת ימים משא\"כ בהציווי כל האזרח גו' אומר ישבו סתם (ואינו אומר שבעת ימים).\n<b>והנה</b> בהמשך לתחוגו את חג ה' שבעת ימים ממשיך הכתוב<sup data-n=\"1682\">13</sup> ולקחתם לכם ביום הראשון פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל גו', שגם מצוה זו קשורה עם חג האסיף<sup data-n=\"1683\">14</sup>, דזמנה של מצוה זו הוא דוקא ביום הראשון, ביום הראשוןשל החג שמצד באספכם גו'. ועם היות שמצות נטילת ד' מינים אינה קשורה כ\"כ עם עצם החג כהמצוה דישיבה בסוכה<sup data-n=\"1684\">15</sup> [וכמובן גם מזה שהחיוב דמצות ישיבה בסוכה הוא בכל שבעת ימי החג (בסוכות תשבו שבעת ימים), משקידש החג, משא\"כ החיוב דמצות נטילת ד' מינים מתחיל בבוקר (בעלות השחר, ולכתחילה מנץ החמה<sup data-n=\"1685\">16</sup>) וביום הראשון<sup data-n=\"1686\">17</sup>], מ\"מ, הרי גם מצוה זו קשורה (כנ\"ל) עם יום הראשון דחג האסיף.\nב) <b>ולהבין</b> זה (השייכות דסוכה ונטילת ד' מינים לאסיפת התבואה) יש להקדים מה שארז\"ל<sup data-n=\"1687\">18</sup> פרי עץ הדר זה הקב\"ה כפות תמרים זה הקב\"ה וענף עץ עבות זה הקב\"ה וערבי נחל זה הקב\"ה (ומביאים ראיות מפסוקים על זה). ומבאר בעל ההילולא<sup data-n=\"1688\">19</sup>, דמה שכל א' מד' המינים מורה על הקב\"ה הוא מצד ענין האחדות שבהם. דפרי<sup data-n=\"1689\">20</sup> עץ הדר זה אתרוג שדר באילנו משנה לשנה<sup data-n=\"1690\">21</sup>, דבמשך השנה יש כו\"כ שינויים מן הקצה אל הקצה שלכן נקראת בשם שנה מלשון שינוי<sup data-n=\"1691\">22</sup> לפי שיש בה כל שינויי האוירים דכל ו' התקופות שנמנות בכתוב<sup data-n=\"1692\">23</sup>, והאתרוג (שדר באילנו משנה לשנה) הוא סובל את כל השינויים. ויתירה מזו, דלא רק שהוא סובל את כל האוירים, אלא שהוא גדל מהם. היינו, דלא רק ששינויי האוירים אינם עושים בו גרעון, אלא שהוא מקבל מהם תוספת צמיחה<sup data-n=\"1693\">24</sup>. דזהו (אמיתית) ענין האחדות שבאתרוג, שהוא מאחד את כל שינויי האוירים, שמכולם נעשה דבר אחד (מציאות האתרוג). ועד\"ז הוא גם בלולב, כפות תמרים (כפת, חסר כתיב) ודרשו רז\"ל שצ\"ל כפות, שהעלים צריכים להיות באופן שיהיו ראויים לכפותן ולאגדם יחד עם השדרה כדבר אחד<sup data-n=\"1694\">25</sup>. דהגם שיש עוד אילנות שהענפים קרובים להעץ, אין זה באופן דכפות (אחדות) כבלולב<sup data-n=\"1695\">26</sup>. וכ\"ה גם בההדסים, ענף עץ עבות, עבות דוקא, תלתא בחד קינא<sup data-n=\"1696\">27</sup>. דהגם שהם ג' עלים נפרדים [ריבוי התחלקות, שהרי גם שנים הם רבים, דמיעוט רבים שנים<sup data-n=\"1697\">28</sup>, ומכ\"ש ג'] מ\"מ הן \"עבות\" (כמין קליעה<sup data-n=\"1698\">29</sup>), בחד קינא. וכ\"ה גם בערבה (ערבי נחל)שנק' בגמרא בשם אחוונא<sup data-n=\"1699\">30</sup>, על שם שגדלים באחוה<sup data-n=\"1700\">31</sup>. דאע\"פ שהם ערבי נחל, ערבי לשון רבים, הם באחוה ובאחדות, וכך הוא אופן גידולם (שגדלים באחוה).\n<b>והנה</b> ענין האחדות שבד' מינים אלו הוא באופן שמריבוי נעשה אחדות. וכמו באתרוג, שהאוירים דו' תקופות השנה הם שונים זה מזה (ועד שהם הפכים), ואעפ\"כ הם מתאחדים אח\"כ ונעשים דבר אחד (מציאות האתרוג). וכ\"ה גם בלולב, שמזה גופא שאומרים שצ\"ל כפות מובן שיש בו עלים נפרדים וצריך לכפותם<sup data-n=\"1701\">32</sup>. וכ\"ה גם בהדס שצ\"ל ג' עלים נפרדים ושאעפ\"כ יתאחדו זה עם זה (בחד קינא). וכ\"ה גם בערבי נחל, שהם ריבוי ערבות (ערבי לשון רבים<sup data-n=\"1702\">33</sup>) ואעפ\"כ הם מתאחדים וגדלים באחוה.\nג) <b>וזהו</b> הקשר דמצות נטילת ד' מינים עם חג הסוכות, כי ענין הסוכה הוא שלום<sup data-n=\"1703\">34</sup>, היינו מה שמריבוי נעשה אחדות. דמזה מובן גם בנוגע לחג הסוכות, שהוא (כנ\"ל בתחילת המאמר) על שם בסוכות תשבו, שענינו הוא מה שמריבוי נעשה אחדות. דזהו חג הסוכות שבעת ימים<sup data-n=\"1704\">35</sup>, שבעת ימים הו\"ע ההתחלקות, דכל יום הוא משונה מזולתו. ועד שהם כוללים התחלקות דכל משך הזמן. כי שבעת ימי השבוע הן שבעת ימי ההיקף<sup data-n=\"1705\">36</sup>. דזהו מה שבכל שבוע אומרים היום יום ראשון, היום יום שני וכו', דלכאורה הלא מברה\"ע עד עתה כבר יש אלפים ורבבות ימים ולמה אנו מונין יום ראשון שני ושלישי וכו', וידוע הביאור בזה<sup data-n=\"1706\">37</sup>, שזהו לפי שהם ימי ההיקף שחוזרין חלילה. וענין חג הסוכות שבעת ימים הוא, שכל שבעת הימים נעשים ענין אחד, חג הסוכות.\nד) <b>וביאור</b> הענין (השייכות דנטילת ד' מינים עם חג הסוכות) בעומק יותר, דענין האחדות שבשניהם הוא לא רק באופן דהתאחדות של דברים נפרדים, אלא אחדות אמיתית שלמעלה מהתחלקות. דבמצות נטילת ד' מינים הנה נוסף על האחדות שבכל אחד מד' המינים (כמו שהוא בפני עצמו), שהיא התאחדות שלדברים נפרדים, הרי כל ד' המינים נעשים מצוה אחת<sup data-n=\"1707\">38</sup>, ענין אחד<sup data-n=\"1708\">39</sup>. דהגם שהם ד' מינים שונים, ומן הקצה אל הקצה, כדאיתא במדרש<sup data-n=\"1709\">40</sup> דד' מינים שבלולב הם כנגד ד' סוגים שבישראל, מהסוג שכנגד אתרוג שיש בו טעם וריח (תורה ומעשים טובים) עד להסוג שכנגד ערבה שאין בה לא טעם ולא ריח, מ\"מ הם נעשים כולם (כל הד' סוגים) אגודה אחת לעשות רצונך, דאחדות זו (מה שכולם נעשים אגודה אחת לעשות רצונך) היא אחדות אמיתית שלמעלה מהתחלקות<sup data-n=\"1710\">41</sup>. ועד\"ז הוא בענין האחדות דסוכה, דלאחרי שאומר בסוכות תשבו שבעת ימים, ענין האחדות דנפרדים (מה ששבעת ימים מתאחדים בסוכה אחת), מוסיף כל האזרח בישראל ישבו בסוכות (ישבו סתם, ואינו אומר שבעת ימים), אחדות אמיתית שלמעלה מהתחלקות<sup data-n=\"1711\">42</sup>.\nה) <b>ועפ\"ז</b> תובן השייכות דחג הסוכות (תחוגו את חג ה' שבעת ימים, דמצות ישיבה בסוכה ודמצות נטילת ד' מינים) לבאספכם את תבואת הארץ, כי באספכם הוא ענין האחדות, שבתחילה הם דברים נפרדים, וענין באספך הוא לאסוף אותם (ולאחדם) יחד. ושני ענינים בזה (בדוגמת ב' המדריגות דאחדות שבסוכה וד' מינים). דתחילה היא האסיפה (וההתאחדות) של ריבוי הפרטים דכל מין ומין (דגן, תירוש ויצהר) בפני עצמו, ולאח\"ז היא האסיפה (ההתאחדות) דכל ג' המינים יחד, שאוסף כולם אל הבית<sup data-n=\"1712\">43</sup> (למקום אחד).\nו) <b>והנה</b> כל ענינים אלו באים לאחרי העבודה דהתחלת חודש תשרי, אותיות רשית<sup data-n=\"1713\">44</sup>. דעשרה ימים שבין ראש השנה ליום הכפורים<sup data-n=\"1714\">45</sup>, עשרה ימים, הם בחינת התחלקות, וביום הכפורים הם מתכללים ומתאחדים ביום <i>אחד</i> (דיום הכפורים)<sup data-n=\"1715\">46</sup>, <i>אחת</i> בשנה<sup data-n=\"1716\">47</sup>, ולאחרי יום הכפורים, בד' ימים שבין יום הכפורים לסוכות, היא ההכנה לקיום מצות בסוכות תשבו ונטילת ד' מינים<sup data-n=\"1717\">48</sup>, כולל גם העבודה דבאספך את מעשיך מן השדה, דעבודה זו היא (כנ\"ל בתחילת המאמר) לפני והכנה לחג הסוכות. אלא שביום הכפורים, שאין בו אכילה ושתי' וכו', הוא באופן דהפשטה מעניני העולם<sup data-n=\"1718\">49</sup>.ובפרט בתפלת נעילה דיום הכפורים, שאז ישראל ומלכא בלחודוהי<sup data-n=\"1719\">50</sup>. דזהו פירוש נעילה<sup data-n=\"1720\">51</sup>, שנועלים כל השערים ונמצאים (בפנים) רק ישראל ומלכא. ובכדי להשלים הכוונה דדירה בתחתונים<sup data-n=\"1721\">52</sup>, צריכה להיות ההמשכה (להמשיך ענין האחדות) למטה, בעוה\"ז הגשמי, עד בענינים הגשמיים דעוה\"ז, מתחיל מבאספך את מעשיך מן השדה, דהגם שהיא עבודה רוחנית (כנ\"ל בתחילת המאמר), מ\"מ הרי היא קשורה גם עם אסיפת התבואה (דגנך תירושך ויצהרך) כפשוטה בגשמיות<sup data-n=\"1722\">53</sup>, ועד\"ז הוא גם במצות בסוכות תשבו, דסכך הסוכה צ\"ל מגרנך ומיקבך ובזה גופא דוקא מפסולת גורן ויקב<sup data-n=\"1723\">54</sup>, ועד\"ז הוא גם במצות נטילת ד' מינים, דא\"א לקיים המצוה ע\"י כוונה<sup data-n=\"1724\">55</sup>, ע\"י העבודה דמדות (הגם שד' המינים הם מסוג הצומח וצומח הו\"ע המדות<sup data-n=\"1725\">56</sup>), וגם לא ע\"י העבודה דמלכות (אף שענין הנענועים הוא להמשיך בנוקבא דז\"א (מלכות) העומדת בחזה דז\"א<sup data-n=\"1726\">57</sup>), וצריך לד' מינים גשמיים דוקא, ושיגעו בחזה<sup data-n=\"1727\">58</sup> הגשמי דוקא.\nז) <b>וזהו</b> וחג האסיף גו' באספך את מעשיך מן השדה, שהוא אסיפת כל הענינים יחד. וההתחלה בזה היא שמאספים כל הענינים דתורה<sup data-n=\"1728\">59</sup> (ככל העבודות, שהתחלתם היא בענינם כמו שהוא בתורה, מכיון דאסתכל באורייתא וברא עלמא<sup data-n=\"1729\">60</sup>). דהנה כל ענין בתורה יש בו ששים ריבוא פירושים ע\"ד הפשט, ששים ריבוא פירושים ע\"ד הרמז, וכן ע\"ד הדרוש וע\"ד הסוד<sup data-n=\"1730\">61</sup>. וצריך לאסוף ולכלול כל הפירושים דחלק הפשט, וכן כל הפירושים דחלק הרמז, דחלק הדרוש ודחלק הסוד, ולאחרי זה לאסוף ולכלול כל ד' החלקים יחד. וזהו ואספת דגנך ותירושך ויצהרך, דגן (לחם) הוא נגלה דתורה, תירוש (יין) הוא רזין דאורייתא, ויצהר (שמן) הוא רזין דרזין<sup data-n=\"1731\">62</sup>, והעבודה דואספת דגנך ותירושך ויצהרך היא בשתים. האסיפה וההתכללות של ריבוי הענינים דכל סוג (נגלה, רזין ורזין דרזין) גופא, וגם האסיפה וההתכללות דכל הסוגים יחד, ולהעלותם לדרגא שלמעלה מהתחלקות, עד לבחי' אתר דכליל כולא<sup data-n=\"1732\">63</sup> ולמעלה יותר.והגם דעיקר ענין זה (ההתאחדות דכל עניני התורה) יהי' בביאת המשיח, שילמד את כל העם כולו<sup data-n=\"1733\">64</sup> את כל התורה כולה, גם רזי תורה ורזין דרזין, וכמ\"ש<sup data-n=\"1734\">65</sup> ישקני מנשיקות פיהו ופירש\"י שלע\"ל יתגלה סוד טעמי' (דתורה) ומסתר צפונותי', וכ\"ז יהי' אז באופן של ראי'<sup data-n=\"1735\">66</sup>, אעפ\"כ, מכיון שטועמי' חיים זכו<sup data-n=\"1736\">67</sup>, הרי מעין זה באופן של טעימה עכ\"פ יכול להיות וצריך להיות עכשיו. ומזה (מהענין דואספת דגנך ותירושך ויצהרך כמו שהוא בתורה) נמשך שיהי' ואספת דגנך ותירושך ויצהרך בכל עניני עבודת האדם ברוחניות, ועד שזה נמשך גם בואספת דגנך ותירושך ויצהרך כפשוטו, בדגן תירוש ויצהר הגשמיים. ועד\"ז הוא גם בענין האחדות דישיבה בסוכה (שלאחרי העבודה דואספת), שיש בזה (כנ\"ל) ב' מדריגות, בסוכות תשבו שבעת ימים שהו\"ע האחדות כמו ששייך עדיין לשבעת ימים (התחלקות) וכל האזרח בישראל ישבו בסוכות (סתם, שלמעלה מענין שבעת ימים), דעיקר ענין זה יהי' לע\"ל, כידוע<sup data-n=\"1737\">68</sup> דפירוש אזרח הוא מה שעתיד להזריח לע\"ל, אלא שאעפ\"כ יש הארה מזה גם עכשיו. כפירוש בעל ההילולא (ע\"פ זה)<sup data-n=\"1738\">69</sup>, דמה שעתיד להזריח לע\"ל בתוך ישראל ובפנימיותם, הנה גם עכשיו ישבו בסוכות, שזה מתגלה עליהם (עכשיו) בבחי' סוכות ומקיף. ועד\"ז הוא גם בענין הד' מינים (דנטילת ד' מינים הוא (כנ\"ל) לאחרי הישיבה בסוכה), דכל אחד מד' המינים הוא \"זה הקב\"ה\", דענין זה הוא גם עכשיו, אלא שעכשיו הוא בהעלם, והגילוי מזה יהי' לע\"ל שאז יהי' ונגלה כבוד הוי' וראו כל בשר גו'<sup data-n=\"1739\">70</sup>. ואז יהי' גם אסיפת דגנך ותירושך ויצהרך באופן אחר, שלא יהי' צריך להיות ואספת (שישראל יצטרכו לאסוף) כי אם ועמדו זרים ורעו צאנכם ובני נכר אכריכם וגו'<sup data-n=\"1740\">71</sup>, וגם הישיבה בסוכה תהי' באופן נעלה יותר, שישבו בסוכת עורו של לויתן<sup data-n=\"1741\">72</sup>, וגם ענין זה הקב\"ה (שבד' המינים) יהי' אז בגילוי, כפי שאני נכתב כך אני נקרא<sup data-n=\"1742\">73</sup>, אלא שמעין זה (דכל ענינים אלו) יש גם עכשיו, וכנ\"ל בפירוש כל האזרח בישראל ישבו בסוכות, ועאכו\"כ בהזמן דסוף הגלות (עקבתא דמשיחא) שנשארו רק רגעים ספורים, והבטיחה תורה שסוף ישראל לעשות תשובה בסוף גלותן ומיד הן נגאלין<sup data-n=\"1743\">74</sup>, ובשמחה ובטוב לבב.\n**********",[["1669","*","יצא לאור ב<b>קונטרס חג הסוכות – תשמ\"ז</b>, \"לקראת חג הסוכות . . <i>ערחה\"ס</i>,<i> ה' </i><b>ת</b><i>הא </i><b>ז</b><i>ו </i><b>ש</b><i>נת </i><b>מ</b><i>שיח</i>\"."],["1670","1","משפטים כג, טז."],["1671","2","רד\"ה כי תבואו גו' ושבתה ורד\"ה קדש ישראל לה' תר\"ל (סה\"מ תר\"ל ע' קלב. שם ע' רה-רו). וראה גם אוה\"ת משפטים ע' א'קעח ואילך."],["1672","3","בסה\"מ תר\"ל שם ע' קלב \"רק שהקפידא ג\"כ על תבואה גשמי' כו'\". ועד\"ז שם ע' רו. וראה לקמן ס\"ו."],["1673","4","דשמו של כל דבר מורה על תכונתו, ועד שהוא החיות שלו (שעהיוה\"א פ\"א. ובכ\"מ)."],["1674","5","עקב יא, יד. וראה אוה\"ת שם ע' א'קפה. סה\"מ תר\"ל שם ע' קלז. שם ע' ריג."],["1675","6","כדכתיב (ראה טז, יג) באספך מגרנך ומיקבך. וראה רשב\"ם עה\"פ משפטים שם."],["1676","7","חגיגה יח, א."],["1677","8","אמור כג, לט."],["1678","9","אמור שם, מב."],["1679","10","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221126\" data-slug=\"likkutei-sichot\" data-id=\"1300221126\">לקו\"ש חכ\"ב</a> שיחה ב' לפ' אמור ס\"ה ואילך (ע' 126 ואילך) שזהו (הישיבה בסוכה) עיקר תוכנו של החג."],["1680","11","רד\"ה בסוכות תשבו עת\"ר (ע' כג). תער\"ג (המשך תער\"ב ח\"א ע' קנ). תרפ\"א (ע' קי). תר\"צ (סה\"מ קונטרסים ח\"א עח, ב). תרצ\"ד (תשי\"א) (סה\"מ תשי\"א ע' 50). תש\"ד (ע' 31). תש\"ה (ע' 43). תש\"י (ע' 58)."],["1681","12","רד\"ה הנ\"ל תש\"ד. תש\"י."],["1682","13","אמור שם, מ."],["1683","14","ראה רמב\"ן שם (פסוק לט) \"שתוסיפו לשמוח . . בלולב ואתרוג . . כי הוא זמן שמחה שברך השם אותך בכל תבואתך כו'\"."],["1684","15","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191366\" data-slug=\"likkutei-sichot\" data-id=\"1300191366\">לקו\"ש חי\"ט ע' 353</a>."],["1685","16","ב\"י לטור או\"ח הל' סוכה ר\"ס תרנב. שו\"ע שם."],["1686","17","שנטילת ד' מינים מן התורה במדינה היא רק יום אחד (ר\"ה ל, א. סוכה מא, א). ואפילו במקדש שלולב ניטל שבעה – הרי זה רק פעם אחת ביום. משא\"כ מצות ישיבה זמנה היא <i>כל שבעת הימים</i>, תשבו כעין תדורו (סוכה כח, ב. טושו\"ע (ודאדה\"ז) או\"ח הל' סוכה ר\"ס תרלט)."],["1687","18","ויק\"ר פ\"ל, ט."],["1688","19","בד\"ה ולקחתם לכם תרל\"ו (סה\"מ תרל\"ו ח\"ב ע' שנח ואילך)."],["1689","20","בהבא להלן ראה גם סה\"מ תקס\"ח ח\"א ע' תמז. סידור (עם דא\"ח) שער הלולב (רסא, ג ואילך. שם רסד, ד ואילך). ובדרושי בעל ההילולא – ד\"ה ולקחתם לכם הנ\"ל (ס\"ע שנט ואילך). המשך וככה תרל\"ז פפ\"ז. סד\"ה ולקחתם לכם תרס\"א (ע' רד). תרפ\"ג (ס\"ע קפא ואילך). ועוד."],["1690","21","סוכה לה, א."],["1691","22","עבודת הקודש ח\"ד פי\"ט. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830002\" data-slug=\"or-hatorah-hb\" data-id=\"8158830002\">אוה\"ת</a> מקץ שלח, סע\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041322\" data-slug=\"likkutei-sichot\" data-id=\"1300041322\">לקו\"ש ח\"ד ע' 1323</a>."],["1692","23","נח ח, כב. וראה ב\"מ קו, ב. פרש\"י עה\"פ."],["1693","24","המשך וככה הנ\"ל פצ\"ד."],["1694","25","סוכה לב, א. שו\"ע אדה\"ז או\"ח הל' סוכה סתרמ\"ה ס\"ג."],["1695","26","ד\"ה ולקחתם לכם תרל\"ו (ע' שס)."],["1696","27","סוכה שם, ב. טושו\"ע (ודאדה\"ז) שם סתרמ\"ו ס\"ג (ס\"ב)."],["1697","28","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211111\" data-slug=\"likkutei-sichot\" data-id=\"1300211111\">לקו\"ש חכ\"א ע' 111</a> הערה 21."],["1698","29","סוכה שם. שו\"ע אדה\"ז שם ס\"א."],["1699","30","ראה שבת כ, א ובפרש\"י שם ד\"ה אחוונא. שם, ב ובפרש\"י שם ד\"ה אחווינא."],["1700","31","בסידור שם רסד, ד (ועד\"ז שם רסב, ג. סה\"מ תקס\"ח שם וע' שיז): וערבי נחל נק' במס' שבת (כ, א) גבי והאח לפניו מבוערת מאי האח אחוונא <i>ופי' רש\"י מפני שגדלי' באחוה</i>. ובפירוש רש\"י שלפנינו ליתא. ובסידור שם רסב, ג: והוא ממדרשי רז\"ל."],["1701","32","ראה סוכה לב, א: כפות מכלל דאיכא פרוד. ובפרש\"י שם: כפות, משמע שפרוד מתחלה ואתה כופתו."],["1702","33","וגם לקיום המצוה צ\"ל <i>שני</i> בדי ערבה (טושו\"ע (ודאדה\"ז) שם ר\"ס תרנא)."],["1703","34","וכידוע שסוכה היא בדוגמת תיבת נח, שבה הי' מעין השלום והאחדות (לא ירעו ולא ישחיתו) דלע\"ל – ד\"ה כי פדה לאדה\"ז (סה\"מ אתהלך לאזניא ע' נז. עם הגהות – <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560405\" data-slug=\"or-hatorah-hb\" data-id=\"8316560405\">אוה\"ת נח תרסט, א</a> ואילך). אוה\"ת דברים (כרך ו) ע' ב'תקכט ואילך. וככה הנ\"ל פצ\"ה-צו. ולהעיר גם ממרז\"ל (סוכה כז, ב) \"שכל ישראל ראויים לישב בסוכה אחת\"."],["1704","35","אמור כג, לד."],["1705","36","ראה שו\"ת הרשב\"א ח\"א ס\"ט."],["1706","37","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">לקו\"ת שה\"ש כה, א</a>-ב. רד\"ה ויהי ביום השמיני תרע\"ח (ע' רסט). תש\"ה (ע' 167). ובכ\"מ."],["1707","38","ראה סהמ\"צ להרמב\"ם (שורש יא) שהם לא <i>ד'</i> מצוות כ\"א מצוה <i>אחת</i> דוקא."],["1708","39","ראה גם לקו\"ש ח\"ד ע' 1142 הערה 13, דשני ענינים אלו הם דוגמת \"לאחדים\" ו\"כאחד\", עיי\"ש."],["1709","40","ויק\"ר פ\"ל, יב."],["1710","41","ומה שמסיים במדרש שם (לאחרי \"יוקשרו כולם אגודה אחת\") \"והן מכפרין אלו על אלו\" – הכוונה בזה, שבהאחדות דד' המינים יש <i>גם</i> הענין (והמעלה) ד\"לאחדים\" (ראה לקו\"ש שם ע' 1160 ובהערות שם)."],["1711","42","ולהעיר, דזה ש\"כל ישראל ראויים לישב בסוכה אחת\" למדו רז\"ל מ\"כל האזרח גו' ישבו בסוכות\" דוקא, ולא מהתחלת הכתוב \"בסוכות תשבו שבעת ימים\". וראה ד\"ה בסוכות תשבו ה'תשל\"ח סי\"א ואילך (לעיל ע' קמ ואילך)."],["1712","43","ראה פרש\"י עה\"פ תשא לד, כב. וראה גם פרש\"י עה\"פ משפטים כג, טז. עקב יא, יד.\nולהעיר מהידוע שמקיף דבית הוא מקיף הרחוק ו\"אינו לפי מדת האדם כלל\" (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381124\" data-slug=\"likkutei-torah\" data-id=\"4001381124\">לקו\"ת ברכה צט, ב</a>. סה\"מ תש\"ד ע' 120. ובכ\"מ). שלכן, האחדות שמצד בית – היא אחדות אמיתית שלמעלה מהתחלקות."],["1713","44","בעה\"ט עה\"פ עקב שם, יב. אוה\"ת סוכות ע' א'תשנו. סה\"מ תר\"ל ע' רפז. ובכ\"מ."],["1714","45","ראה ר\"ה יח, א. וש\"נ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291218\" data-slug=\"likkutei-sichot\" data-id=\"1300291218\">לקו\"ש חכ\"ט ע' 203</a> ואילך."],["1715","46","ראה ב\"ר פ\"ג, ח: יום אחד . . יום הכפורים."],["1716","47","ס\"פ תצוה. אחרי טז, לד."],["1717","48","ויק\"ר פ\"ל, ז."],["1718","49","ראה ד\"ה יוהכ\"פ אסור באו\"ש תרל\"ו (סה\"מ תרל\"ו ח\"ב ע' שיא ואילך)."],["1719","50","ראה זהר ח\"ג לב, א. ח\"א רח, ב."],["1720","51","ראה בארוכה לקו\"ש ח\"ד ע' 1154."],["1721","52","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["1722","53","כמובן בפשטות. וראה גם סה\"מ תר\"ל שבהערה 3."],["1723","54","ולא מגורן ויקב עצמן – סוכה יב, א. שו\"ע אדה\"ז שם ר\"ס תרכט."],["1724","55","ראה ד\"ה ולקחתם לכם תרל\"ו (ס\"ע שסא ואילך)."],["1725","56","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א בראשית ד, א</a>. ובכ\"מ (נסמנו בספר הערכים-חב\"ד ערך אדם ס\"ז)."],["1726","57","סידור (עם דא\"ח) שער הלולב רסג, סע\"ג (ממשנת חסידים – מס' ימי מצוה וסוכה פ\"ה). ד\"ה ולקחתם לכם הנ\"ל. המשך וככה הנ\"ל פפ\"ד ואילך. רד\"ה ולקחתם לכם תרס\"א (ע' קצא). ובכ\"מ."],["1727","58","סידור אדה\"ז דיני נטילת לולב (לפני הלל)."],["1728","59","ראה גם סה\"מ תר\"ל ע' קלז, דענין חג האסיף, ואספת דגנך ותירושך ויצהרך, קאי על התורה. וראה גם שם ע' ריג."],["1729","60","זח\"ב קסא, ב."],["1730","61","שער הגלגולים הקדמה יז. שער רוח הקודש בענין היחודים על קברי צדיקים הקדמה ג' (קח, ב). ליקוטי מהרח\"ו שבסוף שער מאמרי רז\"ל להאריז\"ל."],["1731","62","ראה אמ\"ב שער הק\"ש פנ\"ד ואילך (עה\"פ ואספת דגנך ותירושך ויצהרך). ובסה\"מ תר\"ל (ע' קלז. שם ע' ריג): דגנך – גליא שבתורה, ותירושך – אגדות, ויצהרך – פנימיות התורה, רזין דאורייתא."],["1732","63","ראה זח\"א קכג, א."],["1733","64","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, א</a>. שער האמונה פנ\"ו ואילך. ובכ\"מ."],["1734","65","שה\"ש א, ב."],["1735","66","לקו\"ת שם, א-ב. שער האמונה פ\"ס. סד\"ה וידבר אלקים (השני) תרצ\"ט. ועוד."],["1736","67","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151295\" data-slug=\"likkutei-sichot\" data-id=\"1300151295\">לקו\"ש חט\"ו ע' 282</a>. וש\"נ."],["1737","68","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת ראה יח, סע\"א</a>. סה\"מ תרכ\"ו ע' רלז. דרושים שבהערה הבאה. ובכ\"מ."],["1738","69","ד\"ה כל האזרח תרל\"ו (ע' שסט). וראה גם לקו\"ת שמע\"צ פח, ג. מאמרי אדה\"ז הקצרים ס\"ע עג וריש ע' עד. סד\"ה בסוכות תשבו תרס\"ד (ע' קסד). עת\"ר (ס\"ע כט ואילך). תרע\"ג (ע' קנז). פר\"ת (ע' לח). תרצ\"ד (תשי\"א) (ע' 58)."],["1739","70","ישעי' מ, ה. וראה המשך וככה תרל\"ז פצ\"ב."],["1740","71","שם סא, ה."],["1741","72","ב\"ב עה, א. וראה יל\"ש אמור רמז תרנג בשם הפסיקתא (והוא בפסיקתא דר\"כ הוצאת באָבער פסקא אחריתי לסוכות)."],["1742","73","פסחים נ, א."],["1743","74","רמב\"ם הל' תשובה פ\"ז ה\"ה."]]],[1500360026,"<h3>בס\"ד. יום ב' דחג הסוכות<sup data-n=\"1744\">*</sup> ה'תשכ\"ג<sup data-n=\"1745\">1</sup></h3>\n<b>בסוכות</b> תשבו שבעת ימים כל האזרח בישראל ישבו בסוכות למען ידעו דורותיכם כי בסוכות הושבתי את בני ישראל בהוציאי אותם מארץ מצרים<sup data-n=\"1746\">2</sup>, ומדייק כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה (שבהמשך ראש השנה תש\"ג)<sup data-n=\"1747\">3</sup>, דבסוכות הושבתי הוא <i>שהקב\"ה</i> הושיב את בני ישראל בסוכות, ובסוכות תשבו הוא ציווי לישראל <i>שהם</i> ישבו בסוכות, היינו שישבו בסוכות בכח עצמם, ואעפ\"כ אומר דבסוכות הושבתי הוא <i>טעם</i> על בסוכות תשבו, דכיון <i>שהקב\"ה</i> הושיב את בני ישראל בסוכות [ענין שהוא רק בחיק הבורא<sup data-n=\"1748\">4</sup>] לכן הם יכולים וצריכים לשבת בסוכות בכח עצמם. ויש לומר, שבהדיוק שבהמאמר שני ענינים<sup data-n=\"1749\">5</sup>. דכיון שבסוכות הושבתי הוא בחיק הבורא איך אפשר שהנברא ידמה להבורא. וגם, דמזה שאומר טעם על בסוכות תשבו (כי בסוכות הושבתי) מוכח שבכדי שיוכלו ישראל לישב בסוכות הוא לא בכח עצמם אלא ע\"י נתינת כח מלמעלה, ואעפ\"כ, לאחרי שהקב\"ה הושיב את בני ישראל בסוכות (כשהוציא אותם מארץ מצרים) יכולים הם לישב בסוכה בכח עצמם.\n<b>ונקודת</b> הביאור בזה (בהמאמר<sup data-n=\"1750\">6</sup>), דבסוכה נמשכים אורות מקיפים, וע\"י הישיבה בסוכה ממשיכים אותם בפנימיות ונעשים אורות מתיישבים. וזהו שבסוכות תשבו הוא ע\"י נתינת כח מלמעלה, כי המקיפים (כמו שהם מצד עצמם) הם היפך ההתיישבות, ובכדי שיהי' בסוכות תשבו – שעל ידי שישראל יושבים בסוכה הם ממשיכים את אורות המקיפים בפנימיות, ויתירה מזו<sup data-n=\"1751\">7</sup> שנעשים אורות מתיישבים – הוא ע\"י בסוכות הושבתי, <i>שהקב\"ה</i> הושיב את בני ישראל בסוכות, אתערותא דלעילא. ומ\"ש בסוכות תשבו שפירושו הוא (כנ\"ל) שישראל ימשיכו המקיפים בפנימיות בכח עצמם, הוא, כי זה שבסוכות הושבתי את בני ישראל בדרך אתערותא דלעילא הי' מלכתחילה על מנת שעי\"ז יהי' בסוכות תשבו ע\"י עבודה בכח עצמם.ב) <b>והנה</b> גם בהישיבה בסוכות דישראל בכח עצמם, שני ענינים. בסוכות תשבו גו', וכל האזרח בישראל ישבו בסוכות. ומהחילוקים דשני הענינים, שבסוכות תשבו הוא בלשון ציווי, וישבו בסוכות הוא בלשון דסיפור והודעה. ועוד חילוק, שהציווי בסוכות תשבו הוא לכל ישראל, ואלו שישבו בסוכות (מעצמם, ואין צריכים לציווי על זה) הם (רק) האזרח בישראל. ומבאר בהמאמר&lt;6&gt;, דבמקיפים יש ב' מדריגות, מקיף הקרוב ומקיף הרחוק. ושני הענינים דבסוכות תשבו וישבו בסוכות הם בשתי מדריגות אלו. בסוכות תשבו הוא במקיף הקרוב וישבו בסוכות הוא במקיף הרחוק. וזהו שגבי ישבו בסוכות אומר כל האזרח בישראל, דאזרח בישראל הוא עצם הנשמה שמושרשת בהעצמות<sup data-n=\"1752\">8</sup>, והישיבה במקיף הרחוק היא בהדרגא דעצם הנשמה. ויש לומר, דזהו שישבו בסוכות הוא לא בלשון דציווי אלא בלשון דסיפור והודעה, כי ענין הציווי שייך רק בדרגת הנשמה המלובשת בגוף, משא\"כ בהנשמה שלמעלה, ובפרט בעצם הנשמה, אין ציווי. והענין דישבו בסוכות, שעצם הנשמה יושבת במקיף הרחוק, הוא (לא מפני הציווי, אלא) מצד עצמה<sup data-n=\"1753\">9</sup>, לפי ששרשה הוא בהעצמות.\n<b>ומבאר</b> בהמאמר, דכל האזרח בישראל ישבו בסוכות הוא טעם על בסוכות תשבו. היינו דהכח על בסוכות תשבו, להמשיך מקיף הקרוב, הוא מפני שעצם הנשמה (האזרח בישראל) מושרשת בהעצמות (מקיף הרחוק). וצריך להבין, דהטעם (והכח) על בסוכות תשבו הוא (כמפורש בכתוב) כי בסוכות הושבתי, ולמה צריך גם להטעם דכל האזרח בישראל ישבו בסוכות.\nג) <b>ויובן</b> זה בהקדים, דכיון שאורות המקיפים (כמו שהם מצד עצמם) אינם באים בהתיישבות, הרי זה שע\"י שישראל יושבים בסוכה נמשכים הם בפנימיות ובהתיישבות, הוא כמו שינוי באורות המקיפים. ויתירה מזו, דמלשון המאמר שע\"י הישיבה בסוכה ממשיכים אורות המקיפים בפנימיות <i>ונעשים</i> אורות מתיישבים (ולא ממשיכים אורות המקיפים בפנימיות ובהתיישבות) משמע, שהשינוי שנעשה ע\"י שישראל יושבים בסוכה הוא גם באורות המקיפים עצמם. דנוסף לזה שע\"י הישיבה בסוכה הם <i>נמשכים</i> בפנימיות ובהתיישבות, גם אורות המקיפים עצמם משתנים להיות אורות מתיישבים. וצריך להבין, איך שייך שעל ידי עבודת האדם (ישיבה בסוכה) יהי' שינוי בהאורות דלמעלה.\n<b>והנה</b> הפירוש דכל האזרח בישראל ישבו בסוכות (בפשטות) הוא, שישראל למטה (נשמות בגופים) צריכים לישב בסוכה (כפשוטה). וע\"פ הידוע<sup data-n=\"1754\">10</sup> שכל הפירושים שבאותו הפסוק שייכים זה לזה, מובן, שגם הענין דישבו בסוכות במקיף הרחוק הוא ע\"י הישיבה בסוכה כפשוטה. ועפ\"ז, ע\"י שישראל יושבים בסוכה, נעשהשינוי גם במקיף הרחוק. וצריך להבין, דמבואר בכ\"מ<sup data-n=\"1755\">11</sup> עה\"פ<sup data-n=\"1756\">12</sup> כי לא אדם הוא להנחם, דענין ניחומין וחרטה (שינוי) שייך רק בבחינת אדם, אבל בבחינת לא אדם, אין שייך ניחומין, שינוי. והטעם על זה הוא, כי ענין השינוי הוא (בעיקר) בשכל, כי בשכל יש סברא לכאן וסברא לכאן, וכיון שאדם הוא מוחין ומדות, היינו שגם המדות שבאדם הם ע\"פ השכל, לכן, כשנעשה שינוי בשכל משתנים גם המדות. משא\"כ רצון שלמעלה מהשכל, היינו רצון עצמי שאין לו טעם, גם לא טעם כמוס, אינו משתנה. ועד\"ז למעלה, שבספירות דאצילות וגם בחיצוניות הכתר (שגם חיצוניות הכתר נכלל בבחינת אדם), שייך שינוי, אבל בפנימיות הכתר (לא אדם) אין שייך שינוי. ועפ\"ז צריך להבין בזה דמשמע מהמאמר שע\"י שישראל יושבים בסוכה נמשך בפנימיות גם מקיף הרחוק, דלכאורה, איך שייך שינוי במקיף הרחוק.\nד) <b>ויש</b> לומר הביאור בזה, דזה שמקיף הוא מוגדר בזה שאינו בא בהתיישבות הוא כמו שהוא מצד עצמו, אבל מצד עצמות אוא\"ס, שלגבי' אין חילוק בין מקיף לפנימי, גם המקיף יכול לבוא בהתיישבות. וע\"י שישראל יושבים בסוכה ממשיכים הם מעצמות אוא\"ס, ועי\"ז גם אורות המקיפים נעשים אורות מתיישבים. ויובן זה ע\"פ הידוע<sup data-n=\"1757\">13</sup> בפירוש הכתוב<sup data-n=\"1758\">14</sup> בכסה ליום חגינו, דהענינים ש(בראש השנה ו)ביום הכפורים הם בכסה (כיסוי והעלם), מתגלים הם בסוכות. דמזה מובן, שהעבודה דבסוכות תשבו היא גילוי התשובה דיום הכפורים<sup data-n=\"1759\">15</sup>, שעל ידה היא ההמשכה מעצמות אוא\"ס (כדלקמן). וע\"י העבודה דבסוכות תשבו, ההמשכה מעצמות אוא\"ס שע\"י התשובה דיום הכפורים היא בגילוי. ועי\"ז, גם אורות המקיפים נעשים אורות מתיישבים.\n<b>וע\"פ</b> הידוע<sup data-n=\"1760\">16</sup> שעבודת האדם (אתערותא דלתתא) שעל ידה נעשית ההמשכה (אתערותא דלעילא) צריכה להיות מעין ההמשכה, יש להוסיף, דזה שע\"י העבודה דבסוכות תשבו נעשה שינוי למעלה (שאורות המקיפים נעשים אורות מתיישבים) הוא לפי שהעבודה דבסוכות תשבו שייכת (גם) לענין השינוי. ויובן זה בהקדים, דהטעם (בפשטות) לזה שע\"י התשובה מתתקנים כל הפגמים הוא לפי שע\"י התשובה משתנה האדם ונעשה מציאות חדשה<sup data-n=\"1761\">17</sup>. ובלשון הרמב\"ם<sup data-n=\"1762\">18</sup> אני אחר ואיני אותו האיש שעשה אותן המעשים. דענין זה הוא בעיקר בתשובה כפשוטה.דבצדיקים<sup data-n=\"1763\">19</sup>, גם עבודת התשובה שלהם שענינה הוא שיוצאים ממצבם וממציאותם הקודמת, אסורה מכאן<sup data-n=\"1764\">20</sup>, מ\"מ כיון שצדיקים רוצים לעשות את רצון קונם, והכוונה שלמעלה (רצון קונם) בירידת הנשמה בגוף היא לבוא לתשובה, הרי בהרצון דהצדיקים (גם לפני התשובה שלהם) נכלל (בהעלם) גם היציאה ממציאותם שע\"י התשובה. משא\"כ בבעל תשובה כפשוטו, כיון שקודם (לפני התשובה) הי' במצב כזה שלא עשה רצון הקב\"ה, שהרי עשה עבירות במזיד, הרי זה שעושה אח\"כ תשובה, אין זה המשך ממצבו הקודם, וע\"י התשובה נעשה מציאות חדשה לגמרי.\n<b>ובעומק</b> יותר יש לומר<sup data-n=\"1765\">21</sup>, שענין החידוש שבתשובה כפשוטה הוא גם לגבי הרצון והכוונה דלמעלה. שהרצון והכוונה דלמעלה בבריאת העולם והאדם היא שהאדם יהי' צדיק, כמרז\"ל<sup data-n=\"1766\">22</sup> במי נמלך בנשמותיהן של צדיקים. וע\"י שחטא ופגם והעביר את הדרך (היפך הכוונה דבריאת העולם והאדם) ואח\"כ מתקן זה ע\"י התשובה, עי\"ז נמשך אור חדש שלא הי' בכוונת הבריאה. והכח להמשיך אור חדש שלא הי' בהכוונה דבמי נמלך, הוא לפי ששורש הנשמות הוא בעצמות אוא\"ס, שהוא למעלה גם משרשם בהענין דבמי נמלך. ויש לומר, דזה שע\"י התשובה משתנה האדם ממציאותו ונעשה מציאות חדשה לגמרי, חידוש אמיתי שאינו המשך ממצבו הקודם, הוא, לפי שע\"י התשובה הוא המשכת עצם הנשמה כמו שהיא מושרשת בעצמות אוא\"ס<sup data-n=\"1767\">23</sup>, ולגבי עצם הנשמה, אין נפק\"מ מצבו של האדם שהי' לפני התשובה.\n<b>ועפ\"ז</b> יש להוסיף ביאור בזה שע\"י העבודה דבסוכות תשבו (גילוי התשובה דיום הכפורים) נעשה שינוי באורות המקיפים שנעשים אורות מתיישבים, כי הענין דהמשכת עצם הנשמה שע\"י התשובה מתגלה בזה שהאדם <i>משתנה</i> ממציאותו<sup data-n=\"1768\">24</sup>, ולכן, הגילוי דהמשכת העצמות שע\"י בסוכות תשבו (גילוי התשובה דיום הכפורים) הוא בענין השינוי, שאורות המקיפים משתנים להיות אורות מתיישבים.\nה) <b>ויש</b> לומר, שהגילוי דעצם הנשמה שמושרשת בעצמות אוא\"ס (שלמעלה משורש הנשמות בהענין דבמי נמלך) שע\"י תשובה, הוא בשני ענינים. בהתשובה עצמה ובהסיבה שמביאה לתשובה. והענין הוא, דזה שהאדם עושה תשובה לאחרי שחטא הוא מצד שרש הנשמה בעצמות אוא\"ס שלמעלה מהענין דבמי נמלך. שמצד שורש הנשמות בהענין דבמי נמלך בנשמותיהן של צדיקים, ע\"י שחטא ופגם (היפךהכוונה דבמי נמלך), הוא נפרד משרשו, וזה שלאחרי שחטא הוא עושה תשובה ומשנה את מציאותו, הוא מצד גילוי שורש הנשמה בעצמות אוא\"ס, שלמעלה מהענין דבמי נמלך. ועוד ענין בזה, דהסיבה שמביאה אותו לחזור בתשובה היא לפי שנקודת היהדות שבו היא תמיד בשלימות (וכאשר מתעוררת נקודת היהדות שבו, אינו רוצה בשום אופן להיות נפרד ועושה תשובה), וזה שנקודת היהדות שבו היא תמיד בשלימות, דגם בשעת החטא הנשמה היא באמנה אתו ית'<sup data-n=\"1769\">25</sup>, הוא לפי שההתקשרות דהנשמה באלקות היא התקשרות עצמית, שלמעלה מההתקשרות שע\"י תורה ומצוות (הענין דבמי נמלך).\n<b>והחילוק</b> דשני הענינים הוא, שהגילוי דעצם הנשמה בזה שגם לאחרי החטאים הוא שב להוי', הוא שע\"י החטאים נעשה נפרד מאלקות (שלכן צריך לעשות תשובה עליהם), אלא שכיון ששורש הנשמה הוא בעצמות אוא\"ס שלמעלה מהענין דבמי נמלך, הפירוד שע\"י החטאים הוא רק בחיצוניות, ולכן ביכלתו לעשות תשובה (ע\"י גילוי הפנימיות). והגילוי דעצם הנשמה בהסיבה שמביאה אותו לחזור בתשובה, הוא, שע\"י החטאים לא נעשה מלכתחילה גרעון ח\"ו בההתקשרות העצמית דעצם הנשמה באלקות, וגם בשעת החטא היא באמנה אתו ית'. והוא ע\"ד שנתבאר לעיל (בהמאמר ד\"ה וכל אדם לא יהי'<sup data-n=\"1770\">26</sup>), דהכפרה שע\"י ההמשכה מעצמות אוא\"ס בעל הרצון היא באופן שע\"י החטאים נעשה פגם, וע\"י ההמשכה מעצמות אוא\"ס בעל הרצון שאינו מוכרח בהרצון, <i>מתכפרים</i> הפגמים. והכפרה שמצד עיצומו של יום הכפורים היא (לא באופן של פעולה, אלא) שביום זה מתגלה ההתקשרות של עצם הנשמה עם העצמות (שלמעלה מבעל הרצון), שבדרגא זו אין פגם מלכתחילה.\n<b>ועפ\"ז</b> יש להוסיף ביאור<sup data-n=\"1771\">27</sup> בזה שעיצומו של יום הכיפורים מכפר (דוקא) לשבים<sup data-n=\"1772\">28</sup>, כי בכדי שתהי' המשכת הענין דעיצומו של יום, גילוי ההתקשרות העצמית דעצם הנשמה עם העצמות, צריכה להיות איזו עשי' דהאדם [וע\"ד גילוי עצם הנשמה בראש השנה, שהיא על ידי העבודה דתמליכוני עליכם<sup data-n=\"1773\">29</sup>], וכיון שהסיבה המביאה לעשות תשובה היא התקשרות העצמית, לכן, על ידי התשובה היא המשכת הענין דעיצומו של יום.\nו) <b>וביאור</b> הענין בפרטיות יותר, יובן בהקדים מה שנתבאר לעיל (בהמאמר ד\"ה יבחר לנו<sup data-n=\"1774\">30</sup>), שבתקיעת שופר דראש השנה שעי\"ז נעשה תמליכוני עליכם, ג' ענינים. קיום המצוה דתקיעת שופר, שהיא האתערותא דלתתא המעוררת את הרצון הגלוי. והתשובה דתקיעת שופר, שעל ידה נמשך ההחלט שברצון הנעלם (מחשבה ורצון המוחלט) ולמעלה יותר ברצון המוחלט בעצמותו שע\"י האתעדל\"תיתעורר הרצון גלוי. והביטול הפנימי שמצד עצם הנשמה, שעי\"ז נמשך רצון המוחלט עצמו. וע\"פ הידוע<sup data-n=\"1775\">31</sup> שהענין דבנין המלכות הוא במשך כל עשרת ימי תשובה, יש לומר, שגם בעשרת ימי תשובה צריכה להיות (נוסף על עבודת התשובה) גם עבודה שמצד עצם הנשמה<sup data-n=\"1776\">32</sup>. וזהו שבעשרת ימי תשובה אומרים שיר המעלות ממעמקים<sup data-n=\"1777\">33</sup>, ואיתא בזהר<sup data-n=\"1778\">34</sup> וההוא עמיקא דעמיקתא (מעמקים לשון רבים) אקרי תשובה. ומבאר כ\"ק מו\"ח אדמו\"ר בהמשך הנ\"ל<sup data-n=\"1779\">35</sup> שהם ב' העומקים דרצון הנעלם ורצון המוחלט בעצמותו. דההמשכה מהעומק דרצון הנעלם היא ע\"י צעקת הקול הבאה מהמקיף דחי', וההמשכה מהעומק דרצון המוחלט היא ע\"י צעקת הלב הבאה מהמקיף דיחידה. ובמקום אחר איתא בזהר<sup data-n=\"1780\">36</sup> שיר המעלות סתם ולא פירש מאן אמרו, אלא שיר המעלות דזמינין כל בני עלמא למימר. ובהמשך הענין שם וכי אמר דוד הכי והא כתיב<sup data-n=\"1781\">37</sup> בכל לבי דרשתיך כו' מאי בעי ממעמקים אלא הכי תאנא כל ב\"נ כו' מעיקרא דכל עיקרין. ומבואר בחסידות<sup data-n=\"1782\">38</sup>, שהדיוק בזהר וכי אמר דוד הכי כו' הוא, דכיון שכבר אמר בכל לבי דרשתיך, שבכל לבי הוא פנימיות הלב, מה צריך לומר ממעמקים. ומבאר, שצריך להמשיך מעיקרא דכל עיקרין, מפנימיות ועצמות א\"ס, ובכדי להמשיך משם הוא ע\"י העבודה שמפנימיות ועצמות הנפש, ממעמקים, שלמעלה מהעבודה דפנימיות הלב (בכל לבי).\n<b>ויש</b> לומר, דבמאמר הזהר וההוא עמיקא דעמיקתא אקרי תשובה, מדבר בענין התשובה המשכת ההחלט שברצון הנעלם וברצון המוחלט שע\"י האתעדל\"ת יתעורר הרצון גלוי, שע\"י התשובה דראש השנה ודעשי\"ת. וכיון שההחלט שברצון הנעלם וברצון המוחלט הוא בנוגע לרצון הגלוי, לכן, גם העבודה שעל ידה הוא המשכת ההחלט היא בהדרגא דעצם הנשמה ששייכת לכחות הגלויים, דבכללות הם המקיפים דחי' ויחידה. ובהמאמר שיר המעלות סתם כו' (שאין מזכיר שם ענין התשובה) מדבר בענין המשכת רצון המוחלט עצמו (פנימיות ועצמות א\"ס, עיקרא דכל עיקרין), דהמשכה זו היא ע\"י העבודה שמצד עצם הנשמה (פנימיות ועצמות הנפש). וזהו שבמאמר זה (דוקא) אומר שיר המעלות סתם כו' דזמינין כל בני עלמא למימר, כי העבודה שמצד עצם הנשמה היא בכולם בשוה.\nז) <b>ויש</b> לומר, דבראש השנה ויום הכפורים העבודה דממעמקים היא נעלית יותר מהעבודה דממעמקים שבהימים שבין ראש השנה ליום הכפורים. דבעשרת ימי תשובה, שענינם הוא (כשמם) ימי <i>תשובה</i> (והענין דתמליכוני עליכם אינו בגילויכ\"כ בימים אלה), העבודה דממעמקים (שבגילוי) היא (בעיקר) בהעומק דעצם הנשמה ששייכת לכוחות הגלויים, ובראש השנה שעיקר ענינו הוא תמליכוני עליכם [דענין זה הוא בעיקר מצד עצם הנשמה], העבודה דממעמקים היא בהעומק דעצם הנשמה שלמעלה משייכות לכחות הגלויים. ועד\"ז ביום הכפורים, דכיון שעיקר ענינו הוא הכפרה שמצד עיצומו של יום, גילוי ההתקשרות העצמית דעצם הנשמה עם העצמות, לכן, גם העבודה דיום הכפורים היא מצד העומק דעצם הנשמה שלמעלה משייכות לכחות הגלויים.\n<b>ויש</b> לומר, שהעבודה שמצד העומק דעצם הנשמה ביום הכפורים היא בהתשובה דיום הכפורים, שהיא נעלית יותר מהתשובה דכל ימי השנה וגם מהתשובה דעשרת ימי תשובה<sup data-n=\"1783\">39</sup>. והענין הוא, דבתשובה בכלל, ההתקשרות העצמית דעצם הנשמה עם העצמות היא רק הסיבה שמביאה לתשובה, אבל התשובה עצמה [שענינה הוא חרטה על שעשה היפך הרצון וקבלה לקיים רצונו ית'] היא מצד עצם הנשמה ששייכת לכחות הגלויים שמגעת בבעל הרצון, והתשובה דיום הכפורים היא (בעיקר) להיות מקושר עם העצמות, ולכן נרגש בה בגילוי ההתקשרות דעצם הנשמה (שלמעלה משייכות לכחות הגלויים) עם העצמות (שלמעלה מבעל הרצון)<sup data-n=\"1784\">40</sup>. ויש לומר, דזהו מ\"ש הרמב\"ם<sup data-n=\"1785\">41</sup> שיום הכפורים הוא זמן תשובה לכל, שהכוונה ב\"לכל\" היא (גם) לכל בשוה. דבהתשובה שבכל ימי השנה (כולל גם התשובה דעשי\"ת) שהיא מצד הדרגא דעצם הנשמה ששייכת לכחות הגלויים, ישנם כו\"כ חילוקי דרגות. והתשובה דיום הכפורים שהיא מצד עצם הנשמה שלמעלה משייכות לכחות הגלויים, היא בכולם בשוה.\nח) <b>וזהו</b> בסוכות תשבו גו' כל האזרח בישראל ישבו בסוכות גו' כי בסוכות הושבתי גו', דכל האזרח בישראל ישבו בסוכות וכי בסוכות הושבתי גו' הם שני טעמים על בסוכות תשבו (כמבואר בהמאמר דהמשך ראש השנה תש\"ג, הובא לעיל סעיף ב). והענין הוא, דבסוכות תשבו הוא גילוי התשובה דיום הכפורים, ובהתשובה דיום הכפורים, ג' ענינים. התשובה עצמה, ושני ענינים בשרש וסיבת התשובה. דהתשובה עצמה (גם התשובה דיום הכפורים) היא שהאדם <i>משנה</i> את עצמו, שיוצא ממציאותו הקודמת ונעשה מציאות חדשה. דשינוי זה הוא בכחות הגלויים דהנשמה. ושינוי זה שבכחות הגלויים דהאדם הוא ע\"י שמעורר ומגלה עצם הנשמה שבו, היינו עצם הנשמה ששייכת לכחות הגלויים. [ועד\"ז הוא בנוגע למעלה, דזה שהאדם נעשה <i>מרוצה</i> לפניו ית' כמו קודם החטא<sup data-n=\"1786\">42</sup> הוא, כי ע\"י התשובה נמשך רצון חדש מאוא\"ס בעל הרצון]. ועוד ענין בהתשובה דיום הכפורים, שנרגש בה בגילוי, שהשורשוהסיבה האמיתית דתשובה הוא ההתקשרות דעצם הנשמה (שלמעלה משייכות לכחות הגלויים) עם העצמות (שלמעלה מבעל הרצון). ולכן, גם בהענין דבסוכות תשבו (שהוא הגילוי דהתשובה דיום הכפורים), ג' הענינים. הענין דבסוכות תשבו עצמו – השינוי במקיף הקרוב, שנעשה אור מתיישב. והטעם על זה הוא – כי בסוכות הושבתי גו' בדרך אתערותא דלעילא. ויש לומר, שהוא ע\"ד המובא לעיל סעיף ו דזה שע\"י אתעדל\"ת מתעורר הרצון גלוי (אף שהאתעדל\"ת היא באין ערוך לגבי הרצון) הוא לא מצד הרצון הגלוי עצמו (דכיון שרצון הגלוי שייך לעולמות הוא מוגדר בזה שהנבראים הם באין ערוך לגבי' ואין ביכלתם לעורר אותו), אלא לפי שכן הוחלט ברצון המוחלט. ועד\"ז הוא בהענין דבסוכות תשבו, שהשינוי כביכול שנעשה במקיף הקרוב להיות אור מתיישב הוא, כי בסוכות הושבתי בדרך אתערותא דלעילא, המשכה מעצמות אוא\"ס שלגבי' אין חילוק בין מקיף לפנימי וגם המקיף יכול לבוא בהתיישבות. [ע\"ד שע\"י התשובה נמשך <i>רצון</i> (חדש) מאוא\"ס בעל הרצון]. ועוד טעם על בסוכות תשבו – כל האזרח בישראל ישבו בסוכות, במקיף הרחוק. דענין הישיבה (התיישבות) במקיף הרחוק אינו באופן דפעולה [כי במקיף הרחוק, בחינת לא אדם, אין שייך שיהי' בו פעולה ושינוי, כנ\"ל סעיף ג], אלא שכל האזרח בישראל, ישבו בסוכות (מקיף הרחוק) מצד עצמם, לפי שהם מושרשים בהעצמות. [וזהו שאמרו רז\"ל<sup data-n=\"1787\">43</sup> עה\"פ כל האזרח בישראל ישבו בסוכות מלמד שכל ישראל ראויים לישב בסוכה אחת, כי בדרגא זו כל ישראל שוים]. והוא ע\"ד הענין דעיצומו של יום הכפורים, שמצד ההתקשרות העצמית דעצם הנשמה עם העצמות אין פגם מלכתחילה. וכמו שביום הכפורים, הענין דעיצומו מאיר בגילוי גם בהתשובה דיום הכפורים, שבהתשובה דיום הכפורים נרגש (כנ\"ל) שהיא נמשכת מההתקשרות העצמית דעצם הנשמה עם העצמות, עד\"ז הוא בסוכות, שכל האזרח בישראל ישבו בסוכות הוא טעם על בסוכות תשבו, דזה שמקיף הקרוב נמשך בפנימיות ונעשה אור מתיישב, נרגש בו, שהטעם על זה הוא כל האזרח בישראל ישבו בסוכות, במקיף הרחוק, התקשרות העצמית דעצם הנשמה עם העצמות.\n**********",[["1744","*","יצא לאור ב<b>קונטרס חג הסוכות – תנש\"א</b>, \"לקראת חג הסוכות . . <i>ערחה\"ס</i>,<i> שנת ה'תנש\"א</i>\"."],["1745","1","מאמר זה הוא המשך למאמרים שלפניו ד\"ה יבחר לנו גו' דראש השנה, וד\"ה וכל אדם לא יהי' גו' דשבת תשובה שנה זו (תשכ\"ג) – לעיל ע' א ואילך. ע' עד ואילך."],["1746","2","אמור כג, מב-מג."],["1747","3","סה\"מ ה'תש\"ג ס\"ע 43 ואילך. וראה שם ע' 44."],["1748","4","ראה סוכה יא, ב (לפי דיעה אחת) שענני כבוד היו. וכ\"ה בפרש\"י עה\"פ. וכ\"ה להלכה (שו\"ע אדה\"ז הל' סוכה ר\"ס תרכ\"ה) – דמזה מובן, שבסוכות הושבתי הוא רק בחיק הבורא."],["1749","5","בהדיוק שבתחלת המאמר דשנת ה'תש\"ג (ע' 44) מפורש רק ענין הראשון, אבל מהביאור שבסיום המאמר (ע' 52, נעתק לקמן בפנים) שהאתעדל\"ע דבסוכות הושבתי היתה על מנת שעי\"ז תהי' אח\"כ העבודה דבסוכות תשבו בכח עצמם, מובן, שבהדיוק (בתחילת המאמר) נכלל גם ענין השני, דכיון שבסוכות תשבו הוא ע\"י בסוכות הושבתי, אין זה עבודה בכח עצמו."],["1750","6","בסיומו (סה\"מ שם ע' 52)."],["1751","7","ראה לקמן סעיף ג."],["1752","8","להעיר מפירוש הידוע עה\"פ (תהלים פט, א) משכיל לאיתן האזרחי – סה\"מ ה'תש\"ח ע' 61. <i>ובכ\"מ</i>."],["1753","9","ראה גם סד\"ה זה ה'תש\"י (סה\"מ ה'תש\"י ע' 67) \"וכל האזרח בישראל ישבו בסוכות, שהם יושבים תמיד בסוכה\"."],["1754","10","ועד בנוגע לפס\"ד במעשה בפועל, כידוע הראי' לזה מ\"שעטנז\" (נדה סא, ב) – ראה לקו\"ש ח\"ג ע' 782. ובכ\"מ."],["1755","11","ראה בארוכה המשך באתי לגני ה'שי\"ת סי\"ח (סה\"מ ה'תש\"י ע' 153 ואילך). ד\"ה באתי לגני ה'תשכ\"ח (לקמן ח\"ב ע' שט ואילך). ה'תשמ\"ח (שם ע' תו ואילך). <i>וש\"נ</i>."],["1756","12","שמואל-א טו, כט."],["1757","13","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380937\" data-slug=\"likkutei-torah\" data-id=\"4001380937\">לקו\"ת</a> דרושים לר\"ה נד, סע\"ג ואילך. ועוד. – נסמנו בד\"ה ולקחתם לכם גו' ה'תשל\"ט הערה 54 (לעיל ע' קנא)."],["1758","14","תהלים פא, ד."],["1759","15","ולהעיר מהידוע דסכך הסוכה נעשה מענן הקטורת דיום הכפורים – עט\"ר שער יום הכפורים פ\"ב (כח, א). ועוד. – נסמנו בד\"ה בסוכות תשבו גו' ה'תשמ\"א הערה 5 (לעיל ע' קסג)."],["1760","16","ראה בארוכה ד\"ה באתי לגני ה'תשכ\"ט ס\"ט (לקמן ח\"ב ע' שכה). <i>וש\"נ</i>."],["1761","17","סמ\"ג מ\"ע ט\"ז. ר\"ן לר\"ה טז, ב. – הובאו בחד\"א מהרש\"א לר\"ה שם."],["1762","18","הל' תשובה פ\"ב ה\"ד."],["1763","19","בהבא להלן ראה גם לקמן ע' רלא."],["1764","20","לשון רש\"י עה\"פ שמות ג, ג. וראה ספר השיחות ה'תש\"ב ע' 47 (נעתק לקמן ע' רל הערה 43) שהו\"ע התשובה דצדיקים."],["1765","21","ראה גם לקמן ע' ריח ואילך. לקמן ח\"ד ס\"ע קעב ואילך. וראה גם ד\"ה וכל אדם לא יהי' גו' שנה זו (תשכ\"ג) סעיף ח, ובהערה 67 שם (לעיל ע' פ)."],["1766","22","ב\"ר פ\"ח, ז. רות רבה פ\"ב, א (ג)."],["1767","23","אבל מצד שורש הנשמה בהענין דבמי נמלך, אי אפשר להיות שינוי זה כדלהלן ס\"ה."],["1768","24","להעיר, שהשינוי שנעשה בהאדם ע\"י התשובה הוא לא רק בהכחות הפנימיים אלא גם בענין הקבלת עול, דקב\"ע היא מצד עצם הנשמה שלמעלה מכחות הגלויים. ועפ\"ז יובן, שע\"י התשובה דיום הכפורים נעשה (בחג הסוכות) שינוי <i>בהמקיפים</i>, שנעשים אורות מתיישבים."],["1769","25","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא ספכ\"ד</a>."],["1770","26","סעיף ז (לעיל ע' עט ואילך)."],["1771","27","נוסף על הביאור שבהמאמר ד\"ה וכל אדם הנ\"ל שם."],["1772","28","רמב\"ם הל' תשובה פ\"א ה\"ג. וראה ד\"ה הנ\"ל הערה 58."],["1773","29","ר\"ה טז, א. שם לד, ב. וראה בארוכה ד\"ה יבחר לנו גו' שנה זו (תשכ\"ג) ס\"ו (לעיל ע' ה)."],["1774","30","סעיף ט (לעיל ע' ח)."],["1775","31","פרע\"ח שער כד (שער ראש השנה). ובכ\"מ. וראה גם סה\"מ ה'תש\"ג דלהלן הערה 35."],["1776","32","וענין ה\"מצוה\" שבעשי\"ת – יש לומר, שבעשי\"ת הזהירות במצוות היא יותר מבכל השנה (ראה שו\"ע אדה\"ז או\"ח הל' ראש השנה סתר\"ג. ובכ\"מ)."],["1777","33","תהלים קל, א. וראה בהנסמן לעיל ע' קיט הערה 2."],["1778","34","ח\"ג ע, א."],["1779","35","ד\"ה שיר המעלות ה'תש\"ג (סה\"מ ה'תש\"ג ע' 25 ואילך)."],["1780","36","ח\"ב סג, סע\"א ואילך."],["1781","37","תהלים קיט, י."],["1782","38","סה\"מ תרס\"ח ע' טז."],["1783","39","דנוסף להמשכת הענין דעיצומו של יום ע\"י התשובה דיום הכפורים, גם התשובה עצמה היא נעלית יותר – ראה בהמאמר ד\"ה וכל אדם לא יהי' ס\"ב (לעיל ע' עה)."],["1784","40","ועפ\"ז יומתק שע\"י התשובה דיום הכפורים נמשך הענין דעיצומו של יום (ראה לעיל ס\"ה), כי ענינה של התשובה דיום הכפורים (לא רק סיבת התשובה אלא גם התשובה עצמה) הוא לגלות ההתקשרות העצמית."],["1785","41","הל' תשובה פ\"ב ה\"ז."],["1786","42","ראה רמב\"ם שם פ\"ז ה\"ד."],["1787","43","סוכה כז, ב. וראה ד\"ה בסוכות תשבו גו' ה'תשל\"ח (לעיל ס\"ע קלח ואילך)."]]],[1500360027,"(הנחה)\n<b>הללו</b> את הוי' כל גוים שבחוהו כל האומים כי גבר עלינו חסדו ואמת הוי' לעולם הללוי'<sup data-n=\"1788\">1</sup>. וצריך להבין, מהו הטעם דכי גבר <i>עלינו</i> חסדו שבשביל זה יהללו וישבחו אותו הגוים והאומים, וכמו שמקשה בגמרא פסחים<sup data-n=\"1789\">2</sup> אומות העולם מאי עבידתייהו. והנה רש\"י מפרש (בתירוץ הגמרא שם), דאף שגבר <i>עלינו</i> חסדו, מ\"מ, מכיון שזהו בגילוי שגם הם רואים זאת (\"דחזיתו שעשה לי\"), לכן עליהם להלל ולשבח. אמנם אין זה מספיק וכמש\"כ במאמר ד\"ה הללו את הוי' לרבינו הזקן<sup data-n=\"1790\">3</sup> ש\"אין זה טעם מספיק\". שמלשון זה משמע ש\"כי גבר עלינו חסדו\" הוא טעם להללו את הוי' כל גוים גו' (שמזה משמע שמפרש כפירוש רש\"י הנ\"ל), אלא שאי\"ז טעם מספיק<sup data-n=\"1791\">4</sup>. ולכן מפרש הרשב\"ם שם שכי גבר עלינו חסדו הו\"ע בפ\"ע, וכי כאן פי' כש\"כ שהגוים והאומים עליהם להלל ולשבח על הגבורות ונפלאות שעשה בעולם, וכ\"ש אנו שגבר עלינו חסדו יותר מכל אומה ולשון.\n<b>והנה</b> השייכות מיוחדת דהללו את הוי' כל גוים שבחוהו כל האומים לחג הסוכות הוא כדאיתא בגמרא<sup data-n=\"1792\">5</sup> ובמדרש<sup data-n=\"1793\">6</sup> שהע' פרים שמקריבים בחג הסוכות הם כנגד הע' אומות, שהם כללות כל האומות, שמצד זה הנה בחג הסוכות הללו את הוי' <i>כל</i> גוים שבחוהו <i>כל</i> האומים. וצריך להבין<sup data-n=\"1794\">7</sup>, שהרי איתא בזהר<sup data-n=\"1795\">8</sup> שבז' ימי החג זמין לבחי' אושפיזין והם אבותינו אברהם יצחק ויעקב וכו' עד דוד מלכא משיחא שהוא השביעי, ואיך זה מתאים עם המבואר בגמרא ומדרש שהע' פרים הם כנגד הע' אומות. והגם שכתב הרמ\"ז שם<sup data-n=\"1796\">9</sup> והשכל היטיב כו' שהאושפיזין שבזהר הוא פי' אחר, עדיין אינו מספיק וכמש\"כ בהמאמר שם, והרי אלו ואלו דברי אלקים חיים<sup data-n=\"1797\">10</sup>, ואיך יבואו שני פירושים אלו יחד, ובפרט על פי הידוע<sup data-n=\"1798\">11</sup> (וגם להלכה למעשה) שכל הענינים שבתיבה אחת שייכים זל\"ז, הרי מובן מזה במכ\"ש בנדו\"ד (שב' הפירושים אינם רק בתיבה אחת אלא בכל הענין כולו) שפירוש הגמרא והמדרש וכן פי' המדרש דבז' הימים ה\"ז סעודת המלך לבני המדינה והסועדים כל שבעת ימי הסוכות הם הע' שריםופירוש הזהר שבחג הסוכות זמין להסעודה לבחי' אושפיזין עילאין כו', מכיון ששני הענינים הם בתורת אמת, יש ביניהם שייכות אמיתית. ובפרט לפי מה שמסיים בגמרא ומדרש שם דבשמיני עצרת פר יחידי כו' כנגד אומה יחידה משל למלך כו' שאמר עשו לי סעודה גדולה וזימן את כל בני המדינה ליום אחרון אמר לאוהבו עשו לי סעודה קטנה, באו ונגלגל אני ואתה במה שתמצא. שסעודה גדולה בהנמשל הו\"ע הע' פרים וסעודה קטנה הו\"ע פר אחד שמקריבין בשמיני עצרת. והרי מובן ריחוק הערך דע' פרים (שעבור כל בני המדינה) לפר אחד (דאוהבו), הנה לפי פירוש הזהר שגם ז' ימי החג זמין לאושפיזין עילאין (דמזה עצמו שאומר הלשון <i>זמין</i> לאושפיזין כו' דוגמת לשון המדרש משל למלך שזימן כו' משמע שהם שייכים זל\"ז), שהם אבותינו אברהם יצחק ויעקב כו' עד לדוד מלכא, צריך להבין, מהו החידוש שבהסעודה קטנה דשמיני עצרת על סעודת ז' ימי החג.\n<b>והנה</b> מ\"ש כי גבר עלינו חסדו, חסדו דייקא ולא חסד סתם, י\"ל שהוא ע\"ד מרז\"ל<sup data-n=\"1799\">12</sup> גבי כ\"ו כי לעולם חסדו שקאי על כ\"ו דורות שלפני מ\"ת שהיו ניזונין בחסדו של הקב\"ה, ומבואר בזה בכמה מקומות<sup data-n=\"1800\">13</sup> שקאי על בחי' חסד שלמעלה מהשתלשלות, חסד דאריך אנפין. שמזה מובן גם בכי גבר עלינו חסדו, שחסדו הוא בחי' חסד שלמעלה מהשתלשלות, וגבר עלינו חסדו הוא התגבורת בבחי' חסדו, היינו שהוא נעלה יותר גם מבחי' חסד דאריך. שהיא בחינה נעלית ביותר. וכן גם בנוגע למ\"ש לאח\"ז ואמת הוי' לעולם – שענין \"והוי' אמת\" הוא כמ\"ש הרמב\"ם <i>בהתחלת</i> ספרו<sup data-n=\"1801\">14</sup> הוא לבדו האמת ואין לאחר אמת כאמיתתו, ובענין זה כותב ברמב\"ם שם \"הוא שהנביא אומר\", כי נבראים ובדעתם<sup data-n=\"1802\">15</sup> אין להם ידיעה בהענין דאמיתתו ית', לכן מדגיש \"הוא <i>שהנביא</i> אומר\" [וכ\"ה גם במש\"כ שם לאח\"ז \"והוא שהתורה אומרת אין עוד מלבדו אין שם מצוי אמת מלבדו כמותו\", שמדייק בלשונו והוא שהתורה אומרת (ולא שנאמר), כי ידיעת הפלאת מציאותו אין שם מצוי אמת מלבדו כמותו אי\"ז בכחו של הנברא, ורק שהתורה אומרת כו']. שמזה מובן גודל ההפלאה דבחי' ואמת הוי', ועכ\"ז נאמר ואמת הוי' לעולם, שבחינת ואמת הוי' נמשך לעולם. ויתירה מזו, לפי הפירוש אשר כי גבר עלינו חסדו ואמת הוי' גו' הוא טעם להללו את הוי' כל גוים שבחוהו כל האומים (כפירש\"י), נמצא שבחי' גבר עלינו חסדו, שהוא נעלה יותר גם מבחי' חסדו שלמעלה מהשתלשלות (כנ\"ל), וכן בחי' ואמת הוי', פועל גם בידיעת <i>כל</i> הגוים והאומים. דאף שבכללות, הידיעה דאוה\"ע הוא רק בשם אלקים וכמ\"ש<sup data-n=\"1803\">16</sup> אלקים יענה את שלום פרעה, ויניקתם בשם אלקים גופא הוא רק מהמ\"ח צירופים אחרונים דשם אלקים<sup data-n=\"1804\">17</sup>, ושם הוי' שייך רק לישראל עם <i>קרובו</i>, בכל זה, בחג הסוכות, נרגש בחי' הוי', וגם בחי' ואמת הוי', גם לכל הגוים והאומים עד שצ\"ל הללו גו' שבחוהו.<b>ולהבין</b> כל זה, צריך להקדים מ\"ש בההפטרה דראש והתחלת סוכות, שבה מבואר בגילוי מעניני חג הסוכות עוד יותר מבהקריאה דסוכות. דכמו בכללות, הנה הענינים דתושב\"כ מתבארים בתושבע\"פ, עד\"ז הוא גם בהכ\"ד ספרים שבתושב\"כ גופא, שהענינים שנאמרו בתורה בקיצור וברמז כו', הנה בנביאים ובכתובים הם בגילוי יותר, כנראה גם בפשטות<sup data-n=\"1805\">18</sup>. הנה בההפטרה דחג הסוכות נאמר<sup data-n=\"1806\">19</sup> ועמדו רגליו ביום ההוא על הר הזיתים, ויש בזה ב' פירושים<sup data-n=\"1807\">20</sup>. פירוש אחד<sup data-n=\"1808\">21</sup> שועמדו רגליו הוא המשפט שיהי' לע\"ל, שהמשפט דדור המבול בעוה\"ז הי' בישיבה, כמ\"ש<sup data-n=\"1809\">22</sup> הוי' למבול ישב, והמשפט דלע\"ל יהי' בעמידה וכמ\"ש ועמדו רגליו גו'. וזהו ג\"כ המשך הכתובים שבההפטרה, שבתחילה<sup data-n=\"1810\">23</sup> נאמר ואספתי את כל הגוים גו' ויצא ה' ונלחם בגוים ההם כיום הלחמו גו' ועמדו רגליו גו' עד והי' הוי' למלך על כל הארץ ביום ההוא יהי' הוי' אחד ושמו אחד, שועמדו רגליו הו\"ע המשפט שישפוט את הגוים כו'. וכהמדרש הובא בבחיי<sup data-n=\"1811\">24</sup> עד מדרך כף רגל עד שיבוא יום כו' ועמדו רגליו גו'. ופירוש הב' הוא שועמדו רגליו ביום ההוא על הר הזיתים קאי על בחי' נעלית ביותר שיהי' לעתיד. דהנה נא'<sup data-n=\"1812\">25</sup> ארץ זית שמן, וידוע ששמן מורה על בחי' חכמה, וזיתים שמהם עושים שמן מורים לבחי' מקור החכמה, והר הזיתים (שהוא המקום שבו צומחים זיתים) מקור הזיתים, הוא למעלה גם מבחי' זיתים, ו\"<i>על</i> הר הזיתים\" הוא למעלה גם מבחי' הר הזיתים. וזהו שאומר ועמדו רגליו גו' על הר הזיתים גו' ונבקע הר הזיתים, היינו שלע\"ל יתגלה גם בחי' על הר הזיתים. וזהו ג\"כ ההמשך למ\"ש לאח\"ז ביום ההוא יהי' הוי' אחד ושמו אחד, שבכדי שיהי' הוי' אחד ושמו אחד, כמו שאני נכתב אני נקרא<sup data-n=\"1813\">26</sup>, הוא דוקא ע\"י בחינה נעלית ביותר, ועד בחי' על הר הזיתים. והנה עפ\"י האמור לעיל שכל הפירושים שעל פסוק אחד שייכים זל\"ז, צריך לומר, שבחי' על הר הזיתים שהיא מדריגה נעלית ביותר, שייכת לענין המשפט שיהי' לע\"ל וצריך להבין מהו השייכות דב' ענינים אלו.\n<b>ויובן</b> זה בהקדים תחלה ביאור פירוש השני שבפסוק ועמדו רגליו ביום ההוא על הר הזיתים. הנה שמן הוא בחי' חכמה, וכמבואר עה\"פ<sup data-n=\"1814\">27</sup> ואספת דגנך תירושך ויצהרך, שיין הוא בחי' בינה ושמן הוא בחי' חכמה<sup data-n=\"1815\">28</sup>. והנה<sup data-n=\"1816\">29</sup> ידוע שמים הוא בחי' חכמה, וארז\"ל<sup data-n=\"1817\">30</sup> אין מים אלא תורה שתורה היא חכמתו של הקב\"ה, כי בחכמהישנם, בכללות, ב' מדריגות. מדריגה א' היא בחי' חכמה (שבגילוי) עד לבחי' חכמה עילאה, ומדריגה ב' היא בחי' חכמה סתימאה. וזהו ההפרש בין מים לשמן, שמים הוא בחי' חכמה הגלוי', בדוגמת המים שהם בטבע הגילוי, שמים יורדים ממקום גבוה למקום נמוך<sup data-n=\"1818\">31</sup>, והיינו שהמים מצד עצמם הם בטבע ההמשכה והגילוי, עד שנמשכים ומתגלים גם במקום נמוך. משא\"כ השמן מצד עצמו הוא טמון ומכוסה בהזיתים, וצריך להשתדלות מיוחדת, כתישה, שעי\"ז דוקא נמשך בגילוי. דכמו\"כ הוא בבחי' חכמה סתימאה שמצד עצמה היא בסתימות ובהעלם, וגם כשנמשך ממנה בחי' חכמה הגלוי', אי\"ז שבחי' חכמה סתימאה עצמה באה בגילוי, כי אם, שבחי' חכמה סתימאה נשארת בהעלם, ורק שהיא סיבה שעל ידה נמשך גילוי בחכמה. וכמו שידוע הדוגמא בזה בכחות האדם, שכח המשכיל שממנו נמצא המצאת החכמה, הנה כח המשכיל עצמו נשאר בהעלם, ודלא כההמשכה מחכמה לבינה, בחי' נקודה בהיכלא<sup data-n=\"1819\">32</sup>, שנקודת החכמה עצמה נמשכת בבינה, שהנקודה עצמה באה בהמרחב דבינה עד שנעשית היכל ופועלת (שומרת) בהיכל, משא\"כ בההמשכה דשכל הגלוי מכח המשכיל, הרי כח המשכיל נשאר בהעלם ורק שממנו נמצא שכל הגלוי. דכמו\"כ הוא למעלה באופן המשכת החכמה גלוי' מחכמה סתימאה, שבחי' חכמה סתימאה נשארת בהעלם ורק שממנה נמצאת בחי' חכמה הגלוי', וכמ\"ש<sup data-n=\"1820\">33</sup> והחכמה מאין תמצא שהמשכת חכמה הגלוי' מחכמה סתימאה היא בדרך מציאה, ועד שבחי' חכמה סתימאה לגבי חכמה הגלוי' נקראת בשם אין, ועד שאופן המשכת חכמה הגלוי' מחכמה סתימאה הוא ע\"י פרסא, או (כפי שנאמר לפעמים הלשון) ע\"י צמצום. וזהו ההפרש בין מים לשמן, דמים מורה לבחי' חכמה הגלוי' שהיא ראשית הספירות ויש לה שייכות להט\"ס שלאחרי' ובפרט לספירת הבינה, משא\"כ שמן מורה על חכמה סתימאה שהיא נבדלת מהספירות, גם מבחי' חכמה, ורק שממנה נמצאת החכמה, כנ\"ל. והנה טעם הדבר מה שאופן המשכת חכמה הגלוי' מבחי' חכמה סתימאה הוא מה שבחי' חכמה סתימאה עצמה אינה נמשכת בבחי' חכמה הגלוי' ורק שממנה נמצאת החכמה הוא לפי שגם המשכת בחי' חכמה סתימאה עצמה מהבחינה שלמעלה ממנה הוא באופן כזה. דבחי' חכמה סתימאה הוא בחי' חכמה שבכתר והמשכתה הוא מבחי' כתר שבכתר, הנה אופן המשכת בחי' חכמה שבכתר מבחי' כתר שבכתר הוא שבחי' כתר שבכתר הוא רק סיבה להמשכת בחי' חכמה סתימאה, דזהו מ\"ש והחכמה מאין תמצא, ש\"והחכמה\" קאי (גם) על חכמה סתימאה, וכידוע דחכמה סתימאה היא שרש הנאצלים וכמשי\"ת לקמן, הנה אופן התהוותה הוא בדרך תמצא, דכתר שבכתר הוא בחי' אין לגבי חכמה סתימאה, וממנה תמצא בחי' חכמה סתימאה. ולהיות שאופן המשכת חכמה סתימאה עצמה הוא באופן דמאין תמצא, לכן גם המשכת חכמה הגלוי' ממנה הוא באופן זה. ובזה יובן מה שישנם ב' דיעות<sup data-n=\"1821\">34</sup> בענין שמן שצףע\"ג היין אם הוא חיבור או אינו חיבור, דלכאורה א\"מ, והרי שמן ויין הם חכמה ובינה, וחכמה ובינה הם תרין רעין דלא מתפרשין, ומהו טעם הדיעה דשמן שצף ע\"ג היין אינו חיבור. אך הענין הוא, דלהיות ששמן מורה על בחי' חכמה סתימאה כנ\"ל, ובחי' חכמה סתימאה היא נבדלת בערך מבחי' חכמה הגלוי', ועד שישנו ענין בחכמה סתימאה שאינו בא בגילוי כלל בחכמה הגלוי' אפילו לא בדרך סיבה (והיינו דנוסף על זה מה שאופן המשכת חכמה הגלוי' מחכמה סתימאה הוא שבחי' חכמה סתימאה עצמה נשארת בהעלם והיא רק סיבה להמצאת חכמה הגלוי' כנ\"ל, ישנו ענין בחכמה סתימאה שאינו בא בגילוי כלל בבחי' חכמה הגלוי') ומכ\"ש שאי\"ז בא בגילוי בבינה, לכן ישנה דיעה דשמן שצף ע\"ג היין אינו חיבור.\n<b>והנה</b> כאמור לעיל, דכמו שהמשכת חכמה הגלוי' מחכמה סתימאה הוא רק בדרך תמצא, עד\"ז הוא גם בנוגע להמשכת חכמה סתימאה מבחי' שלמעלה ממנה. דזהו<sup data-n=\"1822\">35</sup> ג\"כ מהפי' במ\"ש<sup data-n=\"1823\">36</sup> נעוץ תחלתן בסופן וסופן בתחלתן, דתחלתן קאי על חכמה סתימאה שהיא שרש הנאצלים כנ\"ל, וסופן קאי על בחי' הכתר (שבכתר) <i>דמלכות</i> דא\"ק נעשה כתר [ובכללות הבחינות שלמעלה מהשתלשלות, בחי' מלכות דא\"ק, ולמעלה יותר בחי' מלכות דא\"ס שקודם הצמצום, והוא בחי' אות תי\"ו, סיום כל האותיות, כמבואר בלקו\"ת<sup data-n=\"1824\">37</sup>], שלכן נקרא סוף. הנה השייכות דתחלתן לסופן אינו שייכות בהשתלשלות והדרגה, ורק באופן של נעיצה, שזהו הלשון <i>נעוץ</i> תחלתן בסופן כו'. וכמו שלהפירוש הרגיל המבואר ברוב המקומות בהמאמר נעוץ תחלתן בסופן וסופן בתחלתן (שסופן קאי על סיום ההשתלשלות) הרי מובן שנעיצת התחלה בסוף והסוף בהתחלה אינו בדרך שייכות בסדר השתלשלות והדרגה, שלכן נעיצת התחילה היא בהסוף ונעיצת הסוף הוא בהתחילה (ולא כבסדר השתלשלות שכל מדריגה שייכת למדריגה שבקירוב אלי'), הנה כמו\"כ הוא להפירוש שסופן קאי על בחי' שלמעלה מתחלתן, דמה שנעוץ תחלתן בסופן וסופן בתחלתן אינו בדרך שייכות שבהדרגה ורק בדרך נעיצה, ובחי' סופן אינו נמשך בבחי' תחלתן והוא רק סיבה אלי', כנ\"ל.\n<b>וזהו</b> ג\"כ מה שנתבאר במאמרים הקודמים<sup data-n=\"1825\">38</sup> במ\"ש<sup data-n=\"1826\">39</sup> הוי' אלקי אתה ארוממך גו' כי שמת מעיר לגל, שאיתא בזהר<sup data-n=\"1827\">40</sup> שהוי' הוא בחי' נקודה עילאה סתימא. ונתבאר בזה<sup data-n=\"1828\">41</sup> דמ\"ש בזהר נקודה עילאה הוא לפי שישנה נקודה תתאה והוא בחי' חכמה תתאה, ולכן מדייק בזהר נקודה עילאה, שהיא בחי' חכמה עילאה. אמנם מה שמוסיף בזהר נקודה עילאה סתימא הוא להורות שהוי' כאן הוא לא בחי' חכמה עילאה סתם כ\"א בחי' חכמה סתימאה. ועל בחינה זו אומר בהפסוק ארוממך, שמרוממיםאותה למעלה יותר, והוא הרוממות דבחי' כתר שבכתר, וכנ\"ל שחכמה סתימאה הוא בחי' חכמה שבכתר והמקום שלשם מרוממים אותה הוא בחי' כתר שבכתר, ולהיות שבחי' כתר שבכתר אינו מקור לבחי' חכמה שבכתר ורק שממנה נמצאת בחי' חכמה שבכתר כנ\"ל, לכן אומר על זה הלשון ארוממך, לפי שכתר שבכתר הוא מרומם ונבדל מחכמה שבכתר.\n<b>וזהו</b> ועמדו רגליו ביום ההוא על הר הזיתים, דהנה זיתים שמהם עושים שמן, הרי הזיתים עצמם הם מרים, וכמרז\"ל<sup data-n=\"1829\">42</sup> אמרה יונה כו' יהיו מזונותי מרורין כזית כו', וגם בזה ב' פי'<sup data-n=\"1830\">43</sup> וארז\"ל שהזית משכח תלמודו – אבל השמן שבא מהזית משיב תלמודו<sup data-n=\"1831\">44</sup>, והענין בעבודה הוא<sup data-n=\"1832\">45</sup>, שזית הוא העבודה דאתכפיא ואתהפכא, שהם דוגמת כתישת הזית, הנה כתיב<sup data-n=\"1833\">46</sup> כתית למאור, שע\"י העבודה דכתית מגיעים לבחי' מאור, מקור האור, שממנו נמצא בחי' חכמה, שמן. והיינו שהזית שממנו עושים שמן רומז לבחי' הכתר (כתר שבכתר) שלמעלה מבחי' חכמה סתימאה, דזהו מה שזית הוא מר, כי הנה מתיקות שייך לאור ומרירות לחושך, וכמש\"נ<sup data-n=\"1834\">47</sup> ומתוק האור, ולהיות שכתר הוא בחי' חושך, בחי' ישת חושך סתרו<sup data-n=\"1835\">48</sup>, וכמאמר<sup data-n=\"1836\">49</sup> כתר עליון אע\"ג דאיהו אור צח אור מצוחצח אוכם הוא קמי עה\"ע, לכן הזית שמורה על בחי' הכתר הוא מר. והנה הר הזיתים הוא למעלה גם מבחי' זיתים. וכמו שנת\"ל בענין כתר שבכתר וחכמה שבכתר (זית ושמן) שבחי' כתר שבכתר הוא נבדל בערך מבחי' חכמה שבכתר, עד\"ז הוא גם בנוגע להערך דזיתים להר הזיתים, שבחי' הר הזיתים הוא נבדל בערך מבחי' זיתים, דזהו מה שצמיחת הזיתים מהר הזיתים הוא רק מבחי' (כח) הצומח שישנו בההר, אבל בחי' הדומם שבדומם שבו, שהוא עצמיות ההר, הוא נבדל מהזיתים. וכמו שידוע בענין הצמיחה, שזה בא לא מעצם העפר ורק מבחי' הצומח שבו, דלכן כשברך על פרי העץ בורא פרי האדמה יצא<sup data-n=\"1837\">50</sup>, דמארעא קא רבי, דיניקת ענפי העץ אינו מעצם האדמה ורק מכח הצמיחה שבו. שמזה מובן גודל הפלאת הענין דהר הזיתים, שהוא נבדל בערך גם מבחי' זיתים. וזהו מ\"ש ונבקע הר הזיתים, שלע\"ל יומשך בחי' הר הזיתים עצמו, היינו בחי' הדומם שבדומם שבו. דזהו\"ע ונבקע, דהנה ידוע ומבואר בענין האושפיזין דיעקב אומר אז יבקע כשחר אורך<sup data-n=\"1838\">51</sup>, דהגם שהאור שנמשך דרך הבקיעה הוא מעט מזעיר, מ\"מ הרי סיבת הבקיעה הוא מצד תגבורת האור, וכידוע המשל מחבית שמתמלאה על כל גדותי' עד שלא תוכל להחזיק את המשקה בתוכה, שאז היא מתבקעת בבקעים וסדקים והמשקה יוצאתדרך הבקעים, אשר אף שכמות המשקה שיוצאת דרך הבקעים היא מעט מזעיר, הרי בקיעה זו מורה על מילוי החבית כו', והיינו שבאור הבקיעה נראה כח בחי' העצם שלמעלה מבחי' הגילוי ושרשה משם, וכמבואר בסידור שער הסוכות<sup data-n=\"1839\">52</sup>, ויתירה מזה כאן. וזהו\"ע ונבקע הר הזיתים עצמו – לא ע\"י פרסא (דופני החבית) וכו' כ\"א שיומשך בחי' העצם דהר הזיתים, בחי' הדומם שבו, שלמעלה מבחי' סיבה לזיתים. וזהו<sup data-n=\"1840\">53</sup> מ\"ש ונבקע הר הזיתים גו' מזרחה וימה, דמזרח וים הוא קדם ואחור, והוא בחי' האורך שנמשך מלמעלה למטה דוגמת הקו דוא\"ו שנמשך מלמעלה למטה, הנה אופן ההמשכה בדרך כלל הוא שכל מה שהאור הולך ונמשך הוא מתמעט, דזהו דוקא כאשר תחילת ההמשכה הוא מבחי' השייך להשתלשלות, אמנם לע\"ל כשיהי' בקיעת הר הזיתים ויומשך מבחי' העצם שלמעלה מהשתלשלות, אז תהי' ההמשכה מזרחה וימה, למעלה ולמטה בשוה. וזהו ג\"כ מ\"ש לאח\"ז ומש חצי ההר צפונה וחציו נגבה, צפונה ונגבה הם קו השמאל וקו הימין, הנה לע\"ל כשיהי' ונבקע הר הזיתים אז ומש גו' צפונה התבטלות הקוין ממציאותם או התכללות ע\"ד לית שמאלא בהאי עתיקא וכו'<sup data-n=\"1841\">54</sup>. וזהו ג\"כ מה שמסיים ביום ההוא יהי' הוי' אחד ושמו אחד וארז\"ל&lt;26&gt; כמו שאני נכתב אני נקרא, דלהיות שיהי' אז המשכת העצם שהוא למעלה ולמטה בשוה, לכן יהי' למטה כמו שהוא למעלה, נקרא כמו שנכתב. וזהו ג\"כ השייכות דשני הפירושים שבועמדו רגליו ביום ההוא על הר הזיתים, כי מצד העילוי דבחי' על הר הזיתים הנה מצד זה יהי' אז המשפט בעמידה, שענין העמידה מורה על ההמשכה מראש לרגל בשוה<sup data-n=\"1842\">55</sup>, וכידוע<sup data-n=\"1843\">56</sup> בענין עמדת להם בעת צרתם<sup data-n=\"1844\">57</sup>, שגם כשמצד העבודה (דכחות פנימיים) ישראל הם במצב דצרתם, שמצד זה נעשה עת צרתם כפשוטו, הנה בכל צרתם לו צר<sup data-n=\"1845\">58</sup> ואז הנה עמדת להם בעת צרתם, שהעמידה היא מה שנמשך מהראש מיד להרגל. וזהו ג\"כ מה שלעתיד יהי' המשפט בעמידה, דמשפט הו\"ע הבירורים, הנה מצד בחי' ונבקע הר הזיתים שיומשך העצם, שאז יהי' ההמשכה קדמה וימה בשוה (כענין העמידה שנמשך מראש לרגל), הנה אז יהי' המשפט בגוים, שיתבררו גם האומות כו'.\n<b>והנה</b> כל הענינים נמשכים ע\"י עבודה, וכן הוא גם בענין ועמדו רגליו ביום ההוא על הר הזיתים שזה נמשך ע\"י העבודה דבחי' רגלים, כמאמר<sup data-n=\"1846\">59</sup> מטו רגלין ברגלין. והענין הוא<sup data-n=\"1847\">60</sup> דהנה בזמן שביהמ\"ק הי' קיים הי' אז גילוי אלקות, ועד\"ז הי'גם לאחרי החורבן, ותותר בימי רבי<sup data-n=\"1848\">61</sup>, ובזה\"ג נאמר סוכת דוד הנופלת<sup data-n=\"1849\">62</sup> מדרגא לדרגא, לכן בתחלה הי' עיקר העבודה והבירורים בבחי' חב\"ד שלכן התנאים ואמוראים הי' עיקר עסקם בלימוד התורה, משא\"כ בעבודת התפלה, ועד שהיו כאלו שהיו מתפללים רק פעם אחת בתלתין יומין וכו'<sup data-n=\"1850\">63</sup>. ובזמן שלאח\"ז, הנה אז עיקר העבודה הי' בחג\"ת, לית פולחנא כפולחנא דרחימותא<sup data-n=\"1851\">64</sup>, שהוא עבודה שבלב, עבודת התפלה<sup data-n=\"1852\">65</sup>. אמנם בהזמן דעקבות משיחא שנפלה בחי' סוכת דוד עד בחי' רגלים ועקביים שהיא בחי' עשי', הנה עכשיו עיקר העבודה הוא בבחי' נה\"י, ובבחי' המעשה, בקיום המצוות בפועל, ובפרט במעשה הצדקה שהיא כללות כל המצוות, כמבואר באגה\"ק<sup data-n=\"1853\">66</sup>. וזהו לימוד זכות גדול (אַ גוואַלדיגער לימוד זכות) על דור זה, שכל ישראל שבדור זה בכל המדינות מצטיינים ביותר בנתינת הצדקה, באופן שלא הי' כן בדורות הקודמים, שע\"י עבודה זו מקימים את סוכת דוד מנפילתה, כמבואר באגה\"ק שם. וזה שייך בפרט לימי הסוכות, וכדאיתא בזהר בענין האושפיזין ופי' בסידור שער הסוכות<sup data-n=\"1854\">67</sup> שצריך לפזר מעות לעניים בערב סוכות. וע\"י עבודת הצדקה במעשה, בחי' רגלים, הנה רגלי דנוקבא מעוררים רגלי דדכורא, ועי\"ז נמשך ועמדו רגליו ביום ההוא על הר הזיתים, דמטו רגלין ברגלין, ועי\"ז נמשך העצם שלמעלה מבחי' גילוי, וע\"ד המבואר בסידור שער הל\"ג בעומר<sup data-n=\"1855\">68</sup> שבבחי' הוד שבהוד דוקא נמשך העצם.\n<b>וזהו</b> הללו את הוי' כל גוים שבחוהו כל האומים כי גבר עלינו חסדו ואמת הוי' לעולם, דבחי' חסדו שלמעלה מהשתלשלות וכמו שגבר עלינו חסדו, וכן בחי' אמת הוי', יומשכו גם בעולם, שיהי' נקרא כמו שנכתב, ומצד זה יתבררו גם הגוים, וכנ\"ל שמצד הגילוי דועמדו רגליו גו' יהי' גם המשפט בגוים שהו\"ע הבירורים, והוא מה שע\"י הקרבת הע' פרים שמקריבים בחג הסוכות מכניעים את הע' שרים לקדושה שהם נכנעים לישראל, ואז נמשך אך טוב לישראל וגודל השמחה דזמן שמחתנו בחג הסוכות ומי שלא ראה שמחת בית השואבה לא ראה שמחה מימיו<sup data-n=\"1856\">69</sup>, ואח\"כ באים לשמיני עצרת, ישראל ומלכא בלחודוהי<sup data-n=\"1857\">70</sup>, דשמיני עצרת שייך ומרמז על הגילוי דלעתיד, וכמרז\"ל<sup data-n=\"1858\">71</sup> כנור של ימות המשיח של שמונה נימין, דבשמיני עצרת (ולעת\"ל) ההמשכה היא מבחי' שמן (בשמנונית) והנותן בעין יפה נותן<sup data-n=\"1859\">72</sup>. והנה עניניתשרי הם כלליים לכל השנה וע\"מ להמשיכם בכל השנה<sup data-n=\"1860\">73</sup>, וזמן שמחתנו הוא שהשמחה דסוכות ושמיני עצרת ממשיכים בכל השנה כולה, ועד לושמחת עולם על ראשם<sup data-n=\"1861\">74</sup> בביאת משיח צדקנו אשר ילחם מלחמת ה' ויצליח<sup data-n=\"1862\">75</sup> ושמת מעיר לגל&lt;39&gt;, שתתבטל מלכות דקליפה, מחורבנה של צור תיבנה ירושלים<sup data-n=\"1863\">76</sup> עיר הקודש ויבנה מקדש במקומו<sup data-n=\"1862\">75</sup> במהרה בימינו אמן.\n**********",[["1788","1","תהלים קיז."],["1789","2","קיח, ב."],["1790","3","נדפס במאמרי אדה\"ז תקס\"ט ע' רלח ואילך. ועם הגהות – באוה\"ת סוכות ע' א'תשנה ואילך."],["1791","4","וראה חדא\"ג שם."],["1792","5","סוכה נה, ב."],["1793","6","רבה ותנחומא ס\"פ פנחס."],["1794","7","ראה אוה\"ת שם ע' א'תשנו."],["1795","8","ח\"ג קג, ב ואילך."],["1796","9","הובא באוה\"ת שם."],["1797","10","עירובין יג, ב."],["1798","11","ראה לקו\"ש ח\"ג ע' 782. ובכ\"מ."],["1799","12","פסחים קיח, א."],["1800","13","ראה תו\"א ר\"פ בשלח. קונטרס ומעין מ\"ח פ\"א. ועוד."],["1801","14","הל' יסוה\"ת פ\"א ה\"ד."],["1802","15","ראה רמב\"ם <i>בסיום</i> ספרו: וישיגו דעת בוראם כפי כח האדם."],["1803","16","מקץ מא, טז. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370319\" data-slug=\"torah-or\" data-id=\"3901370319\">תו\"א יתרו עא, ד</a>."],["1804","17","ראה שער הכוונות ענין הפסח דרוש א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370486\" data-slug=\"torah-or\" data-id=\"3901370486\">תו\"א הוספות קט, ד</a>. סה\"מ תש\"ט ע' 189 (השני)."],["1805","18","להעיר מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370415\" data-slug=\"torah-or\" data-id=\"3901370415\">תו\"א יז, רע\"א</a>. ב\"ק צב, ב: כתוב בתורה כו' בנביאים כו' בברייתא."],["1806","19","זכרי' יד, ד."],["1807","20","הצ\"צ לנ\"ך במקומו. הוספה לס' החקירה."],["1808","21","שמו\"ר פי\"ז, ד."],["1809","22","תהלים כט, י."],["1810","23","זכרי' שם, ב ואילך."],["1811","24","דברים ב, ה."],["1812","25","עקב ח, ח."],["1813","26","פסחים נ, א."],["1814","27","עקב יא, יד."],["1815","28","ראה אמרי בינה שער הק\"ש פנ\"ג ואילך."],["1816","29","עיין ד\"ה למען דעת רס\"ט (סה\"מ תרס\"ט ע' מ ואילך)."],["1817","30","ב\"ק יז, א."],["1818","31","תענית ז, א."],["1819","32","ראה זח\"א ו, רע\"א. תקו\"ז ריש תיקון (יט, א). תיקון כח (עב, ב). ועוד. תניא אגה\"ק ס\"ה (קז, א). ועוד."],["1820","33","איוב כח, יב."],["1821","34","טבול יום פ\"ב מ\"ה."],["1822","35","בהבא לקמן – ראה ד\"ה למען דעת הנ\"ל (סה\"מ תרס\"ט ס\"ע מ ואילך)."],["1823","36","ספר יצירה פ\"א מ\"ז."],["1824","37","בהר מג, ג. בחוקותי נג, ב."],["1825","38","בד\"ה: זה היום, שיר המעלות, דרשו (סה\"מ תשל\"א ע' 305 ואילך; 311 ואילך; 318 ואילך)."],["1826","39","ישעי' רסכ\"ה."],["1827","40","ח\"ג קצג, ב."],["1828","41","ראה ביאוה\"ז להצ\"צ שם. המשך תער\"ב ח\"א פרק קפד ואילך."],["1829","42","עירובין יח, ב."],["1830","43","לקו\"ת ר\"פ בהעלותך."],["1831","44","הוריות יג, ב."],["1832","45","בהבא לקמן – ראה ד\"ה למען דעת הנ\"ל (סה\"מ תרס\"ט ע' מא)."],["1833","46","ר\"פ תצוה."],["1834","47","קהלת יא, ז."],["1835","48","תהלים יח, יב."],["1836","49","תקו\"ז ת\"ע (קלה, ב)."],["1837","50","ברכות מ, א."],["1838","51","ישעי' נח, ח. זח\"ג קד, א."],["1839","52","רנח, א-ב."],["1840","53","בהבא לקמן – ראה ד\"ה למען דעת הנ\"ל (סה\"מ תרס\"ט ע' מו)."],["1841","54","זח\"ג קכט, א. ועד\"ז שם רפט, א."],["1842","55","ראה הוספות לספר החקירה להצ\"צ ע' 272 ואילך."],["1843","56","ראה מאמרי אדמו\"ר האמצעי קונטרסים ע' שלח ואילך. המשך תער\"ב ח\"ג ע' א'רצא ואילך. סה\"מ תרפ\"ט ע' 33 ואילך. ד\"ה ואתה ברחמיך הרבים תשי\"ז (תורת מנחם – התוועדויות חי\"ח ע' 304 ואילך)."],["1844","57","נוסח הודאת \"ועל הנסים\" דחנוכה."],["1845","58","ישעי' סג, ט. תענית טז, א."],["1846","59","זח\"ב רנח, א."],["1847","60","סידור (עם דא\"ח) סד\"ה אני בצדק (כג, א)."],["1848","61","שבת קיג, סע\"ב."],["1849","62","עמוס ט, יא."],["1850","63","ר\"ה לה, א."],["1851","64","ראה זוהר ח\"ב נה, ב. ח\"ג רסז, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380482\" data-slug=\"likkutei-torah\" data-id=\"4001380482\">לקו\"ת שלח מב, ג</a>."],["1852","65","ראה תענית ב, סע\"א."],["1853","66","סי' ט'."],["1854","67","רנז, רע\"ג."],["1855","68","דש, א ואילך."],["1856","69","סוכה נא, א-ב."],["1857","70","ראה זח\"ג לב, א."],["1858","71","ערכין יג, ב."],["1859","72","ב\"ב נג, א. וש\"נ."],["1860","73","מאמרי אדמו\"ר הזקן תקס\"ט שם (ע' רלח). אוה\"ת סוכות שם (ע' א'תשנו). ועוד."],["1861","74","ישעי' לה, יו\"ד. שם נא, יא."],["1862","75","ראה רמב\"ם הל' מלכים פי\"א ה\"ד."],["1863","76","ראה פרש\"י תולדות כה, כג. מגילה ו, א."]]],[1500360028,"<h3>בס\"ד. יום שמחת תורה ה'תשכ\"ג<sup data-n=\"1864\">*</sup></h3>\n<b>תורה</b> צוה לנו משה מורשה קהלת יעקב<sup data-n=\"1865\">1</sup>, שהתורה היא ירושה<sup data-n=\"1866\">2</sup> לכאו\"א<sup data-n=\"1867\">3</sup> שמקהלת יעקב. וידועים הדיוקים בזה<sup data-n=\"1868\">4</sup>, הרי אמרו רז\"ל<sup data-n=\"1869\">5</sup> התקן עצמך ללמוד תורה שאינה ירושה לך, וכאן נאמר שהתורה היא ירושה. גם צריך להבין, דפירוש ירושה בפשטות הוא שיורש מאבותיו (היינו שמצד עצמו אינו שייך להדבר אלא שירש זה מאבותיו), והרי כל ישראל היו (נשמותיהם) במעמד הר סיני<sup data-n=\"1870\">6</sup> וקיבלו בעצמם את התורה. גם צריך להבין, דבפסוק שלאח\"ז<sup data-n=\"1871\">7</sup> נאמר ויהי בישורון מלך בהתאסף ראשי עם יחד שבטי ישראל, מהי השייכות דויהי בישורון מלך גו' למורשה קהלת יעקב. גם, דבפסוק זה נקראים ישראל בשם יעקב (מורשה קהלת יעקב), ובהפסוק שלאח\"ז בתחלתו נקראים בשם ישורון (ויהי בישורון מלך) ובסיום הפסוק נקראים בשם ישראל (יחד שבטי ישראל).\nב) <b>ונקודת</b> הביאור בזה (כמובן מהדרושים<sup data-n=\"1872\">8</sup>), דבתורה שני ענינים. התורה כמו שהיא מצד עצמה, שהיא חכמתו ורצונו של הקב\"ה, וכמו שהתורה ירדה למטה, ומבררת ומזככת את העולם, מתחיל מהבירור והזיכוך שבאדם הלומד, שהשכל דנפש הבהמית מתברר ומזדכך ונכלל בקדושה<sup data-n=\"1873\">9</sup>. וזהו<sup data-n=\"1874\">10</sup> שאמרו רז\"ל<sup data-n=\"1875\">11</sup> לעולם יעסוק אדם בתורה ומצוות שלא לשמה שמתוך שלא לשמה בא לשמה, דבתחילת העבודה, עסק התורה דהאדם הוא בכדי לברר ולזכך את נפשו, כמאמר רז\"ל<sup data-n=\"1876\">12</sup> מעיקרא כי עביד איניש אדעתא דנפשי' קא עביד, שעסק התורה שלו הוא בכדי לזכך את נפשו, ועי\"ז בא אח\"כ לעסק התורה לשמה, לשם התורה עצמה (שלמעלה מענין הבירורים).<b>וזהו</b> שהתורה נקראת ירושה ואעפ\"כ אמרו התקן עצמך ללמוד תורה שאינה ירושה, דזה שהתורה נקראת ירושה הוא מצד הבירורים שע\"י התורה. דהניצוצות שבדברים הגשמיים, וכן הניצוצות שבהשכל דנפש הבהמית, שרשם הוא בתוהו, והשורש דנשמות ישראל הוא בתיקון. דזהו שעשו נקרא גדול ויעקב נקרא קטן<sup data-n=\"1877\">13</sup>, כי שורש עשו הוא בתוהו, שהאורות דתוהו הם אורות מרובים (גדול), ושורש יעקב הוא בתיקון, שהאורות דתיקון הם אורות מועטים וכן מוגבלים בכלים (קטן). וכיון שיעקב ועשו הם אחים, כמ\"ש<sup data-n=\"1878\">14</sup> הלא אח עשו ליעקב, והאחים יורשים זה את זה, לכן, על ידי שנשמות ישראל מבררים את הניצוצות, הם יורשים האורות דתוהו. ומ\"ש התקן עצמך ללמוד תורה שאינה ירושה לך הוא בנוגע להתורה כמו שהיא למעלה מענין הבירורים, דהמשכת בחינה זו דתורה היא על ידי לימוד התורה לשמה. וזהו התקן עצמך ללמוד תורה, שצריך לייגע עצמו שיהי' לימודו לשמה בלי שום פני' כלל (גם לא הפני' דלזכך את נפשו), ועל ידי לימוד התורה לשמה הוא ממשיך התורה כמו שהיא מצד עצמה. שדרגא זו דתורה היא למעלה גם מהאורות דתוהו (שישראל יורשים ע\"י עבודת הבירורים), <i>שאינה</i> ירושה לך.\nג) <b>וזהו</b> יערוף כמטר לקחי תזל כטל אמרתי<sup data-n=\"1879\">15</sup>, דמטר בא מהעננים שנעשים מלחות הארץ, ואד יעלה מן הארץ והשקה את פני האדמה<sup data-n=\"1880\">16</sup>. וטל בא מלמעלה. דכמו\"כ הוא ברוחניות, שמטר הוא ענין<sup data-n=\"1881\">17</sup> שבא ע\"י בירור וזיכוך והעלאת המטה, כמאמר רז\"ל<sup data-n=\"1882\">18</sup> על הפסוק יערוף כמטר לקחי גו', שברו הבריות את ערפן מיד מטר יורד, וטל הוא גילוי מלמעלה. והטעם שהתורה נמשלה לטל ולמטר הוא, כי בתורה שני הענינים. הענין דירידת התורה למטה בכדי לברר את העולם, דהמשכת ענין זה שבתורה הוא על ידי לימוד התורה אדעתא דנפשי' – יערוף כמטר לקחי, והתורה כמו שהיא מצד עצמה (כמו שהיא באצילות, למעלה מירידתה בבי\"ע), דהמשכת ענין זה שבתורה הוא על ידי עסק התורה לשמה – תזל כטל אמרתי. ואולי י\"ל דעל זה אמרו<sup data-n=\"1883\">19</sup> כל הקורא ושונה הקב\"ה קורא ושונה כנגדו, שעל ידי עסק התורה לשמה הוא המשכת וגילוי התורה כמו שהיא מצד למעלה, <i>הקב\"ה</i> קורא ושונה, טל דתורה<sup data-n=\"1884\">20</sup>.\n<b>ויש</b> לומר, דשני ענינים אלה (מטר דתורה וטל דתורה) הם גליא דתורה ופנימיות התורה<sup data-n=\"1885\">21</sup>. שבנגלה דתורה שנתלבשה בדברים גשמיים, האור האלקי הוא בהעלם,ובכדי שהאור יהי' בגילוי באדם הלומד את התורה הוא ע\"י שיזכך את עצמו, דזהו שזכה נעשית לו סם חיים<sup data-n=\"1886\">22</sup>, דע\"י שזכה מלשון זיכוך אז דוקא נעשית לו סם חיים. ובפנימיות התורה האור האלוקי הוא בגילוי. ולהוסיף, שגם לאחרי שהאדם מזכך את עצמו, שאז גם בנגלה דתורה האור הוא בגילוי, אינו כהגילוי שבפנימיות התורה. דכיון שהאור שבנגלה דתורה מלובש בדברים גשמיים המעלימים את האור, לכן גם לאחרי הסרת ההעלם אין האור בגילוי כ\"כ כהאור שבפנימיות התורה<sup data-n=\"1887\">23</sup>. וזהו שנגלה דתורה הוא מטר דתורה, דשני ענינים בזה. שבלימוד נגלה דתורה צריכה להיות העבודה דזכה, הלימוד אדעתא דנפשי' לזכך את נפשו – ע\"ד הענין דשברו הבריות את ערפן. וגם אז, האור האלוקי שמאיר להאדם הוא כמו שהוא מלובש בעולם – מטר. והענין דטל תורה הוא בפנימיות התורה.\nד) <b>והנה</b> נוסף לשני ענינים הנ\"ל שבתורה (ירושה דתורה, והתקן עצמך ללמוד תורה), נקראת התורה בשם מתנה<sup data-n=\"1888\">24</sup>. כהנוסח דברכת התורה <i>ונתן</i> לנו את תורתו וחותמין <i>נותן</i> התורה, וחג השבועות נקרא<sup data-n=\"1889\">25</sup> זמן <i>מתן</i> תורתנו. דענין המתנה שבתורה הוא למעלה גם מהענין דהתקן עצמך ללמוד תורה. והענין הוא<sup data-n=\"1890\">26</sup>, דהחילוק בין טל ומטר הוא, דירידת מטר תלוי' בעבודת האדם (כמ\"ש<sup data-n=\"1891\">27</sup> והי' אם שמוע גו' (ואז<sup data-n=\"1892\">28</sup>) ונתתי מטר ארצכם גו'), וטל אינו תלוי בעבודת האדם (כמארז\"ל<sup data-n=\"1893\">29</sup> טל לא מיעצר), דכמו\"כ הוא ברוחניות, דמטר היא ההמשכה שע\"י אתעדל\"ת וטל היא ההמשכה מלמעלה מצד עצמה. ומזה מובן, דזה שנת\"ל דבחינת טל תורה היא המשכת התורה כמו שהיא למעלה ע\"י עסק התורה לשמה (כל הקורא ושונה הקב\"ה קורא ושונה כנגדו), הוא בכללות, אבל בפרטיות, גם המשכת התורה כמו שהיא למעלה, <i>הקב\"ה</i> קורא ושונה, כיון שההמשכה היא ע\"י <i>שהאדם</i> קורא ושונה, נכללת בבחינת מטר דתורה, ובחינת טל תורה היא דרגא נעלית יותר בתורה, שאינה נמשכת ע\"י עסק התורה דהאדם (גם לא ע\"י עסק התורה לשמה), והמשכתה היא מצד עצמה.\n<b>וזהו</b><sup data-n=\"1890\">26</sup> שאמרו רז\"ל<sup data-n=\"1894\">30</sup> ג' שעות ראשונות הקב\"ה יושב ועוסק בתורה, וידוע הדיוק בזה, הרי כל הקורא ושונה הקב\"ה קורא ושונה כנגדו, וכיון שישראל עוסקים בתורה במשך כל היום (זה לומד בשעה זו וזה לומד בשעה זו), הרי גם הקב\"ה עוסק בתורה במשך כל היום, ואעפ\"כ אמרו שבג' שעות ראשונות הקב\"ה יושב ועוסק בתורה. ונקודת הביאור בזה, דזה שכל הקורא ושונה הקב\"ה קורא ושונהכנגדו היא המשכה מלמעלה שע\"י אתערותא דלתתא (עסק התורה דהאדם), ולכן, ההמשכה היא לפי ערך האתערותא דלתתא. דזהו שאמרו כל הקורא ושונה הקב\"ה קורא ושונה <i>כנגדו</i>, דזה שהקב\"ה קורא ושונה הוא כנגדו, לפי ערך הלימוד דהאדם. וזה שבג' שעות ראשונות הקב\"ה יושב ועוסק בתורה הוא המשכה מלמעלה מצד עצמה, ממקום שאין אתעדל\"ת מגעת לשם. וענין זה הוא בחינת טל דתורה, כי שורש הטל הוא בג' ראשונות דעתיק. וזוהי השייכות דהקב\"ה יושב ועוסק בתורה (טל תורה) לג' שעות ראשונות, כי ג' [שעות] ראשונות הם ג' ראשונות דעתיק.\n<b>ויש</b> לבאר זה ע\"פ הידוע<sup data-n=\"1895\">31</sup> שגם בפנימיות התורה יש חיצוניות ופנימיות. דזה שפנימיות התורה מדברת בהענינים דהשתלשלות הוא הגליא שבה. [והוא ע\"ד נגלה דתורה שמדברת בעניני העולם. אלא שנגלה דתורה מדברת בענינים גשמיים, ופנימיות התורה בענינים רוחניים]. ודרגא זו שבפנימיות התורה היא בבחינת השגה<sup data-n=\"1896\">32</sup>. ועיקר הענין דפנימיות התורה הוא זה שהתורה היא התענוג דלמעלה, תענוג שלמעלה מהשגה. ויש לומר, שההמשכה דפנימיות התורה ע\"י עסק התורה לשמה, שעל זה אמרו כל הקורא ושונה הקב\"ה קורא ושונה כנגדו [הענין דהתקן עצמך ללמוד תורה], הוא הגליא שבפנימיות התורה, שמדברת בהענינים דהשתלשלות וכיו\"ב. וההמשכה דפנימיות התורה מצד עצמה, שעל זה אמרו ג' שעות ראשונות הקב\"ה יושב ועוסק בתורה [ענין המתנה דתורה<sup data-n=\"1897\">33</sup>] הוא בחי' תענוג דתורה שלמעלה מהשגה.\nה) <b>וזהו</b> תורה צוה גו' מורשה קהלת <i>יעקב</i> ויהי <i>בישורון</i> מלך גו' יחד שבטי <i>ישראל</i>, דזה שהתורה היא ירושה לכל אחד מישראל הוא מצד בחינת יעקב שבהם (<i>מורשה</i> קהלת <i>יעקב</i>), והענין דהתקן עצמך ללמוד תורה שאינה ירושה לך הוא מצד בחינת ישראל, והמתנה דתורה היא מצד בחינת ישורון.\n<b>והענין</b> הוא, דיעקב הוא בחינת עבד כמ\"ש<sup data-n=\"1898\">34</sup> שמע אלי יעקב עבדי, וישראל הוא בחינת בן כמ\"ש<sup data-n=\"1899\">35</sup> בני בכורי ישראל<sup data-n=\"1900\">36</sup>. והעבודה דיעקב היא<sup data-n=\"1901\">37</sup> שהוא עובד אלקים, לתקן ההסתר הנמשך משם אלקים. וישראל הוא על שם כי שרית עם אלקים<sup data-n=\"1902\">38</sup>, שמושל ושולט על שם אלקים. וזהו שאיתא בזהר<sup data-n=\"1903\">39</sup> שישראל ויעקב הם נגד ב'השמות הוי' ואלקים, דלגבי בחינת יעקב י' עקב<sup data-n=\"1904\">40</sup> ישנו ההסתר דשם אלקים ועבודתו היא לתקן ההסתר. וגם לאחרי שמתקן ההסתר דשם אלקים, שעי\"ז נמשך הגילוי דהוי', הוא הגילוי דהוי' כמו שהוא ע\"י שם אלקים. וישראל שהוא על שם כי שרית עם אלקים, שלגבי' אין מלכתחילה ההעלם וההסתר דשם אלקים, הגילוי דהוי' שנמשך ע\"י ישראל הוא הגילוי דהוי' עצמו. ומבואר בלקו\"ת<sup data-n=\"1905\">41</sup> שהעבודה בששת ימי החול היא (בדרך כלל) העבודה דיעקב, עבודת הבירורים, לתקן ההסתר דשם אלקים. והעבודה דשבת היא בבחינת ישראל. כי בשבת כתיב<sup data-n=\"1906\">42</sup> ויכל אלקים, שכלתה מדת הצמצום וההסתר דשם אלקים ונמשך הגילוי דהוי', ולכן אין צריך אז לעבודת הבירורים, והעבודה דשבת היא להתענג על הוי', שלמעלה מעבודת הבירורים.\n<b>ובחינת</b> ישורון היא למעלה גם מבחינת ישראל. דישורון הוא מלשון שיר, דבר עגול כטבעת שאין לו ראש וסוף<sup data-n=\"1907\">43</sup>. ומבואר בלקו\"ת<sup data-n=\"1908\">44</sup> דזה שישראל נק' בשם ישורון הוא מצד שורש הנשמות כמו שעלו במחשבה. ויש לומר, דהחילוק שבין ישורון לישראל, אף שגם הענין דישראל על שם כי שרית עם אלקים הוא מצד הגילוי דשורש הנשמה שלמעלה מהתלבשות בגוף [וכמבואר בכ\"מ<sup data-n=\"1909\">45</sup> דיעקב הוא הנשמה שמלובשת בגוף וישראל הוא שורש הנשמה שלמעלה מהתלבשות בגוף], דישראל הוא בחינת בן (כנ\"ל), דלשון וענין בן שייך דוקא לאחרי שהבן <i>נמשך</i> ממוח האב, וישורון הוא עצם הנשמה כמו שהיא מושרשת בעצמותו ית', בדוגמת הבן כמו שהוא במוח האב עצמו (טרם שנמשך). וזהו שישורון הוא מלשון שיר שאין בו ראש וסוף, כי בהדרגא דהנשמות כמו שנמשכו כבר ממוח האב (גם כמו שהם למעלה) ישנם חילוקי דרגות, והענין דשיר שאין בו ראש וסוף הוא בעצם הנשמות כמו שהם מושרשים באוא\"ס. וזהו מ\"ש ויהי בישורון מלך ואיתא בלקו\"ת<sup data-n=\"1908\">44</sup> שזה קאי על ראש השנה, שתמליכוני עליכם, כי הענין דתמליכוני עליכם הוא ע\"י גילוי עצם הנשמה כמו שהיא מושרשת בעצמות אוא\"ס.\n<b>וזוהי</b> השייכות דג' ענינים אלה שבישראל (יעקב, ישראל וישורון) לג' הענינים שבתורה, דענין הירושה שבתורה שהוא מצד הבירורים [שע\"י הבירורים דתורה יורשים את האורות דתהו, כנ\"ל סעיף ב], הוא מצד בחינת יעקב, דעבודת הבירורים היא בבחינת יעקב. והענין דהתקן עצמך ללמוד תורה, שע\"י עסק התורה לשמה נמשך הגילוי דתורה כמו שהיא למעלה (פנימיות התורה), הוא מצד בחינת ישראל<sup data-n=\"1910\">46</sup>, דעסק התורה דבחינת ישראל הוא (לא בכדי לברר בירורים, אלא) בכדילהמשיך גילוי אלקות. וענין המתנה דתורה שהוא המשכת התענוג דתורה (שלמעלה מהשגה) שלמעלה מהתחלקות הוא מצד בחינת ישורון.\nו) <b>וצריך</b> להבין, דלפי ביאור הנ\"ל, הטעם שהתורה נקראת בשם ירושה הוא לפי שהתורה <i>מביאה</i> לירושה (שע\"י הבירורים שע\"י התורה יורשים אורות דתהו), והפירוש דתורה גו' מורשה (בפשטות, דאין מקרא יוצא מידי פשוטו<sup data-n=\"1911\">47</sup>) הוא, שהתורה עצמה היא ירושה<sup data-n=\"1912\">48</sup>.\n<b>ויש</b> לומר, דענין הירושה דתורה (להפירוש שהתורה עצמה היא ירושה) הוא למעלה יותר גם מענין המתנה דתורה. דזה שמובא לעיל מהדרושים דירושה היא למטה ממתנה, הוא<sup data-n=\"1913\">49</sup> לפי שירושה היא מצד מציאותו של <i>היורש</i> (שהוא קרובו של המוריש) ואינה תלוי' ברצון המוריש, ומתנה היא מצד רצונו של <i>הנותן</i>. דענין זה הוא בירושה שהיא<sup data-n=\"1914\">50</sup> (רק) מצד קורבה. אבל בירושה שענינה הוא<sup data-n=\"1914\">50</sup> שהיורש עומד במקום המוריש (<i>ובמילא</i> יורש את נכסיו), אין שייך לומר שהיא באה מצד מציאותו של היורש, כיון שהיורש אינו מציאות אחר מהמוריש אלא עומד במקום המוריש. ואדרבה, ירושה זו היא למעלה ממתנה. דמתנה היא מצד <i>רצון</i> הנותן, ובירושה (באופן זה) היורש עומד במקום המוריש <i>עצמו</i> (שלמעלה מהרצון שלו). ועפ\"ז צריך לומר, דהטעם על זה שבענין הירושה דתורה (שהיא למעלה גם ממתנה דתורה) נאמר מורשה קהלת <i>יעקב</i> הוא, כי ישראל וישורון הם שם המעלה, ולכן שייכים לענין הגילויים, וענין הירושה שהיורש עומד במקום המוריש עצמו מתגלה בהשם יעקב, כאשר הוא שם העצם<sup data-n=\"1915\">51</sup>, שבו כל ישראל הם בשוה.\n<b>וצריך</b> להבין, דהענין דעצם הנשמה שמצד זה כל ישראל הם בשוה, מודגש יותר (לכאורה) בהשם ישורון, דישורון הוא מלשון שיר שאין בו ראש וסוף, ואעפ\"כ השם ישורון שייך לענין מתנה (דתורה) ששייכת <i>לרצון</i> הנותן, וגבי ירושה ששייכת להמוריש עצמו נאמר מורשה קהלת יעקב. ויובן זה בהקדים מ\"ש<sup data-n=\"1916\">52</sup> יבחר לנו את נחלתינו את גאון יעקב גו', שאומר כאן שני ענינים. יבחר לנו, ענין הבחירה, ואת נחלתינו, ענין הירושה. ויש לומר, דענין הבחירה שהקב\"ה בחר בישראל הוא שבחר <i>לרצות</i> בהם. וענין הירושה שהיורש עומד במקום המוריש, הוא, שישראל מושרשים בהעצמות עצמו. והגם דענין הבחירה הוא מצד העצמות שאינו מוכרחבשום דבר ויכול לרצות ולא לרצות<sup data-n=\"1917\">53</sup>, מ\"מ, ענין הבחירה הוא (לא בנוגע לעצמות עצמו, אלא) בנוגע להרצון שלו, דזה שבחר בישראל הוא שבחר <i>לרצות</i> בהם [ועוד ענין בזה, שגם הבחירה עצמה (שהיא הסיבה להרצון) היא הפלאת העצמות (שאינו מוכרח בשום דבר ויכול לרצות ולא לרצות), ולא העצמות עצמו<sup data-n=\"1918\">54</sup>].\n<b>ועפ\"ז</b> יש לבאר שבענין מתנה נאמר השם ישורון ובענין ירושה השם יעקב, דמתנה היא שהיא מצד רצון הנותן (כנ\"ל), באה מצד הבחירה (שבחר לרצות). כמ\"ש בברכת התורה אשר בחר בנו מכל העמים (ולכן) ונתן לנו את תורתו. וכיון שענין הבחירה הוא הפלאת העצמות שאינו מוכרח בשום דבר, לכן, הכלי לזה הוא הענין דישורון מלשון שיר, עיגול שאין בו ראש וסוף, העילוי וההפלאה דעצם הנשמה שהיא למעלה מהתחלקות דראש וסוף. וענין הירושה, שישראל מושרשים בהעצמות עצמו, מתגלה בהשם יעקב, שם העצם דישראל עצמם.\nז) <b>ויש</b> לומר, דזה שבפסוק יבחר לנו את נחלתינו נאמר את גאון <i>יעקב</i>, הוא מצד הענין דנחלתינו, דענין הירושה שייך ליעקב. והבקשה <i>יבחר</i> לנו את נחלתינו, היא, שהענין דנחלתינו, עצם הנשמה שמושרשת בהעצמות עצמו, יומשך בגילוי<sup data-n=\"1919\">55</sup>. וכמו שבראש השנה עיקר ההדגשה הוא נחלתינו את גאון יעקב אלא שמבקשים שענין זה יומשך בגילוי, עד\"ז הוא בשמחת תורה, שעיקר ההדגשה היא <i>מורשה</i> קהלת <i>יעקב</i>. ואומר <i>קהלת</i> יעקב, שמצד הענין דיעקב, כל ישראל הם מציאות אחת (קהל), ע\"ד שבראש השנה אתם נצבים גו' כולכם, לאחדים כאחד<sup data-n=\"1920\">56</sup>. וזהו שמצות היום (דשמח\"ת) הוא בריקודים, דריקוד הוא ברגליים, וברגליים עצמם – בהעקב שבהם (יעקב מלשון עקב), שכל ישראל שוים בזה.\n<b>ולהוסיף</b><b>,</b> דזה שכל ישראל מתאחדים להיות מציאות אחת, קהלת יעקב, הוא לא מפני שנרגש בהם עילוי שלמעלה מהתחלקות [ע\"ד ההתאחדות דישורון מלשון שיר, שהוא ע\"י גילוי המקיף שלמעלה מהתחלקות], שהרי יעקב הוא מלשון עקב, ובעקב אין נרגש עילוי, אלא אחדות עצמית. ועד\"ז הוא בנוגע לההתאחדות דישראל בענין הריקוד בעקביים. וע\"י הענין דקהלת יעקב, מתגלה הענין דמורשה, ירושה דתורה, שישראל אורייתא וקוב\"ה כולא חד. דבמתנה דתורה, יש ג' ענינים. הנותן המקבל והמתנה (תורה), משא\"כ בענין הירושה דתורה, ישראל ואורייתא וקוב\"ה כולא חד.\n<b>והמשכת</b> ענין זה (מורשה, ירושה דתורה) בשמחת תורה, היא בשמחה גדולה. ומשמח\"ת נמשך זה על כל השנה כולה, שתהי' שנה שמיחה בלימודהתורה בלי שום מניעות ועיכובים, שמפני זה נתאוו כל ישראל וכו' לימות המשיח כי אז לא יהי' שום מונע ומעכב מלעסוק בתורה ובמצוות כדרוש<sup data-n=\"1921\">57</sup>, ועד שיהי' ומלאה הארץ דעה את הוי' כמים לים מכסים<sup data-n=\"1922\">58</sup>, בביאת משיח צדקנו בקרוב ממש.\n**********",[["1864","*","יצא לאור ב<b>קונטרס שמע\"צ ושמח\"ת – תנש\"א</b>, \"לקראת שמע\"צ ושמח\"ת . . <i>ערחה\"ס</i>,<i> שנת ה'תנש\"א</i>\".\nמאמר זה הוא המשך למאמרים שלפניו ד\"ה יבחר לנו גו' דראש השנה, ד\"ה וכל אדם גו' דשבת תשובה וד\"ה בסוכות תשבו דיום ב' דחג הסוכות שנה זו (תשכ\"ג) – לעיל ע' א ואילך; ע' עד ואילך; ע' קעח ואילך."],["1865","1","ברכה לג, ד."],["1866","2","סנהדרין נט, א. וראה גם שם צא, סע\"ב."],["1867","3","ולא רק להכלל (ע\"ד גזל השבט)."],["1868","4","ד\"ה תורה צוה באוה\"ת ברכה (ס\"ע א'תתמח. שם ע' א'תתנה). ד\"ה זה דשנת תרנ\"ד (סה\"מ תרנ\"ד ע' כו). ה'תש\"ב (סה\"מ ה'תש\"ב ע' 39)."],["1869","5","אבות פ\"ב מי\"ב."],["1870","6","פדר\"א פמ\"א. שמו\"ר פכ\"ח, ו. תנחומא יתרו יא. זח\"א צא, א. ובכ\"מ."],["1871","7","ברכה לג, ה."],["1872","8","דלעיל הערה 4. וראה גם המשך וככה תרל\"ז פס\"ו ואילך. סה\"מ תר\"ל ע' פז ואילך. סה\"מ קונטרסים ח\"ב שסא, א ואילך."],["1873","9","וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מט, א</a>), דלכאורה הפי' דבירור השכל דנה\"ב והתכללותו בקדושה הוא גם בבינונים (אף שהמדות דנה\"ב אין ביכלתם להפוך לקדושה)."],["1874","10","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381026\" data-slug=\"likkutei-torah\" data-id=\"4001381026\">לקו\"ת האזינו עה, סע\"ד</a> ואילך."],["1875","11","פסחים נ, ב. וש\"נ."],["1876","12","שם סח, ב."],["1877","13","תולדות כז, א. שם, טו. שם, מב."],["1878","14","מלאכי א, ב."],["1879","15","האזינו לב, ב."],["1880","16","בראשית ב, ו."],["1881","17","ברוב המקומות איתא, <i>שירידת</i> המטר הוא ע\"י זיכוך המטה. ובהמשך וככה תרל\"ז הנ\"ל, שזהו <i>ענין</i> המטר – ראה ד\"ה שיר המעלות לדוד הנה מה טוב גו' דל\"ג בעומר ה'תשכ\"ב ס\"ו, ובהערות שם (לקמן ח\"ג ס\"ע רעג ואילך)."],["1882","18","ב\"ר פי\"ג, ד."],["1883","19","ראה תדא\"ר פי\"ח. יל\"ש איכה רמז תתרלד."],["1884","20","כ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381027\" data-slug=\"likkutei-torah\" data-id=\"4001381027\">לקו\"ת שם (עו, רע\"א</a>). אבל ברוב הדרושים שבהערה 8, דהקב\"ה קורא ושונה כנגדו הוא מטר דתורה. וראה לקמן ס\"ד."],["1885","21","ראה גם המשך תרס\"ו ע' שז, דענין הירושה דתורה (שהוא מצד הבירורים דתורה) הוא בגליא דתורה, וטל תורה הוא פנימיות התורה. [אלא, שבהמשך תרס\"ו שם, שטל תורה (פנימיות התורה) הו\"ע מתנה דתורה]."],["1886","22","יומא עב, ב."],["1887","23","וע\"ד המובא לקמן ס\"ה שהגילוי דהוי' ע\"י תיקון ההסתר דאלקים אינו כהגילוי דהוי' עצמו."],["1888","24","ראה גם ברכות ה, סע\"א \"שלש מתנות כו' תורה כו'\". וראה גם ב\"ר פ\"ו, ה \"ג' דברים מתנה לעולם התורה כו'\"."],["1889","25","בנוסח התפלה והקידוש דיו\"ט."],["1890","26","בהבא לקמן ראה בארוכה דרושים שבהערה 8. וראה גם ד\"ה על שלשה דברים העולם עומד כו' ה'תשי\"ד סעיף ה (לקמן ח\"ג ע' קפב ואילך)."],["1891","27","עקב יא, יג-יד."],["1892","28","וכמו שממשיך בכתוב (שם, טו-טז) וסרתם ועבדתם גו' (ואז) ולא יהי' מטר."],["1893","29","תענית ג, א."],["1894","30","ע\"ז ג, ב."],["1895","31","המשך תער\"ב ח\"א פרק קפא (ע' שע)."],["1896","32","וכמו השגת הנשמות בג\"ע בעסק התורה שלהם, שהוא בבחי' השגה ממש. וכ\"ה בתורה דאצילות שמדברת בענינים דאלקות, שהיא \"בבחי' השגה ממש באצילות\" (המשך תער\"ב שם)."],["1897","33","להעיר גם מהמשך תער\"ב ח\"א פרק קעד (ריש ע' שנד), שמתנה דתורה הו\"ע פנימיות התורה בחי' שעשועים העצמיים."],["1898","34","כ\"ה בלקו\"ת שבהערה 36. ובכ\"מ. ובישעי' מו, א: ועתה שמע יעקב עבדי. ובהמשך תרס\"ו שבהערה הנ\"ל: שמע יעקב עבדי."],["1899","35","שמות ד, כב."],["1900","36","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, רע\"ג</a>. המשך תרס\"ו ע' רכה."],["1901","37","בהבא לקמן ראה המשך תרס\"ו שם, ושם ס\"ע רכו ואילך."],["1902","38","וישלח לב, כט."],["1903","39","ח\"א קעד, א."],["1904","40","ע\"ח שער ג (שער סדר אצי' למהרח\"ו) פ\"ב. פרדס שער כג (שער ערכי הכינויים) בערכו."],["1905","41","בלק עב, א-ב."],["1906","42","בראשית ב, ב."],["1907","43","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381135\" data-slug=\"likkutei-torah\" data-id=\"4001381135\">לקו\"ת שה\"ש א, ג</a>. וכ\"מ ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380899\" data-slug=\"likkutei-torah\" data-id=\"4001380899\">לקו\"ת נצבים מה, א</a>. – ראה גם אוה\"ת ברכה ס\"ע א'תתסא ואילך. שם ע' א'תתסו. סה\"מ תרנ\"ד ס\"ע לה ואילך. אלא ששם מדבר (בעיקר) בענין הדרגא דתורה שהיא כמו עיגול (ולא בהדרגא <i>דישראל</i> שנק' בשם ישורון)."],["1908","44","נצבים שם."],["1909","45","וראה גם המשך תרס\"ו שבהערה 21."],["1910","46","להעיר מהידוע שיום השבת שייך לפנימיות התורה (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011053\" data-slug=\"likkutei-sichot\" data-id=\"1300011053\">לקו\"ש ח\"א ע' 53</a>. <i>וש\"נ</i>) – ובשבת הוא בחינת ישראל, כנ\"ל בפנים."],["1911","47","שבת סג, א."],["1912","48","וכן מוכח גם ממה שלמדו רז\"ל מפסוק זה שעכו\"ם שלמד תורה חייב מיתה (סנהדרין נט, א) ושהמונע הלכה מפי תלמיד כאילו גוזלו מנחלת אבותיו (שם צא, סע\"ב)."],["1913","49","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131115\" data-slug=\"likkutei-sichot\" data-id=\"1300131115\">לקו\"ש חי\"ג ע' 115</a>."],["1914","50","ראה בכ\"מ בספרי הרגצובי (שו\"ת צפע\"נ דווינסק ח\"א סקי\"ח. ווארשא ח\"ב סקי\"ח. צפע\"נ מילואים יג, א) דבירושה שני ענינים: ירושה שמצד קורבה – דירושה זו היא גם בב\"נ; ירושה שהיורש עומד במקום המוריש – דירושה זו היא רק בישראל.\nואולי יש לומר, דהמבואר בהדרושים שירושה היא למטה ממתנה הוא – כי שם מדובר בענין הירושה שיעקב יורש את עשו (כנ\"ל סעיף ב), וירושה זו היא מצד קורבה."],["1915","51","ולכאורה צ\"ע המקור על שיעקב שם העצם."],["1916","52","תהלים מז, ה."],["1917","53","המשך ר\"ה תש\"ג ע' 24."],["1918","54","ראה <i>עד\"ז</i> בהמאמר ד\"ה יבחר לנו גו' שנה זו (תשכ\"ג) ס\"ה (לעיל ע' ה). ובהמאמר ד\"ה וכל אדם לא יהי' גו' שנה זו (תשכ\"ג) ס\"ז (לעיל ע' עט)."],["1919","55","<i>וע\"ד</i> הענין דתמליכוני, שמצד עצם הנשמה, שהגילוי שלו הוא ע\"י התשובה והמצוה דתק\"ש (ראה ד\"ה יבחר לנו (שבהערה הקודמת) ס\"ט (לעיל ע' ח))."],["1920","56","לקו\"ת ר\"פ נצבים."],["1921","57","רמב\"ם הל' תשובה פ\"ט ה\"ב."],["1922","58","ישעי' יא, ט."]]],[1500360029,"<h3>בס\"ד. יום שמחת תורה ה'תשל\"ז<sup data-n=\"1923\">*</sup></h3>\n<b>אתה</b> הראת לדעת כי הוי' הוא האלקים אין עוד מלבדו<sup data-n=\"1924\">1</sup>, הנה פסוק זה הוא פסוק הראשון של י\"ז הפסוקים<sup data-n=\"1925\">2</sup> שאומרים קודם ההקפות. ויש לומר, דפסוק זה הוא גם הראש של כל י\"ז הפסוקים שכולל אותם, בדוגמת הראש שכולל את כל אברי הגוף. וצריך להבין השייכות דאתה הראת גו' להקפות. וביותר צריך ביאור ע\"פ מ\"ש כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1926\">3</sup> דענין אמירת הפסוקים קודם הקפות הוא שמביאים טעמים<sup data-n=\"1927\">4</sup> על השמחה דשמע\"צ ושמח\"ת [וע\"ד פסוקי מלכיות זכרונות ושופרות<sup data-n=\"1928\">5</sup>], דלכאורה, מהי השייכות דאתה הראת לדעת גו' להשמחה דשמע\"צ ושמח\"ת. ובפרט שאתה הראת לדעת הי' בשעת מ\"ת, שהוא בחג השבועות.\nב) <b>ויובן</b> זה בהקדים המבואר במק\"א<sup data-n=\"1929\">6</sup> בענין אמירת פסוקי מלכיות זכרונות ושופרות, דזה שצריך להביא ראי' מן התורה על ענינים אלו<sup data-n=\"1930\">7</sup>, הוא, כי הם ענינים נעלים ביותר<sup data-n=\"1931\">8</sup>. ומזה מובן גם בנוגע לאמירת הפסוקים קודם ההקפות, דזה שצריך להביא ראי' מן התורה על ענין ההקפות הוא מפני שהוא ענין נעלה ביותר. וכמבואר בלקו\"ת<sup data-n=\"1932\">9</sup>, דזה שבתורה כתוב רק ניסוך היין משא\"כ ניסוך המים הוא רק הלכה למשה מסיני<sup data-n=\"1933\">10</sup>, הוא, כי ניסוך המים הוא ענין נעלה ביותר שאינו יכול להתלבש באותיות דתורה שבכתב, וזה שענין ההקפות לא נתפרש אפילו בתורה שבע\"פ והוא רק מנהג הוא מפני שענין ההקפות הוא נעלה יותר גם מניסוך המים. וזהו גם<sup data-n=\"1934\">11</sup> שהשמחה דשמחת בית השואבה, עם היותה שמחה גדולה ביותר, ועד שמי שלא ראה שמחת בית השואבה לא ראה שמחה מימיו<sup data-n=\"1935\">12</sup>, מ\"מ, היא במדידה והגבלה. כמובן גם מזה שבהשמחה דשמחת בית השואבה, רק חסידים ואנשי מעשה היו מרקדין,וכל העם באים לראות ולשמוע<sup data-n=\"1936\">13</sup>, דזה שיש הגבלה בנוגע לאלו השמחים בשמחה זו הוא מפני שכללות שמחה זו (גם בהחסידים ואנשי מעשה) היא במדידה והגבלה. משא\"כ בשמח\"ת, ובפרט בהקפות, מנהג ישראל (שתורה היא<sup data-n=\"1937\">14</sup>) שכל ישראל (אנשים נשים וטף) שמחים בה<sup data-n=\"1938\">15</sup>, לפי ששמחה זו היא למעלה ממדידה והגבלה. [ולהוסיף, שההקפות בפעם השני' (בליל שמח\"ת) מנהגן להיות בשמחה גדולה יותר מבפעם הראשונה (בליל שמע\"צ), כי כאשר השמחה היא באותה המדה שבהקפות הקודמות, בלי הוספה וריבוי, אינה שמחה בשלימות, כיון שנתיישנה. ואדמו\"ר הזקן כותב בסידורו<sup data-n=\"1939\">16</sup>, שגם כשערך את ההקפות בשמחה בבית הכנסת שלו, כשבא לבית הכנסת אחר שלא גמרו ההקפות ירנן וישמח גם עמהם]. וי\"ל שדוגמתו העבודה דתמליכוני עליכם שבר\"ה<sup data-n=\"1940\">17</sup>, שבה שוים כל ישראל, כמ\"ש<sup data-n=\"1941\">18</sup> אתם נצבים היום כולכם גו', שבהיום דר\"ה כל עשרה הסוגים דישראל (מראשיכם שבטיכם עד חוטב עציך ושואב מימיך) הם לאחדים כאחד<sup data-n=\"1942\">19</sup>.\nג) <b>והנה</b> בההתאחדות של כל הסוגים דישראל בר\"ה, שני ענינים<sup data-n=\"1943\">20</sup>. שבכל אחד יש מעלה דילי', ומשלימים זה את זה. וזה שיש מעלה בדרגות התחתונות לגבי ראשיכם יש לקשר עם הא דנעוץ סופן בתחילתן<sup data-n=\"1944\">21</sup>, שדוקא דרגות התחתונות (סופן) הן נעוצות בהתחילה (היינו ששרשם הוא בהתחילה שלפני סדר ההשתלשלות, דהמעלה שבראשיכם הוא שהם ההתחלה והראש דסדר ההשתלשלות, והשרש דדרגות התחתונות (סופן) הוא בתחילה שלפני סדר ההשתלשלות<sup data-n=\"1945\">22</sup>). ועוד ענין בהאחדות דישראל שבר\"ה, שכל ישראל הם קומה אחת, ענין אחד שלמעלה מהתחלקות, שאין בו ראש וסוף. וכמ\"ש<sup data-n=\"1946\">23</sup> ויהי בישורון מלך, דזה שישראל נק' בשם ישורון מלשון שיר הוא לפי שהם כמו העיגול (שיר הוא דבר עגול<sup data-n=\"1947\">24</sup>) שאין בו ראש וסוף. ועד\"ז הוא בהשמחה והריקודים דהקפות דשמע\"צ ושמח\"ת, שיש בהם דוגמת שני ענינים הנ\"ל. דזה שהריקוד הוא ברגלים והרגלים מנשאים ומגביהים את הראש הוא מפני שנעוץ סופן בתחילתן, היינו שיש התחלקות דראשורגל וברגל יש ענין שהוא למעלה מהראש<sup data-n=\"1948\">25</sup>. וזה שאופן השמחה דשמח\"ת היא (לא ע\"י לימוד ועיון אלא) שלוקחים ספר תורה כפי שהיא כרוכה ומכוסה במפה ומרקדין עמה, הוא מפני שהשמחה דשמח\"ת קשורה עם התורה כפי שהיא למעלה מגילוי, המקיף דתורה (שאינו יכול להתלבש בחכמה), כתר תורה<sup data-n=\"1949\">26</sup>, דמקיף אין בו ראש וסוף. ועפ\"ז יש לבאר השייכות דהפסוק אתה הראת להשמחה דהקפות, כי בפסוק אתה הראת דוגמת שני ענינים אלה, כדלקמן.\nד) <b>ויובן</b> זה בהקדים שבהחילוק שבין אתה לשון נוכח (גילוי) והוא לשון נסתר (העלם), שני פירושים. שאתה הוא למטה מהוא<sup data-n=\"1950\">27</sup>. דהוא לשון נסתר הוא האור שלמעלה מגילוי [דבכללות הוא אור הסובב שהשפעתו בעולמות אינה בגילוי אלא בהסתר והעלם<sup data-n=\"1951\">28</sup>] ואתה לשון נוכח (גילוי) הוא אור הממלא שהוא בגילוי בעולמות. ואתה הוא למעלה מהוא. כידוע בענין אתה<sup data-n=\"1952\">29</sup> הוא הוי' לבדך<sup data-n=\"1953\">30</sup>, שהוא קאי על האור שלמעלה מגילוי, ואתה הוא העצמות, שהוא בכל מקום בהתגלות, דשם שמים שגור בפי כל. וכן הוא גם באתה הראת לדעת, דשני פירושים בזה. דבלקו\"ת ד\"ה וידעת<sup data-n=\"1954\">31</sup> מבואר דמ\"ש<sup data-n=\"1955\">32</sup> וידעת היום והשבות אל לבבך כי הוי' הוא האלקים גו', אף שכבר נאמר אתה הראת לדעת כי הוי' הוא האלקים גו', הוא, כי זה שאתה הראת לדעת הוא הידיעה בממלא כל עלמין<sup data-n=\"1956\">33</sup>, והציווי וידעת גו' הוא שתהי' הידיעה בסובב כל עלמין. ובכ\"מ מבואר שאתה הראת לדעת קאי על העצמות. וכפירוש אדמו\"ר הזקן<sup data-n=\"1957\">34</sup> אתה דו עצמות א\"ס ב\"ה הראת האָסט זיך באַוויזן לדעת אַז מען זאָל דיך וויסן. דזה שהעצמות הוא בהתגלות (שלכן אומרים עליו אתה לשון נוכח) הוא שהוא בהתגלות כמו שהוא בעצמותו<sup data-n=\"1958\">35</sup>, וזה שכולם יודעים שיש אלוקה מצוי<sup data-n=\"1959\">36</sup> אין זה ידיעה והשגה. וזה שאפשר להיות ידיעה והשגה באלקות הוא ע\"י שהתגלות העצמות בשעת מ\"ת (אתה הראת) היתה באופן דלדעת,שיוכל להיות ידיעה באלקות בכלל, ויתירה מזו, שעי\"ז יהי' אפשר להיות ידיעה בהעצמות, אַז מען זאָל <i>דיך</i> וויסן. וממשיך בכתוב כי הוי' הוא האלקים אין עוד מלבדו, שהידיעה בו ית' (עי\"ז שאתה הראת לדעת) היא בשני ענינים, שהוי' הוא האלקים ושאין עוד מלבדו. וצריך להבין, הרי הוי' ואלקים הם שמות, דשם הוא רק הארה, ומהי השייכות של הידיעה שהוי' הוא האלקים <i>לאתה</i> הראת לדעת אַז מען זאָל <i>דיך</i> וויסן.\nה) <b>ויובן</b> זה ע\"פ המבואר בהדרושים עה\"פ אתה הראת<sup data-n=\"1960\">37</sup> דענין אתה הראת לדעת הוא זה שהוא ית' האציל ענין הידיעה בעצמותו בכדי שעי\"ז יוכל להיות בנבראים ידיעה באלקות. והנה בכ\"מ<sup data-n=\"1961\">38</sup> מבואר שהטעם להאצלת הע\"ס דאצילות הוא בכדי שעל ידם יהי' גילוי אלקות בעולם. כי עיקר הגילוי אלקות שבעולם (בפנימיות) הוא בעיקר בהמוחין ומדות שבהנבראים, זה שהנבראים יכולים לידע ולהשיג אלקות ולהתפעל מזה. וענין זה נמשך מהע\"ס דאצילות. דע\"י שנעשה כביכול באלקות (אצילות) הציור דמוחין ומדות, עי\"ז נמשך גם בהנבראים (ששרשם הוא מהע\"ס דאצילות) הידיעה וההתפעלות באלקות. דההתפעלות באלקות שבנבראים נמשך מהמדות דאצילות, והידיעה וההשגה באלקות שבנבראים נמשך מהמוחין דאצילות. וזה שמבואר בהדרושים ע\"פ אתה הראת לדעת שבכדי שתהי' בנבראים ידיעה באלקות האציל ענין הידיעה בעצמותו (אף שבכדי שתהי' בנבראים ידיעה באלקות הי' מספיק לכאורה הידיעה בחב\"ד דאצילות), יש לומר, שזהו בכדי שתהי' ידיעה כביכול גם בהעצמות, מען זאָל <i>דיך</i> וויסן. דע\"י שהידיעה דחב\"ד דאצילות נמשכה מענין הידיעה בעצמותו, לכן, הידיעה באלקות של הנבראים שנמשכת מחב\"ד דאצילות, היא שייכת גם לאוא\"ס שלמעלה מאצילות, ועד לידיעת העצמות.\n<b>וזהו</b> אתה הראת לדעת כי הוי' הוא האלקים, כי בע\"ס דאצילות (גם בחב\"ד דאצילות) יש אורות וכלים. דשרש האורות הוא מהוי' ושרש הכלים הוא מאלקים. וע\"י הידיעה שהוי' הוא האלקים, דהוי' ואלקים כולא חד<sup data-n=\"1962\">39</sup>, באים להידיעה שאין עוד מלבדו. כי שני השמות הוי' ואלקים כמו שהם מצד עצמם, הם שני ענינים שונים, ויתירה מזו שהם שני ענינים הפכיים, דהוי' הוא גילוי ואלקים הוא צמצום והעלם. וזה שהוי' ואלקים כולא חד הוא מפני ששניהם הם שמותיו של הקב\"ה שלמעלה משניהם<sup data-n=\"1963\">40</sup>, אלא שכך עלה ברצונו ית' שהגילוי שלו יהי' בשני הקוין דבל\"ג וגבול (גילוי וצמצום), ולכן, גם לאחרי שנמשכו בגילוי בענין השמות, שאז הם שני ענינים הפכיים, הם מתכללים זמ\"ז, ועד שהוי' ואלקים כולא חד.\nו) <b>והנה</b> זה שהאורות והכלים (הוי' ואלקים) בשרשם הם כולא חד, כמה מדריגות בזה. דבכללות הו\"ע עשר ספירות הגנוזות. שגם בע\"ס הגנוזות יש(דוגמת) אורות וכלים<sup data-n=\"1964\">41</sup>, והם השרש של האורות וכלים שבע\"ס הגלויות, אלא שבע\"ס הגנוזות הם כולא חד. דכמו שענין ההתחלקות דהספירות (חכמה, בינה וכו') הוא בספירות הגלויות משא\"כ ע\"ס הגנוזות הם כלולים כולם כאחד בבחינת התערבות והתאחדות<sup data-n=\"1965\">42</sup>, עד\"ז הוא גם בענין ההתחלקות דאורות וכלים, שבע\"ס הגנוזות הם (האורות והכלים) בהתאחדות. אבל בפרטיות, גם בע\"ס הגנוזות, אורות וכלים הם שני ענינים. וזה שהוי' ואלקים כולא חד הוא בכללות האור שלפני הצמצום. דהנה ידוע<sup data-n=\"1966\">43</sup> שבהאור שלפני הצמצום יש שתי מדריגות בכללות. שהאור מצד עצמו הוא אין סוף [והספירות שמצד האור עצמו הם ספירות אין קץ], והוא השרש דאור הסובב, ומצד זה שעלה ברצונו להאציל כו' יש בו גם השרש דעשר ספירות (ע\"ס הגנוזות), והוא השרש דאור הממלא. וזהו ששמו הגדול שלפני הצמצום הוא דוגמת הוי' בניקוד אלקים, שמצד עצמו הוא א\"ס, הוי', אלא שאעפ\"כ כלול בו גם השרש דאור הגבול (ממלא), אלקים. וכיון דזה שכלול בו השרש דאור הגבול הוא מפני שעלה <i>ברצונו</i> (דאוא\"ס הבל\"ג) שיהיו עשר ספירות, דאמיתית ענין הרצון הוא שגם לאחרי שרוצה באיזה דבר ענינו של הדבר שרוצה בו הוא (לא הדבר מצד עצמו, אלא) להשלים זה <i>שהוא</i> רוצה<sup data-n=\"1967\">44</sup>, לכן, השרש דאור הגבול כמו שהוא לפני הצמצום, הוא (לא ענין בפני עצמו, אלא) חד עם (הרצון של) אוא\"ס הבל\"ג. וכמובן גם מזה שמובא לעיל דשמו הגדול שלפני הצמצום הוא דוגמת הוי' בניקוד אלקים, היינו שהוא שם אחד שכולל שני הענינים דהוי' ואלקים. אמנם בפרטיות יותר, מכיון שגם ברצון יש תפיסת מקום להדבר שרוצים בו (שע\"י דבר זה דוקא נשלם הרצון), לכן, זה שבהאור שלפני הצמצום יש שרש לאור הסובב (בל\"ג, הוי') ושרש לאור הממלא (גבול, אלקים), הם כמו שני ענינים. ואמיתית הענין דהוי' ואלקים כולא חד הוא בבחינת היכולת (שלמעלה מענין הספירות, שאין שייך בו גם ספירות אין קץ), דזה שביכלתו להאיר (השרש דהוי') ושביכלתו שלא להאיר (השרש דאלקים) הוא חד ממש. וע\"ד המבואר במק\"א<sup data-n=\"1968\">45</sup>, דבהאור שלפני הצמצום, גם בהאור שקודם עלות הרצון, הגילוי וההעלם הם שני ענינים. ולכן, העבודה כמו שהיא מצד האור שלפני הצמצום היא להמשיך ריבוי אור (ע\"ד שקודם הצמצום הי' התגברות כח הגילוי על כח ההעלם). ובכדי שיהי' אתהפכא חשוכא לנהורא, שהחושך עצמו יהפך לאור, הוא דוקא מצד ענין היכולת. דכיון שהיכולת להאיר (שרש האור) והיכולת שלא להאיר (שרש החושך) הם חד ממש, לכן, ע\"י שמגיעים בבחינת היכולת, גם החושך נהפך לאור.\n<b>וזהו</b> הקשר דהוי' הוא האלקים עם אין עוד מלבדו, שע\"י הידיעה דהוי' הוא האלקים באים להידיעה שאין עוד מלבדו (כנ\"ל סעיף ה), דמזה שרואים שהוי' ואלקים הם מאוחדים כאחד ממש, שבעבודת האדם הוא ואהבת את הוי'אלקיך בכל לבבך בשני יצריך<sup data-n=\"1969\">46</sup>, שגם היצה\"ר (ששרשו מההעלם דאלקים) אוהב את הוי' (כמו היצ\"ט ששרשו מהגילוי דהוי'), מזה יודעים שאין עוד מלבדו, שהשרש דשני הענינים (של הגילוי דהוי' וההעלם דאלקים) הוא זה שביכלתו להאיר וביכלתו שלא להאיר, דענין היכולת אינו דבר כלל זולת העצמות והוא רק שהעצמות הוא יכול, אין עוד מלבדו. וזהו גם מה שאומר בתחלת הכתוב <i>אתה</i> הראת לדעת, דו האָסט זיך באַוויזן אַז מען זאָל <i>דיך</i> וויסן, כי כיון שענין היכולת הוא זה שהעצמות הוא יכול, הידיעה בענין היכולת היא ידיעת העצמות<sup data-n=\"1970\">47</sup>.\nז) <b>ועפ\"ז</b> יש לבאר גם השייכות דשני הפירושים (דלעיל סעיף ד) באתה הראת לדעת, שאתה הראת לדעת היא הידיעה בממלא כל עלמין ושאתה הראת לדעת היא הידיעה בהעצמות (מען זאָל <i>דיך</i> וויסן), כי הידיעה וההתבוננות באור המתלבש בעולמות (אור הממלא) הוא בעיקר בכדי שגם השכל דנפש הבהמית ידע אלקות<sup data-n=\"1971\">48</sup>, וזה שגם השכל דנה\"ב יכול להבין אלקות (ובאופן שעי\"ז יבוא לביטול היש, היפך הטבע שלו), הוא ע\"י גילוי יכולת העצמות, שעי\"ז גם החושך נהפך לאור. שידיעה זו היא בכח העצמות, אבל הידיעה עצמה היא רק באור הממלא. ולאחרי ידיעה זו, צריכה להיות הידיעה וההתבוננות באור הסובב [שזהו הציווי וידעת גו', כנ\"ל סעיף ד], ושאור הממלא המתלבש בעולמות הוא רק הארה בלבד שבאין ערוך לגבי אוא\"ס שלמעלה מעולמות (אור הסובב), ואז דוקא הוא שייך להתבונן ולידע היתרון בהידיעה דאור הממלא שמובן גם בהשכל דנה\"ב, שידיעה זו היא מצד יכולת העצמות, כנ\"ל.\nח) <b>ועפ\"ז</b> יש לבאר גם זה שמובא לעיל (סעיף ה) מהדרושים, דזה שהוא ית' האציל ענין הידיעה בעצמותו הוא בכדי שעי\"ז יוכל להיות בנבראים ידיעה באלקות, דמזה שהכוונה בהאצלת הידיעה בעצמותו היא בכדי שהנבראים ידעו אלקות, מובן, שיש יתרון בידיעה זו (שהנבראים יודעים אלקות) לגבי הידיעה שבעצמותו. וע\"ד המבואר בתניא<sup data-n=\"1972\">49</sup> שהתכלית בהשתלשלות העולמות הוא לא בשביל עולמות העליונים, הואיל ולהם ירידה מאור פניו ית', והתכלית דעולמות העליונים הוא זה שעל ידם נתהווה עולם הזה התחתון, שעי\"ז נשלמת הכוונה דדירה בתחתונים<sup data-n=\"1973\">50</sup>, דירה לעצמותו<sup data-n=\"1974\">51</sup>. ונמצא, דענין זה שבעולמות העליונים, שעל ידם מתהווה עוה\"ז התחתון, הוא נעלה יותר מעולמות העליונים עצמם. דעולמות העליונים עצמם הם בבחינת ירידה, וזה שעל ידם נתהווה עוה\"ז התחתון, הואהעלי' שלהם. ועד\"ז הוא גם בנוגע להאצלת הידיעה בעצמותו, שהידיעה היא כמו ירידה מאור פניו [דעם היות שהאצלת ידיעה זו היא בעצמותו, מ\"מ, לגבי העצמות כמו שהוא מצד עצמו (לפני שהאציל הידיעה), הידיעה היא ירידה], והתכלית דהאצלת הידיעה הוא שעל ידה יהי' ידיעת אלקות בהנבראים, עד בהשכל דנפש הבהמית, שעי\"ז מתגלה יכולת העצמות<sup data-n=\"1975\">52</sup>, וע\"י ההמשכה מידיעת עצמו ידיעת אלקות בהנבראים, נעשה עלי' כביכול בידיעת עצמו.\nט) <b>ויש</b> לומר, שהעלי' שנעשית בידיעת עצמו על ידי ידיעת אלקות בהנבראים הוא ע\"ד ההשפעה מהרגל להראש, מצד זה ששרש הרגל הוא למעלה מהראש, נעוץ סופן בתחילתן<sup data-n=\"1976\">53</sup>. דענין זה שייך עדיין לסדר השתלשלות. ועוד ענין באתה הראת לדעת, שע\"י ידיעת אלקות דהנבראים נמשך (אח\"כ) הגילוי דאין עוד מלבדו, יכולת העצמות. וזהו שקודם הקפות אומרים אתה הראת לדעת גו' אין עוד מלבדו, שהוא ביאור בגודל העילוי של השמחה דהקפות. דזה שהשמחה היא באופן שהרגלים מגביהים ומנשאים את הראש, הכוונה בזה היא לראש האדם ולהראש שבכל דרגא ודרגא, עד לדרגת ידיעת עצמו. ויתירה מזו, שע\"י הריקודים דשמח\"ת נמשך בחינת המקיף שלמעלה מהגדרים דראש ורגל, ועד להגילוי דאין עוד מלבדו, יכולת העצמות.\n<b>והכלי</b> לשני ענינים אלה הוא האחדות דישראל בשני אופנים. שכל אחד מקבל מחבירו, ושכל ישראל הם קומה אחת. ועד\"ז בעבודה הפרטית דכאו\"א, שיש בזה שני ענינים אלה. העבודה דעשר כחות הנפש שלו (שהם דוגמת עשרה הסוגים מראשיכם שבטיכם עד חוצב עציך ושואב מימיך<sup data-n=\"1977\">54</sup>) באופן שכל הכחות מקבלים זה מזה ומשלימים זה את זה, והעבודה שמצד יחידה שלמעלה מהתחלקות. וזוהי גם הכנה קרובה לגאולה האמיתית והשלימה ע\"י משיח צדקנו, כי ענינו של משיח הוא יחידה<sup data-n=\"1978\">55</sup>. וזהו שבכל אחד מישראל יש ניצוץ משיח<sup data-n=\"1979\">56</sup>, שהיחידה הפרטית שבכ\"א מישראל היא ניצוץ מהיחידה הכללית דמשיח [וע\"ד משה (גואל ראשון<sup data-n=\"1980\">57</sup>) שבכ\"א מישראל יש בחינת משה שבו<sup data-n=\"1981\">58</sup>], יבוא ויגאלנו ויוליכנו קוממיות לארצנו, בגאולה האמיתית והשלימה בקרוב ממש.\n**********",[["1923","*","יצא לאור ב<b>קונטרס שמע\"צ ושמח\"ת – תש\"נ</b>, \"לקראת שמע\"צ ושמח\"ת . . <i>ערב חג הסוכות</i>,<i> שנת ה'תש\"נ</i>\"."],["1924","1","ואתחנן ד, לה."],["1925","2","בסה\"מ ה'תש\"ד שבהערה הבאה, שהשייכות די\"ז (פסוקים) להקפות היא, כי י\"ז בגימטריא טוב ואין טוב אלא תורה (אבות פ\"ו, ג)."],["1926","3","סד\"ה לעושה נפלאות ה'תש\"ד (סה\"מ ה'תש\"ד ע' 54)."],["1927","4","כ\"ה הלשון בסה\"מ ה'תש\"ד שם. וצע\"ק, דלכאורה הול\"ל \"שמביאים ראי' מן התורה על השמחה דשמע\"צ ושמח\"ת\", ע\"ד הלשון בכ\"מ (נסמנו בהערה 7) בענין פסוקי מלכיות זכרונות ושופרות."],["1928","5","סה\"מ ה'תש\"ד שם."],["1929","6","ראה לקו\"ש ח\"ד ע' 1146 הערה 14."],["1930","7","סידור (עם דא\"ח) רלח, ב. המשך וככה תרל\"ז פרק פב-פג. סה\"מ תרצ\"ט ע' 28. ובכ\"מ. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380945\" data-slug=\"likkutei-torah\" data-id=\"4001380945\">לקו\"ת</a> דרושים לר\"ה נו, ג."],["1931","8","ראה בארוכה המשך תרס\"ו ע' תקלז ואילך."],["1932","9","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381045\" data-slug=\"likkutei-torah\" data-id=\"4001381045\">לקו\"ת</a> דרושים לסוכות פ, ב-ג. סידור (עם דא\"ח) שער הסוכות רסח, ד ואילך."],["1933","10","סוכה לד, רע\"א. וש\"נ. רמב\"ם הל' תמידין ומוספין פ\"י ה\"ו."],["1934","11","בהבא להלן ראה ג\"כ <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141079\" data-slug=\"likkutei-sichot\" data-id=\"1300141079\">לקו\"ש חי\"ד ע' 67-166</a>."],["1935","12","סוכה נא, א (במשנה)."],["1936","13","סוכה שם. רמב\"ם הל' לולב פ\"ח הי\"ד."],["1937","14","ראה תוד\"ה נפסל, מנחות כ, ב. ושם: מנהג <i>אבותינו</i> תורה היא. ועד\"ז במהרי\"ל הובא ברמ\"א יו\"ד סשע\"ו ס\"ד. שו\"ע אדה\"ז או\"ח סתצ\"ד רסט\"ז. ובמנהגים ישנים מדורא ע' 153: והמנהג תורה היא. ובשו\"ע אדה\"ז או\"ח סו\"ס קפ: ומנהגן <i>של ישראל</i> תורה היא. וראה ירושלמי פסחים פ\"ד ה\"א."],["1938","15","ראה סידור שם רסט, א \"ושמחת ההקפות כו' גבוהה היא הרבה גם מבחי' שמחת בית השואבה וכל ישראל ראויים לה\"."],["1939","16","ב\"סדר הקפות בשמחת תורה\" (לפני \"אתה הראת\")."],["1940","17","ר\"ה טז, א. לד, ב."],["1941","18","נצבים כט, ט-י."],["1942","19","לקו\"ת ר\"פ נצבים."],["1943","20","כן מובן מאריכות הלשון בלקו\"ת שם. וראה לקו\"ש ח\"ד ע' 1141 ואילך."],["1944","21","ספר יצירה פ\"א מ\"ז."],["1945","22","ראה המשך תרס\"ו ע' שלח. שם ע' שמה-ו. ובכ\"מ."],["1946","23","ברכה לג, ה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380895\" data-slug=\"likkutei-torah\" data-id=\"4001380895\">לקו\"ת שם (מד, א</a>. מה, א)."],["1947","24","ראה שבת נא, ב ובפרש\"י שם. וראה סה\"מ ה'תש\"ב ע' 48."],["1948","25","ראה סהמ\"צ להצ\"צ קכד, ב \"מהו\"ע נמצא למטה כמו שנמצא למעלה ממש בלי שום חילוק ושינוי כלל . . כי אינו בבחי' גדר עלמין כלל וכדכתיב (תהלים קמח, יג) כי נשגב שמו לבדו רק הודו על ארץ ושמים הודו בלבד . . ואף גם בבחי' זו ארץ קדמה לשמים\". והיינו שגם הענין דארץ קדמה לשמים הוא גדר עלמין. וזה שאינו בגדר עלמין הוא נמצא למטה כמו למעלה ממש, בלי שום חילוק (גם לא החילוק דמעלת המטה). ועצ\"ע."],["1949","26","ראה סה\"מ ה'תש\"ב ע' 49. ולהעיר מהמבואר שם שזהו\"ע ויהי בישורון מלך. – שמזה מובן, שהמקיף דשמח\"ת הוא דוגמת המקיף דר\"ה."],["1950","27","סידור (עם דא\"ח) לט, ג."],["1951","28","<a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח (סח, רע\"א</a>)."],["1952","29","נחמי' ט, ו."],["1953","30","ראה ד\"ה וחזקת והיית לאיש ה'תשכ\"ח ס\"ב (לקמן ח\"ד ע' קד). וש\"נ."],["1954","31","הא' – לקו\"ת ואתחנן ד, א ואילך. עיי\"ש ד, ד."],["1955","32","ואתחנן ד, לט."],["1956","33","וכ\"ה גם בסה\"מ עת\"ר שבהערה 48."],["1957","34","הובא ברד\"ה אתה הראת דש\"פ ואתחנן ה'ש\"ת (סה\"מ ה'ש\"ת ס\"ע 146). סה\"מ ה'תש\"ד ע' 220. וכ\"ה ברד\"ה אתה הראת תרפ\"ט (סה\"מ קונטרסים ח\"א נו, א. סה\"מ תרפ\"ט ע' 227). ה'תש\"ג (סה\"מ ה'תש\"ג ע' 59). סד\"ה לעושה נפלאות ה'תש\"ד (סה\"מ ה'תש\"ד ע' 54)."],["1958","35","כ\"ה ברוב המקומות שנסמנו בד\"ה הנ\"ל ה'תשכ\"ח הע' 13."],["1959","36","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370064\" data-slug=\"torah-or\" data-id=\"3901370064\">תו\"א וירא יד, ב</a>."],["1960","37","ד\"ה הנ\"ל תרפ\"ט (סה\"מ קונטרסים שם נח, ב. סה\"מ תרפ\"ט ע' 233 ואילך) וה'ש\"ת (סה\"מ ה'ש\"ת ע' 147)."],["1961","38","ראה המשך תער\"ב ח\"א פמ\"ז (ע' פב). סה\"מ ה'תש\"ג ע' 131."],["1962","39","ראה זהר ח\"ב קסא, א. ח\"ג רסד, א."],["1963","40","ראה שעהיוה\"א פ\"ו (פ, ב)."],["1964","41","המשך תרס\"ו ע' תקי. ובכ\"מ."],["1965","42","המשך תער\"ב ח\"א פי\"ט ואילך. ובכ\"מ."],["1966","43","ראה בארוכה בכ\"ז המשך תרס\"ו ע' קפה."],["1967","44","ראה ד\"ה שובה ישראל דוא\"ו תשרי שנה זו (תשל\"ז) ס\"ב (לעיל ע' צ ואילך). וש\"נ."],["1968","45","סה\"מ קונטרסים ח\"ב שמו, א."],["1969","46","ואתחנן ו, ה. ברכות נד, א במשנה. ספרי (הובא בפרש\"י) עה\"פ. ובלקו\"ת ואתחנן רד\"ה וידעת הב' (ז, ד) \"היצר טוב והיצר הרע הם שניהם כאחד . . וכמ\"ש בכל לבבך בשני יצריך ומזה וידעת כי כך הוי' הוא האלקים\"."],["1970","47","להעיר מסה\"מ קונטרסים שם \"כמו שהעצמות הוא בבחי' אתה כמו\"כ הוא בחי' שמו הכלול בעצמותו\" (יכולת). ועפ\"ז יומתק יותר מ\"ש על גילוי היכולת \"<i>אתה</i> הראת לדעת\"."],["1971","48","סה\"מ עת\"ר ע' כה. ושם, שזהו\"ע אתה הראת לדעת, עיי\"ש."],["1972","49","פל\"ו. וראה סה\"מ תרנ\"ח ע' ל ואילך."],["1973","50","ראה תנחומא נשא טז. בחוקותי ג. במדב\"ר פי\"ג, ו. תניא שם."],["1974","51","המשך תרס\"ו ס\"ע ג. ובכ\"מ. – נסמן לקמן ח\"ב ע' שח."],["1975","52","ואף שגם היכולת אינה העצמות, מ\"מ, הרי היא היכולת שלו כמו שהוא מצד עצמו (ולא <i>שנאצלה</i>). וראה המשך תרס\"ו ע' קפו שהיכולת היא שמו שקדמון כקדמותו."],["1976","53","ראה סה\"מ תרנ\"ח ריש ע' ל \"דכשם שנת\"ל . . שיש יתרון בז\"א על או\"א ובמלכות על כל הע\"ס מצד שרשם הקדום כמו\"כ הוא בעולמות בי\"ע נגד עולם האצילות\"."],["1977","54","ראה לקו\"ת ר\"פ נצבים, פרט הכתוב עשר מדריגות כמו שיש עשר מדריגות בנפש האדם."],["1978","55","רמ\"ז לזח\"ג רס, ב (נדפס במקדש מלך קצ, ב). ל\"ת להאריז\"ל עה\"פ (בראשית ה, כב) ויתהלך חנוך. ועוד. וראה אוה\"ת נצבים ע' א'רעו. סה\"מ תרכ\"ז ע' טז. תרנ\"ה ס\"ע יט ואילך. תרצ\"ט ע' 207. ועוד."],["1979","56","מאור עינים ס\"פ פינחס."],["1980","57","ראה שמו\"ר פ\"ב, ד. זח\"א רנג, א. שעה\"פ להאריז\"ל פ' ויחי. תו\"א ר\"פ משפטים."],["1981","58","<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב</a>."]]],[1500360030,"<h3>בס\"ד. מוצאי שמחת תורה – בחדרו – ה'תשל\"ח<sup data-n=\"1982\">*</sup></h3>\n<b>להבין</b> ענין שמחת תורה, וידוע הדיוק בזה<sup data-n=\"1983\">1</sup> מה שאופן השמחה (דשמחת תורה) הוא שלוקחים ספר תורה כפי שהיא כרוכה ומכוסה במפה<sup data-n=\"1984\">2</sup> ומרקדין עמה. דעם היות שבתורה כתיב<sup data-n=\"1985\">3</sup> כי היא חכמתכם ובינתכם גו' מ\"מ אופן שמחה זו הוא לא ע\"י לימוד ועיון כ\"א ע\"י ריקוד דוקא. שלכן השמחה דשמחת תורה היא אצל כל ישראל, גם אצל פשוטים ביותר שאין שייכים להשגה והבנה [ויתירה מזו, שבעת השמחה וריקודים דהקפות נמשכים (ווערן צוגעצויגן) גם כאלו שבשאר ימי השנה אין ניכר הקשר וההתאחדות שלהם עם [עניני] התורה, כמו שרואים במוחש]. וענין זה (שהשמחה דשמחת תורה היא בכל אחד מישראל) מתבטא גם בזה שמרקדין עם ספר תורה – תורה שבכתב דוקא, שאפילו זה שלא ידע מאי קאמר מברך ברכת התורה כשקורא בתושב\"כ<sup data-n=\"1986\">4</sup>. ומכיון שזה מה שמברך ברכת התורה הוא ע\"פ <i>ציווי</i> תורת <i>אמת</i>, הרי פשוט שכן היא המציאות, שגם זה שלא ידע מאי קאמר ממשיך אוא\"ס ועד עצמות ומהות (נותן התורה) בהתורה שלומד. גם ידוע<sup data-n=\"1987\">5</sup> הדיוק למה עושין שמחת תורה בשמיני עצרת (ובחו\"ל ביו\"ט שני דשמיני עצרת), דלכאורה הי' צ\"ל בחג השבועות זמן מתן תורתינו.\nב) <b>ומובא</b> הביאור בזה<sup data-n=\"1988\">6</sup> ע\"פ מה דאיתא במדרש<sup data-n=\"1989\">7</sup> ראוי' היתה העצרת של חג שתהא רחוקה חמשים יום כנגד העצרת של פסח אלא עצרת של חג ע\"י שהן יוצאין מן הקיץ לחורף לית ביומייהו דיזלון וייתון, משל למה\"ד למלך שהיו לו בנות הרבה, מהן נשואות למקום קרוב ומהן נשואות למקום רחוק, יום אחד באו כולן לשאול שלום המלך אביהם, אמר המלך אלו שנשואות במקום קרוב אית בעונתן למיזל ולמיתי, ואילין שנשואות במקום רחוק לית בעונתן למיזל ולמיתי, עד דאינון כולן אצלי הכא נעביד כולן חד יו\"ט ונחדי עמן, כך עצרת של פסח עד דאינון נפקין מחורף לקיץ אמר הקב\"ה אית ביומא למיזל ולמיתי, אבל עצרת של חג ע\"י שהן יוצאין מהקיץ לחורף כו' אמר הקב\"ה לית ביומא למיזל ולמיתי אלא עד דאינון הכא נעביד כולן חד יו\"ט ונחדי. וזהו מה שעושין שמחת תורה בשמיני עצרת, כי ה\"יום אחד\" שבו באים כל הבנות [בנות ציון וירושלים, היינו נשמות ישראל<sup data-n=\"1990\">8</sup>]לשאול שלום המלך אביהם קאי<sup data-n=\"1991\">9</sup> על יום הכפורים, ולאח\"ז אומר נעביד כולן חד יו\"ט ונחדי, הוא<sup data-n=\"1991\">9</sup> שמחת תורה (שנקבע בשמיני עצרת), שהוא \"<i>חד</i> יו\"ט\" בדוגמת ה\"יום אחד\" דיום הכפורים.\nג) <b>ויובן</b> זה ע\"פ מה שנת\"ל (ד\"ה בסוכות תשבו<sup data-n=\"1992\">10</sup>) שכל המועדים דחודש תשרי הם בבחי' של אחת. דהנה על ראש השנה ארז\"ל<sup data-n=\"1993\">11</sup> מצות היום בשופר. היינו, דזה מה שהיום דראש השנה הוא חלוק משאר המועדים הוא במצוה אחת (איין און איינציקע מצוה), מצות שופר. ובמצוה זו גופא כותב הרמב\"ם<sup data-n=\"1994\">12</sup> שהיא גזירת הכתוב למעלה מטעם. דהגם שהמצוה דשופר גם מרמזת על ענינים הכי נעלים בענין התשובה (כמו שממשיך הרמב\"ם<sup data-n=\"1994\">12</sup> רמז יש בדבר כו') מ\"מ ענינה הוא גזירת הכתוב למעלה מטעם. ועד\"ז הוא גם בנוגע ליום הכפורים [סיום העשרת ימים שבין ראש השנה ליום הכפורים], שהיא בחי' אחת דכל הג' בחי' דעולם שנה נפש. שהעבודה המיוחדת דיום הכפורים היא בקודש הקדשים בחי' אחת דעולם (מקום), ביום דיום הכפורים שנקרא<sup data-n=\"1995\">13</sup> בשם אחת בשנה, בחי' אחת דשנה (זמן), ונעשית ע\"י כה\"ג [אלא שהכה\"ג עושה זה בתור שלוחם של כל ישראל] דכתיב<sup data-n=\"1996\">14</sup> בי' ויבדל אהרן להקדישו קודש קדשים, בחי' אחת דנפש. ועד\"ז הוא גם בנוגע לסוכות, שבענין הסוכה [שמצות ישיבה בסוכה היא במשך כל שבעת ימי הסוכות, מרגע הראשון שבהתחלתם] מודגש ענין האחדות (בחי' אחת) דכל ישראל כמרז\"ל<sup data-n=\"1997\">15</sup> ראוים כל ישראל לישב בסוכה אחת. וכמו\"כ הוא גם במצות נטילת ד' מינים [שענינה הוא להמשיך המקיף (דסוכה אחת) בפנימיות<sup data-n=\"1998\">16</sup>], שבכל אחד מד' מינים אלו ניכר ומודגש ענין האחדות, ובפרט באתרוג, שבו מודגש ענין האחדות עוד יותר [שלכן בסדר הד' מינים שבכתוב<sup data-n=\"1999\">17</sup> (שגם סדר בתורה הוא תורה) ההתחלה היא מאתרוג פרי עץ הדר], דזה מה שאתרוג נקרא בכתוב בשם פרי עץ הדר הוא לפי שדר באילנו משנה לשנה<sup data-n=\"2000\">18</sup>, היינו שהוא סובל את שינויי ד' האוירים שבמשך השנה, ועד אשר (לא רק שהוא סובל את כל האוירים אלא) הוא גדל מהם. ומענין האחדות שבאתרוג נמשך גם זה בשאר הג' מינים, שלכן הענין דהדר שבג' המינים למדים מאתרוג<sup data-n=\"2001\">19</sup>. ונוסף לזה שכל אחד מהד' מינים מורה על ענין האחדות, הנה המצוה בנטילת ד' מינים היא לאחדאת כל ד' המינים, שמורים על ד' הסוגים שבבנ\"י<sup data-n=\"2002\">20</sup>, שיהי' וייעשו כולם אגודה אחת לעשות רצונך בלבב שלם.\nד) <b>והנה</b> בכדי שיוכל להיות ההתאחדות האמיתית (ובת קיימא) של כל הד' סוגים דישראל, הוא ע\"י התשובה. דהנה ענין התשובה הוא למעלה מהתחלקות, שלכן היא בשעתא חדא וברגע חדא<sup data-n=\"2003\">21</sup>. דזהו ההפרש שבין לוחות הראשונות (ענין התורה מצ\"ע) ללוחות השניות (ענין תורה ע\"י תשובה), שבכדי לקבל לוה\"ר הי' משה בהר ארבעים יום, נוסף על ההכנה דשבעה שבועות תספר לך שהי' לפנ\"ז<sup data-n=\"2004\">22</sup>. משא\"כ בלוחות השניות, הרי הארבעים יום שהי' משה בהר הוא (בעיקר) בכדי לפעול שיתרצה הקב\"ה לישראל בשמחה ובלב שלם<sup data-n=\"2005\">23</sup>, ולאח\"ז ניתנו הלוחות בשעתא חדא. והנה ענין זה [מה שהתשובה היא בשעתא חדא וברגע חדא] מדגיש שענין התשובה הוא למעלה מכל מדידה והגבלה<sup data-n=\"2006\">24</sup>, מפני שתשובה אמיתית מגעת (דערנעמט) בפנימיות ועצמות הנפש, שבחינה זו היא למעלה מהתחלקות, בחי' אחת (בשעתא <i>חדא</i> וברגע <i>חדא</i>) דנפש. וזהו מה שע\"י התשובה נעשה ההתאחדות של כל הסוגים דישראל, מראשיכם שבטיכם עד חוטב עציך ושואב מימיך, ובאופן דאתם נצבים כולכם גו', נצבים מלשון נצב<sup data-n=\"2007\">25</sup> מלך<sup data-n=\"2008\">26</sup>, שישראל נעשים מלכים און בעלי בתים על כל המציאות דעולם, מתחיל מזה שהם נכתבים ונחתמים בכתיבה וחתימה טובה לשנה טובה ומתוקה בטוב הנראה והנגלה למטה מעשרה טפחים גם בענינים הגשמיים, מכיון שמצד בחי' זו אין שייך לחלק בין רוחניות לגשמיות ובין מעלה למטה, און דאָס נעמט דורך את כל סדר ההשתלשלות וגם מה שלמעלה מסדר ההשתלשלות.\n<b>וזהו</b> ענין יום אחד באו כולן לשאול שלום המלך אביהם כו' נעביד כולן חד יו\"ט ונחדי עמן, יום אחד (שבו באו כולן לשאול שלום המלך אביהם) הוא יום הכפורים, אחת דשנה (וגם אחת דעולם ודנפש), ומזה נמשך אח\"כ נעביד כולן חד יו\"ט כו' שקאי על שמחת תורה, שהוא ג\"כ יום אחד (<i>חד</i> יו\"ט), בחי' אחת.\nה) <b>והנה</b> ההתעוררות דבחי' אחת שבנפש שלמעלה מהתחלקות צריך להמשיכה בהדרגות דנפש שבבחינת התחלקות [ובדוגמת מה שהתעוררות זו צריכה להיות קשורה בעשי' גשמית, וכמו בהעשי' דישיבה בסוכה, נטילת ד' מינים, ריקוד ברגלים]. דזהו מה שלאחרי שנאמר אתם נצבים גו' כולכם גו' שכל ישראל הם באופןד\"כולכם\"<sup data-n=\"2009\">27</sup> מצד בחינת אחת שבהם, מונה אח\"כ כל העשר סוגים בפרטיות, מראשיכם שבטיכם עד חוטב עציך ושואב מימיך, היינו שהענין דכולכם (בחינת אחת) דישראל צריך להיות ניכר בהם גם כמו שהם בבחינת התחלקות. וכמו שהוא בנפש עד\"ז הוא גם בשנה, שבחינת יום אחד דיום הכפורים ודשמחת תורה פועלת און פירט אָן מיט אַלע ימי השנה (מתחיל מאסרו חג), שבכל פרטי עשיותיו (בכל מעשיך ובכל דרכיך), ניכר אַז ער איז אָט ערשט געקומען מיום אחד דיום הכפורים ודשמחת תורה. וענין זה הוא במשך כל השנה כולה, דאף שכבר עברו כמה וכמה ימים שבועות וחדשים מיום הכפורים ושמחת תורה, אעפ\"כ ההתעוררות דיום אחד אינה נחלשת כלל ובתקפה עומדת, מכיון שבאה מבחינה שלמעלה מענין ההתחלקות והשינויים, בחינת אני<sup data-n=\"2010\">28</sup> הוי' לא שניתי. ועל ידי שהבחינה דיום אחד שלמעלה מהתחלקות נמשכת בכל ימי השנה שבבחינת התחלקות ושינויים, עי\"ז נעשה עילוי גם בהבחינה דיום אחד, ע\"ד מה שנת\"ל בענין פרי עץ הדר אשר לא רק שהוא סובל כל שינויי האוירים אלא שהוא גדל מהם.\nו) <b>ויהי</b> רצון, שכל הנ\"ל יתקיים בכל אחד ואחת בתוככי כלל ישראל, שתהי' שנה טובה ומבורכת בטוב הנראה והנגלה למטה מעשרה טפחים, בבני חיי ומזוני ובכולם רויחי, הן בבני חיי ומזוני כפשוטם והן בבני חיי ומזוני ברוחניות<sup data-n=\"2011\">29</sup> (שמהם משתלשלים הענינים כפשוטם<sup data-n=\"2012\">30</sup>), אשר מתוך שמחה וטוב לבב תהי' מיד לאחרי שמחת תורה העבודה דויעקב הלך לדרכו<sup data-n=\"2013\">31</sup> גם בהנוגע לעניני הרשות [שענין ויעקב הלך לדרכו שאחרי יום הכפורים<sup data-n=\"2014\">32</sup> הוא ב\"דרכו\" בענין המצוות, שהרי בד' הימים שבין יום הכפורים לסוכות כל ישראל עסוקים במצוות<sup data-n=\"2015\">33</sup>. משא\"כ ענין ויעקב הלך לדרכו שלאחרי שמחת תורה הוא ב\"דרכו\" גם בעניני הרשות], שבכל יום ויום, הן בימי החול ועאכו\"כ בשבת ויו\"ט (כולל גם ראש השנה ויום הכפורים), זיינען דורכגענומען כל עניניו, הן ענינים הכללים הן ענינים הפרטים, בנקודה העיקרית והפנימית דפנימיות ועצמות הנשמה, שהיא קשורה בפנימיות ועצמות א\"ס ב\"ה.\nז) <b>ומכיון</b> שזה בא משמחת תורה, ששמחה פורצת כל הגדרים, למעלה ממדידה והגבלה<sup data-n=\"2016\">34</sup>, הרי זה פורץ ומבטל כל הגדרים וההגבלות דגלות הפנימי, וכן הגדרים וההגבלות דגלות כפשוטו, וזוכים שבקרוב ממש יהי' ותחזינה עינינו בשובך לציון ברחמים, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, יבוא ויוליכנו קוממיות לארצנו במהרה בימינו ממש, ויבנה<sup data-n=\"2017\">35</sup> בית המקדש במקומו ויקבץ נדחיישראל וכו' (ועד אשר) אז<sup data-n=\"2018\">36</sup> אהפוך אל עמים שפה ברורה וגו' ולעבדו<sup data-n=\"2019\">37</sup> שכם אחד, והיתה<sup data-n=\"2020\">38</sup> לה' המלוכה.\n**********",[["1982","*","יצא לאור ב<b>קונטרס מוצאי שמחת תורה – ה'תשל\"ח</b>, \"<i>עש\"ק בראשית ה'תשל\"ח</i>\"."],["1983","1","ד\"ה ביום השמע\"צ תרפ\"ט. ד\"ה עץ חיים תרצ\"ט. ד\"ה להבין ענין שמח\"ת תש\"ה ותש\"ו."],["1984","2","שאז אין שייך ללמוד אותה. ובפרט ע\"פ מרז\"ל (גיטין ס, ב) דדברים שבכתב אי אתה רשאי לאומרן בע\"פ."],["1985","3","ואתחנן ד, ו."],["1986","4","הל' ת\"ת לאדה\"ז פ\"ב סי\"ב-יג. וש\"נ."],["1987","5","אוה\"ת שמע\"צ ע' א'תשעט ואילך. ד\"ה ביוהשמע\"צ תרפ\"ט ותש\"ו."],["1988","6","ד\"ה ביוהשמע\"צ שם."],["1989","7","שהש\"ר פ\"ז, ב (ב)."],["1990","8","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381155\" data-slug=\"likkutei-torah\" data-id=\"4001381155\">לקו\"ת שה\"ש ו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381218\" data-slug=\"likkutei-torah\" data-id=\"4001381218\">כב, ב</a>. אוה\"ת שה\"ש ע' פט ואילך."],["1991","9","סד\"ה ביוהשמע\"צ תרפ\"ט, סד\"ה להבין ענין שמח\"ת תש\"ו."],["1992","10","תשל\"ח (לעיל ע' קלד ואילך)."],["1993","11","משנה ר\"ה כו, ב."],["1994","12","הל' תשובה פ\"ג, ה\"ד."],["1995","13","אחרי טז, לד."],["1996","14","דברי הימים-א כג, יג."],["1997","15","סוכה כז, ב."],["1998","16","סדור רסה, סע\"א ואילך. המשך תרס\"ו ס\"ע לב. ובכ\"מ."],["1999","17","אמור כג, מ."],["2000","18","סוכה לה, א."],["2001","19","סוכה לא, א. שו\"ע אדה\"ז סתרמ\"ה ס\"ב. ואף ששם הוא בנוגע להדר כפשוטו – הרי ע\"פ הביאור שגדל מהם מובן שגם הדר כפשוטו גדל מהם."],["2002","20","ויק\"ר פ\"ל, יב."],["2003","21","זח\"א קכט, סע\"א."],["2004","22","ראה ר\"ן סוף מס' פסחים שענין ז' השבועות שמיציאת מצרים עד מתן תורה הוא מקור ענין שבעה שבועות תספר לך. וראה זח\"ג (צז, ב) שביציאת מצרים הייתה צ\"ל ההכנה והעבודה דז' שבועות קודם לקבלת התורה."],["2005","23","פרש\"י תשא לג, יא."],["2006","24","ראה לקו\"ת שבת שובה סה, א."],["2007","25","לשון הכתוב – מלכים-א כב, מח."],["2008","26","אוה\"ת נצבים ע' א'רא."],["2009","27","ראה לקו\"ת ר\"פ נצבים."],["2010","28","לשון הכתוב – מלאכי ג, ו."],["2011","29","להעיר מחנוך לנער בסופו. אוה\"ת להצ\"צ ד\"ה והוי' פקד (בראשית כרך ד ע' 1510 ואילך)."],["2012","30","ע\"ד המבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>."],["2013","31","לשון הכתוב ויצא לב, ב. וראה שיחת אחרון של פסח תרצ\"ה (נדפסה בסה\"מ תשי\"א ע' 240)."],["2014","32","וככה תרל\"ז רפצ\"ו."],["2015","33","ויק\"ר פ\"ל, ז."],["2016","34","ראה ד\"ה שמח תשמח תרנ\"ז ע' 49 ואילך."],["2017","35","רמב\"ם הל' מלכים ספי\"א."],["2018","36","צפני' ג, ט."],["2019","37","בצפני' שם: לעבדו (בלא וא\"ו). אבל ברמב\"ם שם (ועוד): ולעבדו (בוא\"ו). וראה הערה במכתב י\"ג תשרי תשל\"ו (לקו\"ש חי\"ד ע' 414)."],["2020","38","עובדי' א, כא."]]],[1500360031,"<h3>בס\"ד. יום שמחת תורה ה'תש\"מ<sup data-n=\"2021\">*</sup></h3>\n<b>ביום</b> השמיני עצרת תהי' לכם<sup data-n=\"2022\">1</sup>, וידועים דיוקי רבותינו נשיאינו בזה, הרי שמיני עצרת הוא רגל בפני עצמו לענין פז\"ר קש\"ב<sup data-n=\"2023\">2</sup>, וא\"כ הול\"ל בעשרים ושנים יום לחודש השביעי כמו בשאר המועדים שנאמר בהם ימי החודש (ובחודש השביעי באחד לחודש, ובעשור לחודש השביעי, ובחמשה עשר יום לחודש השביעי<sup data-n=\"2024\">3</sup>), ולמה אומר ביום השמיני<sup data-n=\"2025\">4</sup>. והגם ששמיני עצרת בא בהמשך לז' ימי הסוכות, וידוע<sup data-n=\"2026\">5</sup> שבשמיני עצרת נעצרים ונקלטים הענינים דז' ימי הסוכות, הרי בשמיני עצרת נעצרים ונקלטים גם הענינים דראש השנה ויום הכפורים<sup data-n=\"2027\">6</sup>, ואעפ\"כ אינו נקרא בשם כזה שיורה על שייכותו (ושבא בהמשך) לראש השנה ויום הכפורים, ולמה נקרא השם שמיני (עצרת). ובפרט ע\"פ תורת הבעש\"ט<sup data-n=\"2028\">7</sup> דזה שמו אשר יקראו לו בלה\"ק מורה על תוכן הדבר, ועד שמורה על חיותו וקיומו, שמזה מובן, שעיקר ענינו דשמיני עצרת (שנקרא בשם <i>שמיני</i> עצרת) הוא מה שבא בהמשך לז' ימי הסוכות. גם צריך להבין מ\"ש עצרת תהי' לכם, ואיתא במדרש<sup data-n=\"2029\">8</sup> הה\"ד<sup data-n=\"2030\">9</sup> יהיו לך לבדך ואין לזרים אתך, שיש בזה ב' ענינים. ענין דלך לבדך, ישראל ומלכא בלחודוהי<sup data-n=\"2031\">10</sup>, אבל אעפ\"כ מזה גופא שצריך לשלול שאין לזרים אתך מובן שיש מקום לקס\"ד ששמיני עצרת הוא גם לזרים ולכן צריך לשלול ולומר שהוא רק לכם. גם צריך להבין מה ששמיני עצרת כולל גם שמחת תורה, ועד שבארץ ישראל, ארץ אשר גו' תמיד עיני ה' אלקיך בה מרשית השנה ועד אחרית שנה<sup data-n=\"2032\">11</sup>, שמיני עצרת ושמחת תורה הם ביום אחד, וגם בחו\"ל שהם ב' ימים הרי שמחת תורה הוא ביו\"ט שני דשמיני עצרת, וידוע הדיוק בזה מה שקבעו שמחת תורה בשמיני עצרת, דלכאורה הוצרכו לעשות שמחת תורה בחג השבועות זמן מתן תורתנו<sup data-n=\"2033\">12</sup>.ב) <b>והנה</b> בכ\"מ<sup data-n=\"2034\">13</sup> מבואר דזה שעושים שמחת תורה בשמיני עצרת הוא על לוחות האחרונות שניתנו ביום הכפורים<sup data-n=\"2035\">14</sup>, אבל זה גופא (מה שהשמחה דשמחת תורה היא על לוחות האחרונות דוקא ולא על לוחות הראשונות) צריך ביאור, הרי עיקר הגילוי והשלימות דמ\"ת הי' בנתינת לוחות הראשונות דוקא, הן בנוגע לישראל שהיו אז בתכלית השלימות, דבמעמד הר סיני פסקה זוהמתן<sup data-n=\"2036\">15</sup>, והן בנוגע להעולם שהי' אז גילוי אוא\"ס ממש למטה כמ\"ש<sup data-n=\"2037\">16</sup> וירד ה' על הר סיני ותרגם ואתגלי, וגילוי זה פעל בכל העולם<sup data-n=\"2038\">17</sup> כמרז\"ל<sup data-n=\"2039\">18</sup> צפור לא צווח עוף לא פרח שור לא געה, ועד שהקול דעשרת הדברות הי' נשמע מכל ד' הרוחות ומלמעלה ומלמטה<sup data-n=\"2040\">19</sup>, אַז די וועלט (וכל הו\"ק שבה) האָט אויסגעשריען אנכי<sup data-n=\"2041\">20</sup> ה' אלקיך גו', לא יהי' לך גו'. דכל זה הי' בלוחות הראשונות דוקא, ולמה קבעו שמחת תורה בשמיני עצרת על לוחות האחרונות דוקא. ומה שמבואר בכ\"מ<sup data-n=\"2042\">21</sup> דזה שעושים שמחת תורה על לוחות האחרונות דוקא הוא מפני שבלוחות האחרונות כתיב ויגד לך תעלומות חכמה כי כפלים לתושי'<sup data-n=\"2043\">22</sup>, צריך ביאור, דמכיון שענין הגילוי (דמ\"ת) בישראל ובעולם הי' בלוחות הראשונות דוקא כנ\"ל, לכאורה צ\"ל השמחה דשמחת תורה שהיא בניגונים וריקודים (ענין הגילוי) בחג השבועות שבו ניתנו לוחות הראשונות בגילוי ובפרסום. ובפרט לפי המבואר<sup data-n=\"2044\">23</sup> בענין הריקודים (דשמחת תורה) שענין הריקודים הוא בעיקר בהרגלים, ובהם גופא בהעקב שבהם, חלק הכי תחתון שבאדם<sup data-n=\"2045\">24</sup> (אלא שעי\"ז מתנשא ורוקד גם הראש). שמזה מובן שהשמחה דשמחת תורה היא בעיקר לא מצד פעולת התורה בישראל לי ראש<sup data-n=\"2046\">25</sup>, כי אם, מצד פעולת התורה בעולם שהוא טפל<sup data-n=\"2047\">26</sup> לישראל, בדוגמת הרגלים שטפלים להראש, ובעולם גופא בענינים התחתונים שבו (בחי' עקב). ועפ\"ז אינו מובן יותר מה שקבעו שמחת תורה על לוחות האחרונות דוקא, שהעילוי דכפלים לתושי' שבלוחות האחרונות הוא בישראל. גם אינו מובן, דלפי זה (שהשמחהדשמחת תורה היא על לוחות האחרונות שניתנו ביום הכפורים) היו צריכים לעשות שמחת תורה למחרת יום הכפורים<sup data-n=\"2048\">27</sup>. דמה שלא קבעו שמחת תורה ביום הכפורים גופא י\"ל דזהו לפי שאין שמחה בלא אכילה ושתי'<sup data-n=\"2049\">28</sup>, אבל הי' צ\"ל מיד אחרי יום הכפורים. ואולי י\"ל יתירה מזו, הרי מצינו שבאותה שנה (דחנוכת ביהמ\"ק) לא עשו ישראל את יום הכפורים, ויצתה ב\"ק ואמרה להם כולכם מוזמנים לחיי העוה\"ב<sup data-n=\"2049\">28</sup>, כי השמחה דחנוכת ביהמ\"ק היא נעלית יותר מהעינוי דיום הכפורים. ומכיון שהשמחה דשמחת תורה היא שמחה גדולה ביותר, ועד שהיא גדולה יותר גם מהשמחה דשמחת בית השואבה<sup data-n=\"2050\">29</sup>, דמי שלא ראה שמחת בית השואבה לא ראה שמחה מימיו<sup data-n=\"2051\">30</sup>, א\"כ הי' ראוי לקבוע שמחת תורה ביום הכפורים גופא.\nג) <b>ויובן</b> זה בהקדים תחלה ענין לוחות הראשונות ולוחות האחרונות בעבודת האדם. דהנה עיקר הכוונה דמ\"ת הוא שתהי' קבלת התורה, עבודת האדם. דלוחות הראשונות הוא ענין עבודת הצדיקים ולוחות האחרונות הוא ענין עבודת הבע\"ת. והמעלה דלוחות האחרונות על לוחות הראשונות הוא מפני שעבודת התשובה נעלית יותר מעבודת הצדיקים<sup data-n=\"2052\">31</sup>. והענין הוא, דהנה כללות החילוק בין לוחות הראשונות ללוחות האחרונות הוא דנתינת לוחות הראשונות היתה מצד למעלה, וירד הוי' על הר סיני. דהגם שהגילוי דמ\"ת פעל גם בעולם וגם בהדומם שבו, ועד שהעולם (גם הדומם שבו) איז געוואָרן דורכגענומען מהגילוי דמ\"ת, אעפ\"כ אין זה שנעשה זיכוך תמידי ועלי' בהעולם, ורק שהאיר בו הגילוי שלמעלה<sup data-n=\"2053\">32</sup>. ועד\"ז גם בישראל, דמה שהגילוי דמ\"ת פעל גם בהגוף (שפסקה זוהמתן) הי' זה מצד הנשמה. דבעת מ\"ת הי' אצלם גילוי עצם הנשמה, בחי' יחידה [שאינה מציאות לעצמה וכל מציאותה הוא זה שהיא כלי ומקבלת מבחי' יחיד<sup data-n=\"2054\">33</sup>], ומכיון שגם בחי' יחידה היא קשורה עם הגוף<sup data-n=\"2055\">34</sup>, לכן, הגילוי דבחי' יחידה האיר גם בהגוף, עד בבחי' עקב שבו, וע\"ד מ\"ש גבי אברהם<sup data-n=\"2056\">35</sup> עקב אשר שמע אברהם בקולי גו'<sup data-n=\"2057\">36</sup>. והטעם לזה הוא לפי שהגילוי דמ\"ת הי' בדרך אתערותא דלעילא שלא ע\"י אתערותא דלתתא, דהגם שהיתה העבודה דספירת העומר במשך הז' שבועות שבין יצי\"מ למ\"ת, הרי מובן, שע\"י עבודה זו (שבמשך המ\"ט יום ונ' יום) לא היו בערך להיות בבחי' כלילהגילוי דמ\"ת<sup data-n=\"2058\">37</sup>, כי אם, שהגילוי דמ\"ת הי' בדרך אתעדל\"ע מצ\"ע, ואני המתחיל<sup data-n=\"2059\">38</sup>, ומה שהוצרך להיות העבודה לפני מ\"ת הוא רק בדרך הכנה בלבד<sup data-n=\"2060\">39</sup>. ובדוגמת המבואר בכ\"מ<sup data-n=\"2061\">40</sup> בענין ההפרש שבין האתעדל\"ע שלפי ערך האתעדל\"ת להאתעדל\"ע הבאה בדרך מתנה שאין אתעדל\"ת מגעת לשם כלל, דהגם שגם האתעדל\"ע שבדרך מתנה נמשכת דוקא אחרי קדימת האתעדל\"ת (והאתעדל\"ע שלפ\"ע האתעדל\"ת), מ\"מ אין זה שהאתעדל\"ת ממשיכה אותה, כי המשכת אתעדל\"ע זו היא מבחי' שאין אתעדל\"ת מגעת לשם, ומה שנמשכת אחרי קדימת האתעדל\"ת (והאתעדל\"ע שלפ\"ע האתעדל\"ת) הוא לפי דקוב\"ה לא שריא אלא באתר שלים<sup data-n=\"2062\">41</sup>. שעד\"ז הוא גם בנוגע להעבודה במשך הז' שבועות לפני מ\"ת שהעבודה לא היתה כלי להגילוי דמ\"ת (ואין שייך לומר שהעבודה המשיכה את הגילוי דמ\"ת), ורק בדרך הכנה בלבד, שע\"י עבודתם נעשו מעין כלי (אבל לא כלי ממש) להגילוי דמ\"ת. וזה גופא (מה שהיו מעין כלי להגילוי דמ\"ת) הוא מצד שרשם ומקורם, מצד האבות והאמהות עד לאחד הי' אברהם<sup data-n=\"2063\">42</sup>, שלכן יש (קס\"ד) בכתבי האריז\"ל<sup data-n=\"2064\">43</sup> שענין מ\"ת הותחל בימי האבות. דכ\"ז הי' בלוחות הראשונות. משא\"כ נתינת לוחות האחרונות היתה ע\"י אתעדל\"ת. דעבודת התשובה דבנ\"י (על חטא העגל) היתה אתעדל\"ת שעוררה והמשיכה הגילוי דלוחות האחרונות. וזהו מה שנתינת לוחות האחרונות היתה בחודש תשרי, כי עניני חודש תשרי באים ע\"י העבודה דאלול שהיא כלי ואתעדל\"ת שמעוררת וממשכת את הענינים דתשרי. ולכן עי\"ז נעשה זיכוך ועלי' גם בהמטה מצד עצמו (דלא כבלוחות הראשונות). וזהו דלוחות הראשונות ולוחות האחרונות בעבודת האדם הם עבודת הצדיקים ועבודת התשובה, כי עבודת הצדיקים (כולל גם המשכה שע\"י העבודה) היא בבחי' אור ישר, מלמעלה למטה, משא\"כ ע\"י עבודת התשובה נפעל ענין חדש, שגם המטה גופא מזדכך ומתעלה.\nד) <b>והענין</b> הוא, דעבודת הצדיקים היא כשהאדם הוא באופן דהאלקים עשה את האדם ישר<sup data-n=\"2065\">44</sup>, דכל אחד מישראל באיזה מצב שהוא רוצה הוא בטבעו למלאות רצון קונו (כפס\"ד הידוע<sup data-n=\"2066\">45</sup>) בלימוד התורה ובקיום המצוות ובעבודת התפלה, ולכן ע\"י עבודת הצדיקים לא נעשה התחדשות אמיתית, מכיון שהעבודה היא כטבע תולדותם. וכמו שעבודת הצדיקים אינה חידוש אמיתי בהאדם מכיון שהעבודה היא כטבע תולדתו, עד\"ז הוא גם בנוגע להענינים שלמעלה, מכיון שכוונת הבריאה (מלכתחלה) היא בכדי להטיב לברואיו כו'<sup data-n=\"2067\">46</sup> (ע\"י עבודתם בתומ\"צ) מצדטבע<sup data-n=\"2068\">47</sup> הטוב להטיב<sup data-n=\"2069\">48</sup>. וכן הוא גם למעלה יותר בבחי' שרש הנשמות כמו שמושרשים בעצמותו ית', כתורת הרב המגיד<sup data-n=\"2070\">49</sup> בענין במי<sup data-n=\"2071\">50</sup> נמלך בנשמותיהן של צדיקים<sup data-n=\"2072\">51</sup>, די\"ל שענין זה הוא בעצמותו ית' (למעלה מבחי' טבע הטוב להטיב), דמכיון שגם בתחלה כבר עלה לפניו ית' התענוג שיתענג בעבודת הצדיקים<sup data-n=\"2073\">52</sup>, הרי ע\"י עבודת הצדיקים (בפועל) אין זה התחדשות אמיתית.\n<b>דכ\"ז</b> הוא בנוגע לעבודת הצדיקים, וכדיוק לשון רז\"ל במי נמלך בנשמותיהן של צדיקים. אמנם הכוונה האמיתית (שלמעלה גם מבחי' במי נמלך) היא כמ\"ש<sup data-n=\"2074\">53</sup> אשר ברא אלקים לעשות, לעשות לתקן<sup data-n=\"2075\">54</sup>, שהאדם ע\"י עבודתו יעשה חידוש בהבריאה, שיהי' (לא רק אלה תולדות השמים והארץ בהבראם<sup data-n=\"2076\">55</sup>, תולדות מלא<sup data-n=\"2077\">56</sup>, עולם על מילואו נברא<sup data-n=\"2078\">57</sup>, אלא גם) אלה תולדות פרץ<sup data-n=\"2079\">58</sup>, תולדות מלא<sup data-n=\"2077\">56</sup>, למעלה מאלה תולדות השמים והארץ, פרץ זה משיח שנאמר בו<sup data-n=\"2080\">59</sup> עלה הפורץ לפניהם<sup data-n=\"2081\">60</sup>, שאז יהי' העולם למעלה מכמו שהי' בתחלת הבריאה דעולם על מילואו נברא (כ\"א שמים חדשים וארץ חדשה<sup data-n=\"2082\">61</sup>). וכן הוא גם בנוגע לנשמות ישראל<sup data-n=\"2083\">62</sup> שהנשמות דלע\"ל יהיו גבוהות יותר גם מאדה\"ר כמו שהי' קודם החטא, וכמבואר בלקו\"ת בסיומו וחותמו<sup data-n=\"2084\">63</sup> בענין נשמות החדשות שיהיו לע\"ל שהם יותר גבוהות מכל הנשמות שנכללו באדה\"ר. דחידוש זה נעשה ע\"י עבודת התשובה דוקא, דזהו מה שמשיח (דוקא) אתא לאתבא צדיקייא בתיובתא<sup data-n=\"2085\">64</sup>. ועי\"ז נשלמה הכוונה האמיתית, שלמעלה מענין במי נמלך בנשמותיהן של צדיקים.ה) <b>ועד\"ז</b> הוא גם בתשובה כפשוטה, דכאשר האדם חטא ופגם והעביר את הדרך (שזהו היפך טבע האדם וטבע דלמעלה) ואח\"כ מתקן זה ע\"י התשובה, ובפרט כשהתשובה היא באופן דזדונות נעשו לו כזכיות<sup data-n=\"2086\">65</sup>, הנה עי\"ז נעשה ענין חדש שלמעלה מטבע האדם ומהטבע שלמעלה (דטבע הטוב להטיב), וגם למעלה משרש הנשמות כמו שהן בבחי' במי נמלך. והענין הוא, כי עבודת התשובה היא בדרך דילוג<sup data-n=\"2087\">66</sup> מה שהאדם משתנה ונהפך (שלא בסדר והדרגה) ונעשה מציאות חדשה<sup data-n=\"2088\">67</sup>. דזהו מה שתשובה היא למעלה מהזמן שלכן גם כמו שהיא נמשכת בבחי' הזמן היא בשעתא חדא וברגעא חדא<sup data-n=\"2089\">68</sup>, לפי<sup data-n=\"2090\">69</sup> שעבודת התשובה היא שלא בהדרגה. וזהו גם מה שבבע\"ת נאמר והי' טרם יקראו ואני אענה<sup data-n=\"2091\">70</sup>, דענין זה (מענה טרם הקריאה) הוא היפך הטבע וההשתלשלות, כי ע\"י הדילוג (דתשובה) שלא בסדר ההשתלשלות שבאדם, עי\"ז נעשה גם למעלה שלא בסדר ההשתלשלות, וע\"ד מ\"ש<sup data-n=\"2092\">71</sup> ממעמקים קראתיך הוי', ממעמקים (לשון רבים) הוא מעומק לעומק<sup data-n=\"2093\">72</sup>, דע\"י עבודת התשובה מעומק פנימיות נקודת הלב, עי\"ז הוא קורא וממשיך מבחי' עומק ופנימיות א\"ס ב\"ה<sup data-n=\"2094\">73</sup> [ועד שענין התשובה מגיע בעצמותו ית', כידוע בענין שאלו להקב\"ה כו' אמר יעשה תשובה ויתכפר לו<sup data-n=\"2095\">74</sup>]. וע\"י המשכה זו, זדונות נעשו לו כזכיות<sup data-n=\"2094\">73</sup>. דכמו שע\"י התשובה נעשה ענין חדש באדם שנעשה מציאות חדשה כנ\"ל, כמו\"כ נעשה עי\"ז ענין חדש בעולם<sup data-n=\"2096\">75</sup> שזדונות נהפכים לזכיות. וזכיות אלו (שמהפכים מהזדונות), מכיון שנעשים ע\"י הדילוג דתשובה, הם נעלים יותר<sup data-n=\"2097\">76</sup> מהזכיות דצדיקים.ו) <b>וזהו</b> מה שבלוחות האחרונות (שבעבודת האדם הו\"ע עבודת התשובה כנ\"ל) כתיב כפלים לתושי', שהכוונה בכפלים היא לא רק כפלים במספר<sup data-n=\"2098\">77</sup> כי אם לריבוי גדול יותר ועד באין ערוך [כמובן גם מזה שבלוחות האחרונות נתוספו ריבוי ענינים, הלכות מדרש ואגדות<sup data-n=\"2099\">78</sup>], כי נוסף על זה שבבע\"ת יש ב' סוגי זכיות (כפלים במספר) הזכיות דתומ\"צ (כמו בצדיקים) והזכיות שנעשו מהפיכת הזדונות, הרי הזכיות שנעשו מהפיכת הזדונות הם נעלים יותר ועד באין ערוך מזכיות הצדיקים. ויתירה מזו, שגם התומ\"צ שלאחרי התשובה הם נעלים יותר, בחילא יתיר<sup data-n=\"2100\">79</sup>. וזהו גם מהביאורים בזה שגאולה העתידה היא ע\"י הקדמת עבודת התשובה דוקא<sup data-n=\"2101\">80</sup>, כי גם השגת התורה דלע\"ל תהי' כפלים לתושי'. ולא רק כפלים במספר, ההשגה בכל מה שלמדו עכשיו בנגלה דתורה ובפנימיות התורה (ותלמודו בידו<sup data-n=\"2102\">81</sup>) וההשגה בתורתו של משיח, אלא גם לריבוי ביותר ועד לאין ערוך, שהרי בביאת המשיח יהי' ישקני מנשיקות פיהו<sup data-n=\"2103\">82</sup> שיתגלה סוד טעמי' ומסתר צפונותי'<sup data-n=\"2104\">83</sup> (תעלומות חכמה). ויתירה מזו, שעי\"ז גם השגת הנגלה דתורה תהי' באופן נעלה יותר. ועד\"ז ע\"י העבודה דתומ\"צ בזמן הגלות, דכללות העבודה שבזמן הגלות (גם העבודה דתומ\"צ) היא עבודת התשובה וע\"י התשובה כפלים לתושי'.\nז) <b>ויובן</b> זה על פי הידוע<sup data-n=\"2105\">84</sup> שהחילוק בין תלמוד בבלי לתלמוד ירושלמי הוא בדוגמת החילוק בין לוחות הראשונות ללוחות האחרונות. דתלמוד<sup data-n=\"2106\">85</sup> ירושלמי הוא בדרך אור ישר (דוגמת עבודת הצדיקים, לוחות הראשונות), ותלמוד בבלי הוא הפלפול בריבוי קושיות והעלמות, במחשכים הושיבני<sup data-n=\"2107\">86</sup> זה תלמוד בבלי<sup data-n=\"2108\">87</sup>, ואעפ\"כ הלכה כבבלי דוקא<sup data-n=\"2109\">88</sup>, כי ע\"י היגיעה בבירור הקושיות וכו' מגיעים לאמיתית הכוונה, לבחי' העלם העצמי שבתורה, בחי' תעלומות חכמה (דוגמת מעלת הזכיות דבע\"ת שנעשים מהזדונות, על הזכיות דצדיקים). וזהו מה שבלוחות האחרונות דוקא כתיב ויגד לך תעלומות חכמה כי כפלים לתושי', תעלומות חכמה הוא (עד ל)פנימיות ח\"ס, ובשרשה היא פנימיות ועצמות א\"ס<sup data-n=\"2110\">89</sup>, וזה מתגלה ע\"י הפלפול וכו' דתלמודבבלי דוקא. וגילוי זה יהי' בעיקר לע\"ל, וכדאיתא בזהר<sup data-n=\"2111\">90</sup> עה\"פ<sup data-n=\"2112\">91</sup> עין לא ראתה גו' יעשה למחכה לו מאי למחכה לו כו' אינון דדחקין למלה דחוכמתא ודייקין לי' ומחכאן לי' למנדע ברירא דמלה כו', שע\"י ריבוי העיון והיגיעה בריבוי קושיות וכו', יהי' (לע\"ל) הגילוי דבחי' עדן שעליו נאמר עין לא ראתה<sup data-n=\"2113\">92</sup>, בחי' העלם העצמי. ועי\"ז נעשה עילוי ושלימות גם בהתורה שהיא מתקשרת עם העצמות (בדוגמת דוד הי' מחבר תורה שלמעלה בהקב\"ה<sup data-n=\"2114\">93</sup>), דהתורה מצ\"ע (כמו שניתנה במ\"ת, בלוחות הראשונות) היא בחי' חכמה, דאורייתא מחכמה נפקת<sup data-n=\"2115\">94</sup>, והגם שבמ\"ת ניתנה גם התורה שתתגלה לע\"ל (שהרי מ\"ת הי' רק פעם אחת)<sup data-n=\"2116\">95</sup>, הנה בעת מ\"ת ניתן זה בבחי' העלם, <i>תעלומות</i> חכמה, ובכדי להמשיך זה בגילוי (באופן דתורה <i>אור</i><sup data-n=\"2117\">96</sup>), הנה כח זה ניתן בלוחות האחרונות דוקא. וזהו מה שע\"י עסק התורה בזמן הגלות דוקא (תלמוד בבלי) יהי' הגילוי דלע\"ל שאז תושלם הכוונה דדירה<sup data-n=\"2118\">97</sup> בתחתונים, כי בדירה בתחתונים ב' ענינים, דירה לו לעצמותו<sup data-n=\"2119\">98</sup> ודירה בתחתונים, וב' ענינים אלו נעשים<sup data-n=\"2120\">99</sup> ע\"י העסק והיגיעה בתלמוד בבלי דוקא. דע\"י היגיעה בבירור הקושיות מגיעים לבחי' העלם העצמי כנ\"ל, לו לעצמותו, ועי\"ז מגיעים גם לאמיתית הכוונה לפסוק הלכה למעשה כנ\"ל, וע\"י העשי' בפועל (כפי פסק ההלכה) נעשה דירה לו ית' בתחתונים. וזהו במחשכים הושיבני (זה תלמוד בבלי), דע\"י במחשכים (היגיעה בריבוי הקושיות וכו') נעשה הושיבני, דירה לו ית' בתחתונים.\nח) <b>ועד\"ז</b> הוא בקיום המצוות בזמן הגלות דוקא, דהגם שהמצוות בזמן הגלות אינם בתכלית השלימות [דנוסף לזה שעיקר השלימות דמעשה המצוות יהי' בימות המשיח כמ\"ש ושם (דוקא) נעשה לפניך כו' כמצות רצונך, דשלימות זו לא היתה גם בזמן הבית<sup data-n=\"2121\">100</sup>, הנה בהמצוות דזמן הגלות לא יש גם השלימות שהיתה בזמן הבית<sup data-n=\"2122\">101</sup>], מ\"מ ע\"י ההתבוננות בזה גופא שבזמן הגלות חסר השלימות, עי\"ז עשיית המצוות היא בחילא יתיר. וע\"ד המבואר בתניא<sup data-n=\"2123\">102</sup> בענין מעלת הבע\"ת על צדיקים, שעי\"ז שהי' מרוחק מאלקות לכן הצמאון שלו הוא ביתר עז, באהבה רבה מעומקא דלבא. ועי\"ז גופא (מה שעשיית המצוות בזמן הגלות היא בחילא יתיר)מבררים את חושך הגלות ומהפכים אותו לקדושה, ע\"ד המבואר בתניא&lt;102&gt;, שע\"י התשובה מאהבה רבה והצמאון מתהפכים הזדונות לזכיות (שבתחלה נעשים זדונות כזכיות בכ\"ף הדמיון, ועד שנעשה זכיות ממש). וזהו מה שתכלית השלימות דלע\"ל נעשה (בעיקר) ע\"י קיום המצוות שבזמן הגלות דוקא<sup data-n=\"2124\">103</sup>, ובפרט ע\"י עבודת התשובה, כי ב' הענינים שבדירה בתחתונים (שזהו השלימות דלע\"ל), דירה לו לעצמותו ודירה בתחתונים, נעשים (בעיקר) ע\"י קיום המצוות שבזמן הגלות דוקא, ובפרט ע\"י עבודת התשובה. דע\"י הצמאון והחילא יתיר שבזמן הגלות, ובפרט ע\"י הצעקה דתשובה מעומקא דלבא, ממשיכים מבחי' עומק ופנימיות דלמעלה, לו לעצמותו, וע\"י בירור והפיכת חושך הגלות, ובפרט הפיכת הזדונות לזכיות (ע\"י התשובה), מבררים ומזככים גם ענינים הכי תחתונים ונעשים דירה לו ית'.\nט) <b>וזהו</b> מה שתכלית השלימות דעולם יהי' לע\"ל דוקא, אלה תולדות פרץ, דשלימות זו היא למעלה יותר מהשלימות שהיתה בתחלת הבריאה עולם על מילואו נברא, ולמעלה יותר גם מהשלימות דעולם שהיתה במ\"ת, הגם שגם במ\"ת האָט די וועלט אויסגעשריען אנכי, לא יהי' לך (שהם כללות כל התורה כולה<sup data-n=\"2125\">104</sup>), כי במ\"ת הי' זה בעיקר מצד הגילוי שמלמעלה (שהדברות אנכי ולא יהי' לך הם היו יוצאים ונשמעים מכל ו\"ק העולם), כנ\"ל, משא\"כ לע\"ל יהי' זה בהעולם מצ\"ע<sup data-n=\"2126\">105</sup>, כמרז\"ל<sup data-n=\"2127\">106</sup> לע\"ל אם אדם הולך ללקט תאנה בשבת היא צווחת ואומרת שבת היום כו' האבן זועקת ואומרת כו' (שזה יהי' מצד התאנה והאבן). ויתירה מזו, שע\"י מעשינו ועבודתנו בזמן הגלות בעסק התורה ובקיום המצוות שעי\"ז מבררים גם את חושך הגלות, ובפרט ע\"י תשובה דזדונות נעשו לו כזכיות, עי\"ז יהי' זיכוך העולם לע\"ל גם בענינים הכי תחתונים, ועד שגם החושך יהפך לאור. וזהו אלה תולדות פרץ זה משיח שנאמר בו עלה הפורץ לפניהם, שיפרוץ כל הגדרים, היינו שגם הגדרים (מצד הקדושה<sup data-n=\"2128\">107</sup>) יופרצו.\nיו\"ד) <b>והנה</b> מכיון שבעבודת האדם צריך להיות סדר, לכן, גם עבודת התשובה, עם היותה למעלה מסדר והדרגה, יש לה זמן מיוחד, בהארבעים יום שבין ראש חודש אלול ליום הכפורים, שהם הד' יודי\"ן דס\"ת אני לדודי ודודי לי<sup data-n=\"2129\">108</sup>. דעבודת התשובה היא מלמטה למעלה, בתחלה אני לדודי ואח\"כ ודודי לי. והגם שיו\"ד ימים האחרונים דמ' ימים אלו (עשרה ימים שבין ראש השנה ליום הכפורים) הם בדרך המשכה וגילוי מלמעלה למטה כמרז\"ל<sup data-n=\"2130\">109</sup> עה\"פ<sup data-n=\"2131\">110</sup> דרשו הוי' בהמצאוקראוהו בהיותו קרוב אלו עשרה ימים שבין ראש השנה ליום הכפורים (דבהמצאו ובהיותו קרוב הוא גילוי מלמעלה למטה), וכידוע<sup data-n=\"2132\">111</sup> שבימים אלו הוא קירוב המאור אל הניצוץ, מ\"מ שייכים גם ימים אלו לעבודת התשובה שמצד המטה, כי ההמשכה והגילוי מלמעלה שבימים אלו נעשית ע\"י העבודה והאתעדל\"ת שבחודש אלול, שע\"י העבודה בג' יודי\"ן הראשונים (אני לדודי ודודי) נעשה היו\"ד דתיבת לי, קירוב המאור אל הניצוץ. ובעשרה ימים אלו יש כו\"כ עליות, עד לתכלית העלי' דיום הכפורים, וביום הכפורים עצמו תכלית העלי' הוא בתפלת נעילה (בסיומו וחותמו של היום), וי\"ל דבנעילה גופא – באמירת שמע ישראל (שהוא בסיומה וחותמה), וכדאיתא בשל\"ה שצריך לכוין אז למסור נפשו על קידוש השם ונחשב לו הכוונה כאילו עשה בפועל [ואולי י\"ל שהוא ע\"ד מאמר הבעש\"ט<sup data-n=\"2133\">112</sup> במקום שמחשבתו של אדם שם הוא נמצא]. דכל זה הוא עליות מלמטה למעלה. ולאח\"ז מתחיל ענין ההמשכה מלמעלה למטה (שעי\"ז נשלמת הכוונה דלשבת יצרה<sup data-n=\"2134\">113</sup>), דתחלת ההמשכה היא בד' הימים שבין יום הכפורים לסוכות שאז כל ישראל עסוקין במצוות זה עוסק בסוכתו וזה בלולבו<sup data-n=\"2135\">114</sup>, ולאח\"ז בימי הסוכות עצמם ע\"י קיום מצות ישיבה בסוכה ונטילת ד' מינים בפועל, דע\"י קיום מצות סוכה ההמשכה היא בבחי' מקיף, וע\"י נטילת ד' מינים נמשך בפנימיות ולקחתם לכם<sup data-n=\"2136\">115</sup>. וצ\"ל כ\"ז בבחי' קליטה, שזה (הקליטה) נעשה בשמיני עצרת, עצרת מלשון קליטה. [דזהו גם מ\"ש<sup data-n=\"2137\">116</sup> תקעו בחודש שופר בכסה ליום חגינו, וידוע הפירוש בזה, דמה שבראש השנה ויום הכפורים הוא באופן דבכסה (מכוסה ונעלם) מתגלה ליום חגינו בחג הסוכות<sup data-n=\"2138\">117</sup>, ואעפ\"כ נאמר ליום חגינו לשון יחיד (ולא לימי חגינו לשון רבים), כי עיקר הגילוי (של הענינים דראש השנה ויום הכפורים) באופן דקליטה הוא בשמיני עצרת, ליום חגינו לשון יחיד<sup data-n=\"2139\">118</sup>]. וכידוע שבשמיני עצרת הוא הזיווג<sup data-n=\"2140\">119</sup>, ועד לאופן דוהיו לבשר אחד<sup data-n=\"2141\">120</sup>, שמזה נעשה ההולדה דתומ\"צ (תולדותיהן של צדיקים מעשים טובים<sup data-n=\"2142\">121</sup>) במשך כל השנה, לעשות לו ית' דירה בתחתונים. וזהו ג\"כ שעצרת הוא מלשון מלוכה (כמו זה<sup data-n=\"2143\">122</sup> יעצור בעמי)<sup data-n=\"2144\">123</sup>, דבשמיניעצרת ווערט אַ איד אַ מלך און אַ בעה\"ב על כל סדר ההשתלשלות, לעשות ממנו דירה לו ית'.\nיא) <b>וזהו</b> ביום השמיני עצרת תהי' לכם, דזה שנקרא בשם <i>שמיני</i> עצרת שמורה ע\"ז שבא בהמשך לז' ימי הסוכות דוקא, אף שבשמיני עצרת נעצרים ונקלטים גם הענינים דראש השנה ויום הכפורים, כי בראש השנה ויום הכפורים הוא ענין העלי' מלמטה למעלה, ומכיון שהכוונה היא לשבת יצרה, המשכה מלמעלה למטה, לכן נקרא בשם שמיני עצרת, שבו נעצרים ונקלטים כל הענינים שנמשכו מלמעלה למטה בז' ימי הסוכות, שלכן נקרא בשם שמיני דוקא [נוסף לזה ששמיני הוא מלשון שומן ודשן<sup data-n=\"2145\">124</sup>]. אלא שאעפ\"כ שמיני עצרת הוא רגל בפ\"ע, כי עי\"ז גופא מה שבשמיני עצרת נעצרים ונקלטים הענינים דז' ימי הסוכות, נעשה בו ענין חדש, רגל בפ\"ע. כי בז' ימי הסוכות נמשכים (בבחי' מקיף) הענינים דראש השנה ויום הכפורים ודכללות עשי\"ת עד לשלימות התשובה דיום הכפורים, וע\"י המשכת ענין זה בפנימיות ובקליטה בשמיני עצרת, ליום חגינו לשון יחיד, מתגלה (ובאופן דקליטה) ההתקשרות והתאחדות דבחי' יחידה שבנפש עם בחי' יחיד, שלשם מגיע ענין התשובה, פר אחד איל אחד<sup data-n=\"2146\">125</sup>. וזהו ג\"כ עצרת תהי' לכם ואיתא במדרש הה\"ד יהיו לך לבדך ואין לזרים אתך, דזה שצריך לשלול ולומר אין לזרים אתך הוא לפי שבע\"ת שסורו רע צריך לזהירות יתירה<sup data-n=\"2147\">126</sup>, ולכן צריך לשלול הענין דזרים (ענינים הבלתי רצויים). אבל עי\"ז גופא (הזהירות יתירה דהבע\"ת) נעשה יהיו לך לבדך, כי עי\"ז שהתשובה מגעת בעצמותו ית', הרי לא שייך שם שום נתינת מקום לזרים, ישראל ומלכא בלחודוהי. ואדרבה, מצד המשכת העצמות (ע\"י עבודת התשובה) מתגלה פנימית ואמיתית הכוונה דעשיית הענינים הבלתי רצויים, שזה הי' בכוונה תחלה (כידוע<sup data-n=\"2148\">127</sup> בענין נורא עלילה על בני אדם<sup data-n=\"2149\">128</sup>) בכדי שיהי' אתהפכא חשוכא לנהורא, הפיכת הזדונות לזכיות.\nיב) <b>וזהו</b> ג\"כ מה שקבעו שמחת תורה בשמיני עצרת על לוחות האחרונות דוקא [שהגלוי דלוחות האחרונות (ענין התשובה דיום הכפורים) בפנימיות ובקליטה הוא בשמיני עצרת, כנ\"ל], כי השמחה דשמחת תורה היא (בעיקר) מצד זה שהתורה פועלת גם בענינים התחתונים שבעולם, דזהו מה שהשמחה דשמחת תורה היא בריקודים ברגלים ובהם גופא בהעקב שבהם, ולכן השמחה היא על לוחות האחרונות דוקא, ענין התשובה, כי עי\"ז מתברר גם הכי תחתון שבעולם, עד שגם הזדונות נהפכים לזכיות. וכמו שבריקוד (בגשמיות), ע\"י שהרגלים והעקביים מתנשאים(הויבן זיך) ומרקדים, הם מנשאים גם את הראש (וכח השכל שבו) שגם הוא מרקד בשמחה גדולה למעלה ממדידה והגבלה, עד\"ז הוא גם ברוחניות הענינים, שע\"י השמחה והריקודים דשמחת תורה נעשה עלי' והתנשאות גם בבחי' הראש דנשמה. ומכיון שאדם הוא אדמה לעליון<sup data-n=\"2150\">129</sup> הנה עי\"ז נעשה עלי' והתנשאות כביכול גם בחכמתו ית' שהיא התורה [וכמובן גם מזה שבהריקודים דהקפות גם התורה היא שמחה ורוקדת, כמאמר הידוע דרבינו נשיאינו], ושמחה פורצת גדר<sup data-n=\"2151\">130</sup>, שהשמחה דשמחת תורה פורצת גם הגדר דתורה כביכול, דהתורה מצ\"ע היא במדידה והגבלה וע\"י השמחה והריקודים דשמחת תורה ממשיכים בה מעצמותו ית', וכנ\"ל ע\"ד מרז\"ל דוד הי' מחבר תורה שלמעלה בהקב\"ה. וכמו שהוא בתורה עד\"ז הוא בנשמות ישראל, שע\"י השמחה והריקודים דשמחת תורה נעשה עלי' והתנשאות בבחי' הראש דנשמה (כנ\"ל), שמתקשרת ונעשית חד ממש עם העצמות, שאו את ראש גו' לגולגלותם<sup data-n=\"2152\">131</sup>, שעיקר ענין זה יהי' במנין העשירי עוד תעבורנה הצאן ע\"י מונה<sup data-n=\"2153\">132</sup>. וכל זה נעשה (כנ\"ל) ע\"י מעשינו ועבודתנו בזמן הגלות, ובמיוחד לאחר גילוי תורת הרשב\"י ובאופן דיתפרנסון<sup data-n=\"2154\">133</sup> ע\"י תורת הבעש\"ט וע\"י תורת חסידות חב\"ד, ויפקון בי' מן גלותא ברחמי<sup data-n=\"2155\">134</sup>, ושמחת עולם על ראשם<sup data-n=\"2156\">135</sup>, בגאולה האמיתית והשלימה בקרוב ממש בביאת משיח צדקנו, דוד מלכא משיחא.\n**********",[["2021","*","יצא לאור ב<b>קונטרס שמע\"צ ושמח\"ת – תשמ\"ז</b>, \"לקראת שמע\"צ ושמח\"ת . . <i>ערחה\"ס</i>,<i> ה' </i><b>ת</b><i>הא </i><b>ז</b><i>ו </i><b>ש</b><i>נת </i><b>מ</b><i>שיח</i>\"."],["2022","1","פינחס כט, לה."],["2023","2","סוכה מח, רע\"א. וש\"נ."],["2024","3","פינחס שם, א, ז, יב."],["2025","4","רד\"ה זה תער\"ג (המשך תער\"ב ח\"א ע' קנח), תרע\"ה (המשך הנ\"ל ח\"ב ע' תרפח), תרפ\"ו (ע' נה), תרצ\"ד (תשי\"א) (ע' 80)."],["2026","5","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381050\" data-slug=\"likkutei-torah\" data-id=\"4001381050\">אוה\"ת סוכות ס\"ע א</a>'תשסב ואילך. ס\"ע א'תשסו ואילך. וראה גם לקו\"ת סוכות פא, ג. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091229\" data-slug=\"likkutei-sichot\" data-id=\"1300091229\">לקו\"ש ח\"ט ע' 229</a> ובהערות שם."],["2027","6","רד\"ה זה תרנ\"ט (ע' מג). סד\"ה זה תרס\"ה (ע' מז), תרס\"ו (המשך תרס\"ו ע' שעט), תרפ\"ו (ע' סח), תש\"ו (ע' 46), תש\"ז הב' (ע' 181). ועוד."],["2028","7","שעהיוה\"א בתחלתו."],["2029","8","שמו\"ר פט\"ו, כג. וראה ריש וסוף ד\"ה הנ\"ל עת\"ר (ע' לה. מד), תש\"ד (ע' 43. 47), תש\"ט (ע' 69. 73), תש\"י (ע' 71. 82). ועוד."],["2030","9","משלי ה, יז."],["2031","10","ראה זח\"ג לב, א. וראה זח\"א רח, ב. הובא ונת' בריש וסוף ד\"ה זה באוה\"ת שמע\"צ (כרך ה) ע' ב'קמט. שם ע' ב'קנג. תרפ\"ז (ע' לו. נא)."],["2032","11","עקב יא, יב."],["2033","12","אוה\"ת שמיני עצרת ע' א'תשעט ואילך. המשך וככה תרל\"ז פרק פד. רד\"ה הנ\"ל תרס\"ז (המשך תרס\"ו ע' שע), תער\"ב (סה\"מ תער\"ב-תרע\"ו ע' כז), עזר\"ת (הא' – ס\"ע ל), תרפ\"ז (ע' לו), תרצ\"ט (ס\"ע 60), תש\"ו (ע' 34). ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141168\" data-slug=\"likkutei-sichot\" data-id=\"1300141168\">לקו\"ש חי\"ד ע' 156</a> ואילך."],["2034","13","רד\"ה הנ\"ל תרנ\"ט (ע' מג). מקומות שבהערה הקודמת."],["2035","14","ראה תענית כו, ב במשנה ובפרש\"י שם. גמרא שם ל, ב."],["2036","15","שבת קמו, א. ובכ\"מ."],["2037","16","יתרו יט, כ."],["2038","17","וגם בהדומם שבעולם (לא רק בצפור וכו'), דזהו מה שהקול דעשרת הדברות לא הי' לו בת-קול (שמו\"ר ספכ\"ח), מפני שנקלט גם בהדומם שבעולם (ראה בארוכה לקו\"ש ח\"ד שיחה לפ' ואתחנן). ויתירה מזו, שהעולם גופא (גם הדומם שבו) \"האָט אויסגעשריען כו'\", כדלקמן בפנים."],["2039","18","שמו\"ר ספכ\"ט."],["2040","19","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תקו\"ז תכ\"ב (סד, ב</a>), הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a> – מו, א. וראה תנחומא שמות כה. שמו\"ר פ\"ה, ט."],["2041","20","יתרו כ, ב-ג."],["2042","21","ד\"ה הנ\"ל תרנ\"ט, עזר\"ת, תרפ\"ז, תרצ\"ט, תש\"ו."],["2043","22","איוב יא, ו. וראה שמו\"ר רפמ\"ו."],["2044","23","ראה סד\"ה הנ\"ל תרצ\"ד (תשי\"א)."],["2045","24","ראה אדר\"נ ספל\"א."],["2046","25","פרע\"ח שער הלולב פ\"א. שעה\"פ להאריז\"ל עה\"פ וישלח לב, כט. ספר הליקוטים להאריז\"ל עה\"פ ויחי מז, כח. מח, ב. ערכי הכינויים [לבעל סדר הדורות] מערכת ראש. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380505\" data-slug=\"likkutei-torah\" data-id=\"4001380505\">לקו\"ת שלח מח, ב</a>. ובכ\"מ."],["2047","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101025\" data-slug=\"likkutei-sichot\" data-id=\"1300101025\">לקו\"ש ח\"י ע' 25</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201139\" data-slug=\"likkutei-sichot\" data-id=\"1300201139\">ח\"כ ע' 139</a> ואילך."],["2048","27","המשך וככה תרל\"ז פפ\"ד. ד\"ה הנ\"ל עזר\"ת (ע' לה). רד\"ה הנ\"ל תרנ\"ט, עזר\"ת (ע' לה), תש\"ו. וראה גם אוה\"ת שם ס\"ע א'תשפ."],["2049","28","מו\"ק ט, א."],["2050","29","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141178\" data-slug=\"likkutei-sichot\" data-id=\"1300141178\">לקו\"ש חי\"ד ע' 166</a> ואילך."],["2051","30","סוכה נא, סע\"א במשנה."],["2052","31","ראה בארוכה אוה\"ת שם ס\"ע א'תשעט ואילך. מקומות שבהערה 21."],["2053","32","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380829\" data-slug=\"likkutei-torah\" data-id=\"4001380829\">לקו\"ת ראה כח, ב</a>. המשך תרס\"ו ע' שנג. המשך תער\"ב ח\"ב ס\"ע תתקל ואילך."],["2054","33","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>. סה\"מ תרפ\"ז ע' קיז. סה\"מ קונטרסים ח\"ב שסז, א. ובכ\"מ."],["2055","34","ראה קונטרס העבודה פ\"ד (ע' 33). ובכ\"מ."],["2056","35","תולדות כו, ה."],["2057","36","ראה סה\"מ תש\"ח ס\"ע 253. התמים חוברת ו' ע' נב [רצג, ד]. אגרות-קודש לכ\"ק אדמו\"ר מוהריי\"צ ח\"ג ע' תקסח."],["2058","37","המשך תער\"ב שם."],["2059","38","שמו\"ר פי\"ב, ג. תנחומא וארא טו."],["2060","39","ואולי י\"ל – להסיר דבר המונע."],["2061","40","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381225\" data-slug=\"likkutei-torah\" data-id=\"4001381225\">לקו\"ת שה\"ש כד, א</a>-ב."],["2062","41","זח\"ג צ, ב."],["2063","42","יחזקאל לג, כד."],["2064","43","ל\"ת להאריז\"ל לך לך. וראה אוה\"ת חיי שרה קכו, א."],["2065","44","קהלת ז, כט."],["2066","45","רמב\"ם הל' גירושין ספ\"ב."],["2067","46","ע\"ח שער הכללים בתחלתו."],["2068","47","ד\"ה אתה אחד לאדהאמ\"צ (מאמרי אדהאמ\"צ קונטרסים ע' ה) – בשם הע\"ח (וראה בהערה שם). עמה\"מ שער שעשועי המלך רפ\"א. שעהיוה\"א פ\"ד (עט, א). שומר אמונים ויכוח ב' סי' יד. ולהעיר משו\"ת ח\"צ סי\"ח."],["2069","48","סה\"מ תש\"ח ע' 273."],["2070","49","או\"ת ב, ג (בהוצאת קה\"ת תש\"מ ואילך – ס\"ו). לקו\"א (הוצאת קה\"ת) בתחלתו."],["2071","50","ב\"ר פ\"ח, ז. רות רבה פ\"ב, ג."],["2072","51","ראה ד\"ה מים רבים תשל\"ח הערה 44 (לקמן ע' רמח)."],["2073","52","המשך ר\"ה תש\"ג פ\"ג (סה\"מ תש\"ג ריש ע' 9). ובכ\"מ. וראה או\"ת ולקו\"א (להה\"מ) בתחלתן."],["2074","53","בראשית ב, ג."],["2075","54","ראה ב\"ר פי\"א, ו ובפרש\"י שם."],["2076","55","בראשית שם, ד."],["2077","56","ב\"ר פי\"ב, ו."],["2078","57","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["2079","58","רות ד, יח."],["2080","59","מיכה ב, יג."],["2081","60","אגדת בראשית ספס\"ג. פרש\"י לב\"ר פפ\"ה, יד."],["2082","61","ישעי' סה, יז."],["2083","62","להעיר גם מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381011\" data-slug=\"likkutei-torah\" data-id=\"4001381011\">לקו\"ת האזינו עב, רע\"א</a> (בענין התשובה דוהרוח תשוב אל האלקים אשר נתנה), ד\"התשובה הוא להיות . . כמו קודם ירידתה <i>ויתר על כן</i>\", היינו דע\"י התשובה נעשה בהנשמה ענין חדש, שמתעלית גם יותר מכפי שהיתה בשרשה בבחי' האלקים אשר נתנה. ועיין ד\"ה מים רבים תשל\"ח סוף ס\"ד ואילך (לקמן ע' רמח ואילך)."],["2084","63","שה\"ש נ, א. נא, ג."],["2085","64","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">לקו\"ת שמע\"צ צב, ב</a>. שה\"ש נ, סע\"ב. ובכ\"מ. וראה זח\"ג קנג, ב."],["2086","65","יומא פו, ב."],["2087","66","לקו\"ת ש\"ש סה, א. וראה בארוכה ד\"ה שובה ישראל תשל\"ו ס\"ב ואילך (לעיל ע' פד ואילך)."],["2088","67","ובלשון הרמב\"ם הל' תשובה פ\"ב ה\"ד [ועד\"ז בסמ\"ג מ\"ע טז ובר\"ן ר\"ה טז, ב – הובאו בחדא\"ג מהרש\"א לר\"ה שם] \"אני אחר ואיני אותו האיש שעשה אותן המעשים\".\nואף שלכאורה הוא רק \"גילוי ההעלם\" מה שנתגלה רצונו האמיתי שהי' גם מקודם (כפס\"ד הנ\"ל דהרמב\"ם), ד\"גם בשעת החטא היתה (הנשמה) באמנה אתו ית'\" (תניא ספכ\"ד) – מ\"מ, מכיון שה\"העלם\" שהי' מקודם הוא העלם בתכלית, \"בבחי' גלות ממש\" (תניא שם), ובפרט שהעלם זה נעשה ע\"י ההנהגה <i>דהיפך</i> כוונת בריאתו (שהרי האלקים עשה את האדם ישר, כנ\"ל) – יש לומר, שמצד הגדרים דסדר ההשתלשלות [ולמעלה יותר, כולל גם הענין דבמי נמלך, שהכוונה שם היא נשמותיהן של <i>צדיקים</i>], הוא \"העלם\" כזה ש(מצד עצמו) אינו בא לגילוי, והגילוי שלו הו\"ע של <i>חידוש</i>* (שמצד כח העצמות)."],["2089","68","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201086\" data-slug=\"likkutei-sichot\" data-id=\"1300201086\">זח\"א קכט, סע\"א</a>. וראה לקו\"ש ח\"כ ע' 86 הערה 5."],["2090","69","ראה בארוכה ד\"ה שובה הנ\"ל שם."],["2091","70","ישעי' סה, כד. רמב\"ם הל' תשובה פ\"ז ה\"ז."],["2092","71","תהלים קל, א."],["2093","72","ד\"ה ביום השמיני עצרת תרפ\"ז (ע' לז). וראה זח\"ג ע, רע\"א."],["2094","73","ד\"ה הנ\"ל תרפ\"ז (שם) ותרצ\"ט (ע' 61)."],["2095","74","יל\"ש תהלים רמז תש\"ב. ועוד. וראה ד\"ה שובה ישראל תרכ\"ט (ע' שלח ואילך). ד\"ה טוב וישר תרס\"ד (ע' רעא ואילך). ד\"ה ביום השמיני עצרת תער\"ב (סה\"מ תער\"ב-תרע\"ו ע' לב). ועוד."],["2096","75","ולא עוד אלא שזהו חידוש גדול יותר גם מהחידוש באדם, כמובן מהמבואר לעיל הערה 67."],["2097","76","אוה\"ת שמע\"צ ע' א'תשפ. ד\"ה ביום השמיני עצרת תרפ\"ז ותרצ\"ט. וראה גם סהמ\"צ להצ\"צ קפו, סע\"א. ובכ\"מ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171186\" data-slug=\"likkutei-sichot\" data-id=\"1300171186\">לקו\"ש חי\"ז ע' 186</a> ואילך.\n*) <i>ויש לומר</i>,<i> שזהו חידוש גדול יותר גם מהחידוש דוהרוח תשוב (ראה לעיל הערה 62)</i>,<i> מכיון שכאן הי' ענין </i><b>דהיפך</b><i> כוונת הבריאה</i>."],["2098","77","ראה אגה\"ת ספ\"ט."],["2099","78","שמו\"ר רפמ\"ו."],["2100","79","ראה אגה\"ת ספ\"ח, מזח\"א קכט, ב."],["2101","80","סנהדרין צז, ב. רמב\"ם הל' תשובה פ\"ז ה\"ה."],["2102","81","פסחים נ, א. וש\"נ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241584\" data-slug=\"likkutei-sichot\" data-id=\"1300241584\">לקו\"ש חכ\"ד ס\"ע 570</a> הע' 91."],["2103","82","שה\"ש א, ב."],["2104","83","פרש\"י עה\"פ."],["2105","84","המשך תרס\"ו ע' צ. ד\"ה ביום השמיני עצרת עזר\"ת (הא'). ובכ\"מ."],["2106","85","בכל הבא לקמן ראה שערי אורה כב, ב ואילך. המשך תרס\"ו שם ואילך (וראה שם ע' תח. ס\"ע תכא ואילך). ועוד."],["2107","86","איכה ג, ו."],["2108","87","כן הובא בכ\"מ בדא\"ח. וכ\"ה בשל\"ה טז, ב. לו, א. וראה סנהדרין כד, א."],["2109","88","רי\"ף סוף מס' עירובין. וראה אנציקלופדי' תלמודית ערך הלכה ע' רנ ואילך."],["2110","89","ד\"ה ביום השמיני עצרת תרפ\"ז ותרצ\"ט. וראה גם ד\"ה זה עזר\"ת (הא')."],["2111","90","ח\"א קל, ב."],["2112","91","ישעי' סד, ג."],["2113","92","ברכות לד, ב."],["2114","93","ס' הבהיר סקצ\"ו. רע\"מ בזח\"ג רכב, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380502\" data-slug=\"likkutei-torah\" data-id=\"4001380502\">לקו\"ת שלח מז, רע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380516\" data-slug=\"likkutei-torah\" data-id=\"4001380516\">שם נא, סע\"א</a>. ובכ\"מ. וראה המשך תרס\"ו ע' שצ."],["2115","94","זח\"ב קכא, א."],["2116","95","המשך תרס\"ו ע' כג. תקמו. סה\"מ תרנ\"ו ע' שנו. המשך תער\"ב ח\"א ע' שסו. סה\"מ עטר\"ת ע' רצא. תרפ\"ה ע' קצט. תש\"ט ע' 51 (השני)."],["2117","96","משלי ו, כג."],["2118","97","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["2119","98","אוה\"ת בלק ע' תתקצז. המשך תרס\"ו ס\"ע ג. ע' תמה. ובכ\"מ."],["2120","99","ראה עד\"ז ד\"ה שובה ישראל ה'תש\"מ ס\"ח (לעיל ע' קט)."],["2121","100","המשך וככה תרל\"ז פי\"ז ואילך. וראה שם ספ\"כ."],["2122","101","ראה ספרי עקב יא, יז. רמב\"ן אחרי יח, כה."],["2123","102","פ\"ז (יב, א)."],["2124","103","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>. וראה ד\"ה שובה הנ\"ל ס\"ד (לעיל ע' קז)."],["2125","104","<a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא רפ\"כ</a>."],["2126","105","ראה במקומות שבהערה 32."],["2127","106","מדרש תהלים ספע\"ג. יל\"ש ירמי' רמז שטו בסופו."],["2128","107","וע\"ד פרזות תשב ירושלים (זכרי' ב, ח. וראה ד\"ה בראשית תרע\"ח ותרצ\"ט)."],["2129","108","אבודרהם סדר תפלת ר\"ה (בשם הדרשנים). ב\"ח או\"ח סתקפ\"א (ד\"ה והעבירו). ר\"ח שער התשובה פ\"ד (ד\"ה עוד יש – קטו, ב). אוה\"ת ראה ע' תשפא. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380975\" data-slug=\"likkutei-torah\" data-id=\"4001380975\">לקו\"ת ר\"ה סד, א</a>."],["2130","109","ר\"ה יח, א. וש\"נ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291218\" data-slug=\"likkutei-sichot\" data-id=\"1300291218\">לקו\"ש חכ\"ט ע' 203</a> ואילך."],["2131","110","ישעי' נה, ו."],["2132","111","דרך חיים יג, ריש ע\"ד. כא, סע\"ב. צא, א. קונטרס העבודה ספ\"ה (ע' 35). ד\"ה ביום השמיני עצרת תרפ\"ז (ס\"ע לז). וראה גם ד\"ה מן המיצר עזר\"ת (ע' ב)."],["2133","112","כתר שם טוב (הוצאת קה\"ת תשנ\"ט) בהוספות סמ\"ח. וש\"נ."],["2134","113","ישעי' מה, יח."],["2135","114","ויק\"ר פ\"ל, ז."],["2136","115","אמור כג, מ. סה\"מ תקס\"ח ע' תמח. סידור שער הלולב רסה, סע\"א ואילך."],["2137","116","תהלים פא, ד."],["2138","117","ראה סידור רלה, ב. ובכ\"מ. וראה גם לקו\"ת ר\"ה נד, ריש ע\"ד."],["2139","118","המשך תער\"ב ח\"א ע' קסה."],["2140","119","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381111\" data-slug=\"likkutei-torah\" data-id=\"4001381111\">אגה\"ק ס\"כ (קל, סע\"ב</a>). פע\"ח שער הלולב פ\"ח. סידור שער הלולב רסג, ב. וראה לקו\"ת שמע\"צ פח, ג. ברכה צו, א. אוה\"ת שמע\"צ ע' א'תשפו."],["2141","120","לשון הכתוב – בראשית ב, כד."],["2142","121","פרש\"י ר\"פ נח."],["2143","122","שמואל-א ט, יז."],["2144","123","אוה\"ת שם ע' א'תשעו. רד\"ה ביום השמיני עצרת תרס\"ה (ע' לח), תרס\"ו (המשך תרס\"ו ריש ע' שע), תרס\"ח (ע' לא), תרפ\"א (ע' קכו), תרצ\"ד (תשי\"א) (ע' 80). ועוד."],["2145","124","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080431\" data-slug=\"or-hatorah-hb\" data-id=\"8160080431\">אוה\"ת שם (ע' א'תתיז</a>); סד\"ה הנ\"ל עדר\"ת (המשך תער\"ב ח\"א ע' תלא) בשם הה\"מ – דשמיני הוא ל' שמן. ובסד\"ה הנ\"ל תרצ\"ד (תשי\"א) (ע' 87); רד\"ה זה תרצ\"ט (ע' 60), תש\"ב (ס\"ע 35), תש\"ג (ע' 53) הוא כבפנים."],["2146","125","פינחס כט, לו. וראה סוכה נה, ב."],["2147","126","לקו\"ת ואתחנן ט, ד. ד\"ה מים רבים תרל\"ו פ' רא (ע' רלד). ד\"ה ביום השמיני עצרת עזר\"ת (הא' – ס\"ע לג ואילך). ועוד."],["2148","127","תו\"ח תולדות יג, א ואילך. ובכ\"מ."],["2149","128","תהלים סו, ה. תנחומא וישב ד."],["2150","129","עש\"מ (לרמ\"ע מפאנו) מאמר אם כל חי סל\"ג (קצג, ב). של\"ה ג, א. כ, ב. שא, ב. ובכ\"מ. עבודת הקודש ח\"א פי\"ז ואילך."],["2151","130","ראה בארוכה ד\"ה שמח תשמח תרנ\"ז (סה\"מ תרנ\"ז ע' רכג ואילך)."],["2152","131","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380316\" data-slug=\"likkutei-torah\" data-id=\"4001380316\">במדבר א, ב</a>. וראה לקו\"ת במדבר ב, א."],["2153","132","ירמי' לג, יג. במדב\"ר פ\"ב, יא."],["2154","133","תקו\"ז ת\"ו בסופו. וראה הקדמת מ\"מ לזהר. כס\"מ לתקו\"ז שם."],["2155","134","זח\"ג קכד, ב (ברע\"מ)."],["2156","135","ישעי' לה, י. נא, יא."]]],[1500360032,"<h3>בס\"ד. יום שמחת תורה ה'תשמ\"א<sup data-n=\"2157\">*</sup></h3>\n<b>ביום</b> השמיני שלח את העם ויברכו את המלך וילכו לאהליהם שמחים וטובי לב על כל הטובה אשר עשה ה' לדוד עבדו ולישראל עמו<sup data-n=\"2158\">1</sup>, הנה פסוק זה הוא סיום וחותם ההפטורה דשמיני עצרת. דמזה מובן, דהגם ש\"שלח (המלך) את העם ויברכו את המלך גו'\" בפשטות הי' רק פעם אחת, בשמיני עצרת שלאחרי חנוכת בית המקדש [משא\"כ בהשנים שלאח\"ז, לא מצינו שהוצרכו ליטול רשות מהמלך<sup data-n=\"2159\">2</sup> (ולברך אותו) ללכת מביהמ\"ק לאהליהם], מ\"מ הענין ברוחניות הוא בשמיני עצרת דכל שנה ושנה. וכמבואר בלקו\"ת<sup data-n=\"2160\">3</sup> ובכמה דרושים ד\"ה זה<sup data-n=\"2161\">4</sup>, דבשמיני עצרת הוא הקליטה (עצרת מלשון קליטה<sup data-n=\"2162\">5</sup>) של כל הענינים דחודש תשרי, מתחיל מענין דתמליכוני עליכם שבראש השנה<sup data-n=\"2163\">6</sup>. ועד שאחד הפירושים בשמיני עצרת הוא מלשון מלוכה (כמו זה<sup data-n=\"2164\">7</sup> יעצור בעמי)<sup data-n=\"2165\">8</sup>, דמזה מובן, דענין המלכות בשמיני עצרת הוא מעניניו העיקריים. וזהו שהענין ד\"שלח (המלך) את העם גו'\" הוא בשמיני עצרת בכל שנה ושנה, דבשמיני עצרת נמשך קבלת עול מלכות שמים על כל השנה<sup data-n=\"2166\">9</sup>.\n<b>והנה</b> בדברי הימים<sup data-n=\"2167\">10</sup> כתיב וביום עשרים ושלשה לחודש השביעי שלח את העם גו', ומבאר אדמו\"ר הצ\"צ בהגהותיו ללקו\"ת ד\"ה זה<sup data-n=\"2168\">11</sup>, שזה רמז ליו\"ט שני של גליות (דיו\"ט שני דשמיני עצרת הוא בכ\"ג בתשרי). וצריך להבין, הרי בשמיני עצרת יש כמה ענינים, ומדוע הרמז דיו\"ט שני דשמיני עצרת הוא בהענין דשלח את העם דוקא. גם צריך להבין מה שבדברי הימים שם נאמר על הטובה אשר עשה ה'לדוד ולשלמה גו'. דיש לומר, דב' שינויים אלו [שבדברי הימים כתיב וביום עשרים ושלשה גו', ושמוסיף שם ולשלמה] שייכים זל\"ז. היינו, דענין שלח את העם שביום השמיני (יו\"ט ראשון דשמיני עצרת) שייך לדוד, וענין שלח את העם שביום עשרים ושלשה לחודש השביעי (יו\"ט שני דשמיני עצרת) שייך לדוד ולשלמה.\nב) <b>ויובן</b> זה בהקדים מה שארז\"ל<sup data-n=\"2169\">12</sup> יפה שעה אחת בתשובה ומעשים טובים בעולם הזה מכל חיי העולם הבא, ואיתא בלקו\"ת (בדרושי שמע\"צ<sup data-n=\"2170\">13</sup>), דבתשובה ומעשים טובים שני פירושים. א', דפירוש תשובה ומעשים טובים הוא שהתשובה היא הקדמה למעשים טובים, דבכדי שהמעשים יהיו טובים (ומאירים) הוא ע\"י קדימת התשובה<sup data-n=\"2171\">14</sup>. ועפ\"ז, זה שאמרו יפה שעה אחת כו' בעוה\"ז קאי (בעיקר) על מעשים טובים. והגם שגם לפי פירוש זה יש מעלה בתשובה מכיון שהיא מביאה למעשים טובים, ה\"ז ע\"ד הידוע<sup data-n=\"2172\">15</sup> בענין גדול לימוד שמביא לידי מעשה<sup data-n=\"2173\">16</sup>, שבזה גופא מודגש מעלת המעשה. הב', דתשובה ומעשים טובים הם שני ענינים, ויפה שעה אחת קאי על שניהם<sup data-n=\"2174\">17</sup>, היינו, דתשובה היא ענין בפ\"ע. ואדרבא, תשובה היא נעלית יותר ממעשים טובים<sup data-n=\"2175\">18</sup>. ועפ\"ז יש לומר דזה שמקדים תשובה למעשים טובים הוא מפני שהיא קודמת במעלה.\n<b>ונקודת</b> הביאור בזה י\"ל שבשניהם הו\"ע התשובה. היינו, שגם מעשים טובים ענינם הוא תשובה, דע\"י קיום המצוות [ועד\"ז ע\"י העבודה דכל מעשיך יהיו לשם שמים<sup data-n=\"2176\">19</sup>, ועאכו\"כ<sup data-n=\"2177\">20</sup> ע\"י בכל דרכיך דעהו<sup data-n=\"2178\">21</sup>] פודים את ניצוצות הקדושה שבדברים הגשמיים ומשיבים ומעלים אותם לשרשם. אלא שתשובה היא תשובה דהנשמה, השבת הנשמה למקורה ושרשה, והרוח תשוב אל האלקים אשר נתנה<sup data-n=\"2179\">22</sup>, ומעשים טובים הוא התשובה דהניצוצות שבעולם<sup data-n=\"2180\">23</sup>, כולל גם הניצוצות שבגופו ונפשו הבהמית, שהבירור והעלי' שלהם הוא ע\"י מעשה המצוות, מעשים טובים.וזהו יפה שעה אחת בתשובה ומעשים טובים בעולם הזה, כי ענין התשובה (תשובה דהנשמה, ותשובה דהניצוצות, מעשים טובים) היא בעולם הזה דוקא<sup data-n=\"2181\">24</sup>. דזהו הטעם על ירידת הנשמה למטה, בכדי שיהי' בה ענין התשובה. דבהיותה למעלה היא במדריגת צדיק, וע\"י ירידתה למטה מתחדש בה ענין התשובה<sup data-n=\"2182\">25</sup>, ובמקום שבעלי תשובה עומדין אין צדיקים גמורין יכולים לעמוד בו<sup data-n=\"2183\">26</sup>. ועד\"ז הוא בנוגע לירידת הניצוצות למטה, דע\"י הבירור והעלי' שלהם (ענין התשובה דהניצוצות) הם מתעלים למעלה יותר מכפי שהיו קודם הירידה<sup data-n=\"2184\">27</sup>. ועפ\"ז יש לבאר שני הפירושים דלעיל בזה שמקדים תשובה למעשים טובים [אם העיקר הוא מעשים טובים והתשובה היא הקדמה למעשים טובים, או שקדימת תשובה למעשים טובים היא גם קדימה במעלה], כי בהעילוי דתשובה (לגבי צדיקים) כמה ענינים, וישנם ענינים שעיקרם הוא בהתשובה דהנשמה, ומצד ענינים אלו, תשובה (דהנשמה) קודמת במעלה למעשים טובים (תשובה דהניצוצות), ויש ענינים שעיקרם הוא בהתשובה דהניצוצות, ומצד זה העיקר הוא מעשים טובים.\nג) <b>ויובן</b> זה בהקדים העילוי דתשובה כפשוטה (תשובה על עבירות), שיש בזה כמה ענינים. א', שהצמאון לאלקות דבעלי תשובה הוא צמאון גדול יותר מהצמאון דצדיקים. דמכיון שמקודם היו רחוקים, לכן הצמאון שלהם הוא גדול יותר, כמבואר בתניא<sup data-n=\"2185\">28</sup>. וב', דמכיון שמקודם היו רחוקים, הרי התענוג והנחת רוח למעלה שנעשה ע\"י התשובה הוא גדול יותר מהתענוג ונח\"ר דעשיית המצוות (עבודת הצדיקים) נח\"ר<sup data-n=\"2186\">29</sup> לפני שאמרתי ונעשה רצוני. וכידוע המשל על זה מבן מלך שנתרחק מאביו המלך ועד שהי' בשבי' וכו', דכשיוצא מהשבי' ובא לאביו המלך, התענוג והשמחה שלהם (של בן המלך ושל המלך) הוא גדול הרבה יותר מהתענוג והשמחה שהי' קודם (לפני שנתרחק). דעיקר התענוג והשמחה הוא מקירוב שבא לאחרי הריחוק<sup data-n=\"2187\">30</sup>. וג', דעבודת התשובה היא בדרך דילוג שלא בסדר והדרגה<sup data-n=\"2188\">31</sup>, שמשתנה ונעשה מציאות חדשה. ובלשון הרמב\"ם<sup data-n=\"2189\">32</sup> \"אני אחר ואיני אותו האיש שעשה אותן המעשים\" [וע\"י חידוש זה (דהאדם), נעשה חידוש גם בעולם, שזדונותנהפכים לזכיות<sup data-n=\"2190\">33</sup>]. וגם מזה נעשה תענוג גדול למעלה, דעיקר התענוג הוא מדבר חדש דוקא, ולהעיר ממשל הידוע דצפור המדברת<sup data-n=\"2191\">34</sup>.\nד) <b>והנה</b> הכוונה בבריאת האדם היא שיהי' באופן דעשה האלקים את האדם ישר<sup data-n=\"2192\">35</sup>, שילך כל ימיו בדרך הישרה, כדיוק לשון רז\"ל<sup data-n=\"2193\">36</sup> במי נמלך בנשמותיהן של צדיקים, צדיקים דייקא<sup data-n=\"2194\">37</sup>. ואף שבמקום שבעלי תשובה עומדין אין צדיקים גמורין יכולים לעמוד בו, הרי ידוע<sup data-n=\"2195\">38</sup> דענין התשובה הוא (לא רק על עבירות, כי אם גם) השבת הנפש למקורה ושרשה, דתשובה זו היא גם בצדיקים גמורים. דזה גופא שנשמתו נמצאת למטה ולא במקורה ושרשה, שזהו מקומה האמיתי [ובפרט דזה שהנשמה היא למטה בעוה\"ז, הוא \"בחי' גלות ממש\"<sup data-n=\"2196\">39</sup>], הרי צריך להשיבה למקומה. ומעלת הבעלי תשובה על צדיקים גמורים, דבמקום שבעלי תשובה עומדין אין צדיקים גמורין יכולים לעמוד בו, הוא גם בתשובה זו (דצדיקים). ותכלית ירידת הנשמה לעוה\"ז הגשמי הוא בשביל תשובה זו<sup data-n=\"2197\">40</sup>.\n<b>והענין</b> הוא, דג' מעלות הנ\"ל שבבעלי תשובה על צדיקים גמורים, הם גם בהנשמה כשנעשית בעל תשובה ע\"י ירידתה למטה לגבי כמו שהיתה קודם הירידה (בחי' צדיק). דמכיון שגם הריחוק שמצד ירידת הנשמה למטה (גם כשלא עבר עבירה מימיו) הוא ריחוק עצום ביותר, ועד שהירידה למטה היא \"בחי' גלות ממש\" (כנ\"ל), הרי ריחוק זה מעורר אצלו צמאון גדול, וגם התענוג והשמחה שבקירוב שלאחרי הריחוק הוא תענוג גדול ביותר. ועד\"ז הוא בענין החידוש שבתשובה, דמכיון שענין התשובה (גם תשובה דצדיקים) הוא שמתמרמר על מצבו (שהוא מרוחק מאלקות)<sup data-n=\"2198\">41</sup> ורוצה לצאת ממצבו ומציאותו<sup data-n=\"2199\">42</sup>, אסורה מכאן<sup data-n=\"2200\">43</sup>, הרי זה ענין של חידוש.\n<b>אלא</b> שאעפ\"כ, מכיון שי\"ל שאין מרז\"ל זה יוצא מידי פשוטו, הרי זה שאמרו במקום שבעלי תשובה עומדין אין צדיקים גמורין יכולים לעמוד בו, הואבעיקר בבעלי תשובה כפשוטם<sup data-n=\"2201\">44</sup>. ויש לומר, דזה שעיקר המעלה דבעלי תשובה הוא בבעלי תשובה כפשוטם, הוא במעלת החידוש שבתשובה. דבמעלת הצמאון, ובהמעלה דקירוב שלאחרי הריחוק, אין חילוק (כ\"כ) ביניהם, וזה שעיקר העילוי דתשובה הוא בתשובה כפשוטה הוא במעלת החידוש שבתשובה. והענין הוא, דבצדיקים, מכיון שנשמתם מאירה אצלם בגילוי, הרי המרירות שלהם על ריחוקם מאלקות, ועד שהמרירות נוגעת עד הנפש, אין זה פלא וחידוש (כ\"כ). והגם דענין התשובה הוא שיוצא ממציאות שלו, מ\"מ, מכיון שהנשמה בטבעה רוצה למלאות רצון קונה, והכוונה שלמעלה (רצון קונה) בירידת הנשמה בגוף היא לבוא לתשובה, הרי בהרצון (שמצד טבע הנשמה) למלאות רצון קונו, נכלל גם היציאה ממציאותו שע\"י התשובה<sup data-n=\"2202\">45</sup>. משא\"כ בתשובה כפשוטה, מכיון שמקודם (לפני התשובה) הי' במצב כזה שלא עשה רצון הקב\"ה<sup data-n=\"2203\">46</sup>, שהרי עשה עבירות במזיד, הרי זה שעושה אח\"כ תשובה, אין זה המשך ממצבו הקודם, ועל ידי התשובה נעשה מציאות חדשה לגמרי.\nה) <b>והנה</b> ג' ענינים הנ\"ל הם גם בהתשובה דהשבת הניצוצות (שבדברים הגשמיים) למקורם, שגם בתשובה זו יש דוגמת ג' ענינים הנ\"ל. א', הצמאון והתשוקה דהניצוצות (מצד שרשם) לעלות מירידתן ולחזור לשרשם, וע\"ד מים תחתונים בוכין אנן בעינן למהוי קדם מלכא<sup data-n=\"2204\">47</sup>. ב', גודל השמחה שנעשה מהעלאת הניצוצות וחזרתם למקורם לאחרי שנתרחקו<sup data-n=\"2205\">48</sup>. וג', מכיון שהניצוצות שנפלו בקליפות, גם בקליפת נוגה<sup data-n=\"2206\">49</sup>, נכבה אורם<sup data-n=\"2207\">50</sup>, הרי מצד מצבם אין שייך שיתבררו ויתעלו לשרשן, וכשמתבררים ועולים לשרשם (ע\"י עבודת האדם), הוא חידוש<sup data-n=\"2208\">51</sup>.\n<b>ויש</b> לומר, דהחידוש שבתשובה דהשבת הניצוצות הוא חידוש גדול יותר מהחידוש שבתשובה כפשוטה. דבתשובה כפשוטה, אף שלפני התשובה הי' במצב כזה שלא עשה רצון הקב\"ה כנ\"ל, הרי זהו רק כמו שהוא בחיצוניות, אבל רצונו האמיתי(גם אז<sup data-n=\"2209\">52</sup>) הי' למלאות רצון קונו (כפס\"ד הידוע<sup data-n=\"2210\">53</sup>), אלא שרצון זה הי' בתכלית ההעלם, ועד שהגילוי שלו הוא כמו חידוש<sup data-n=\"2211\">54</sup>. משא\"כ התשובה דהחזרת הניצוצות למקורם, מכיון שהניצוצות שנפלו בהקליפות (גם בק\"נ) נחשך אורם, ועד שאינם בבחי' אור כלל, הרי הבירור וההעלאה שלהם הוא חידוש ממש.\nו) <b>אמנם</b><b>,</b> ענין זה (העילוי בהתשובה דהחזרת הניצוצות) הוא במעלת החידוש שבתשובה. משא\"כ המעלה דצמאון שע\"י הריחוק היא בעיקר בהתשובה דנשמה (הן בתשובה דצדיקים והן בתשובה כפשוטה). דמכיון שההתקשרות דנשמות עם אלקות היא התקשרות עצמית, כמו התקשרות בן עם האב (בנים אתם להוי' אלקיכם<sup data-n=\"2212\">55</sup>) שהיא התקשרות עצמית<sup data-n=\"2213\">56</sup>, הרי כשהנשמה מרגישה שהיא מרוחקת מאלקות (הריחוק שע\"י ירידתה למטה, ומכ\"ש הריחוק שע\"י עבירות), זה נוגע לעצמותה, ובמילא, גם הצמאון שע\"י הרגש הריחוק נוגע לעצמותה. ועד\"ז הוא גם בהתענוג מהקירוב שבא לאחרי הריחוק, דמכיון שהנשמות הם בנים, דהבן הוא מעצמיות האב<sup data-n=\"2214\">57</sup>, הרי תענוג האב מזה שנתקרב בנו (לאחרי שנתרחק), ועאכו\"כ בנו יחידו<sup data-n=\"2215\">58</sup>, הוא תענוג עצמי<sup data-n=\"2216\">59</sup>. משא\"כ התענוג מקירוב הניצוצות לאחרי שנתרחקו הוא דוגמת שני אוהבים<sup data-n=\"2217\">60</sup> שלא ראו זה את זה משך זמן רב ולאחרי שמתקרבים ורואים זה את זה, הם מתענגים ושמחים במאד<sup data-n=\"2218\">61</sup>, שתענוג זה (עם היותו תענוג גדול) הוא כמו שאר התענוגים שהם מדבר שחוץ ממנו<sup data-n=\"2219\">62</sup>.\n<b>ויש</b> להוסיף, שגם החידוש שבתשובה דהחזרת הניצוצות (שבדברים הגשמיים) למקורם, הוא ע\"י נשמות ישראל דוקא<sup data-n=\"2220\">63</sup> (ע\"י שמקיימים מצוות בדברים הגשמיים, או ע\"י שמשתמשים בהם לשם שמים). ויש לומר שזהו ע\"ד המבואר במקום אחר<sup data-n=\"2221\">64</sup> דזה שהכח לעשות לו ית' דירה בתחתונים הוא בנש\"י דוקא הוא כי מכיון שעולם הוא מלשון העלם והסתר<sup data-n=\"2222\">65</sup>, הרי זה שהעולם נעשה כלי לאלקות (היפךהטבע והגדר דעולם) הוא התחדשות<sup data-n=\"2223\">66</sup>, וע\"ד החידוש דבריאה יש מאין שהוא בכח העצמות<sup data-n=\"2224\">67</sup>, ולכן עשיית דירה בתחתונים היא ע\"י נשמות ישראל דוקא, דלהיות שהנשמות מושרשות בהעצמות, לכן ניתן להם כח זה.\nז) <b>ועפ\"ז</b> יש לתווך שני הפירושים ביפה שעה אחת בתשובה ומעשים טובים, דלפי פירוש אחד תשובה היא נעלית יותר ממעשים טובים, ולפי פירוש אחד התשובה היא הקדמה למעשים טובים, כי זה שהתשובה היא נעלית יותר ממעשים טובים הוא זה שהתענוג דתשובה (דהנשמה) הוא תענוג עצמי כנ\"ל, אלא שאעפ\"כ יש מעלה במעשים טובים לגבי תשובה מצד החידוש שבזה (כנ\"ל), וגם מפני שעי\"ז דוקא נשלמת הכוונה דדירה בתחתונים<sup data-n=\"2225\">68</sup>. והתשובה היא הקדמה למעשים טובים, דמכיון שהכח לעשות לו ית' דירה בתחתונים הוא בנשמות דוקא (כנ\"ל), לכן, בכדי שהדירה שנעשית ע\"י מעשה המצוות תהי' בשלימות ובגילוי, מעשים טובים ומאירים, הוא ע\"י קדימת התשובה, הגילוי דשרש הנשמה ועד כמו שמושרשת בהעצמות.\nח) <b>והנה</b> שני ענינים הנ\"ל שבתשובה, שהיא ענין בפ\"ע ושהיא הקדמה למעשים טובים, הם בדוגמת התשובה דראש השנה והתשובה דעשי\"ת. דהתשובה דראש השנה, המרומזת בתקיעת שופר<sup data-n=\"2226\">69</sup>, עיקרה הוא (לא התשובה על ענינים פרטיים, כי אם) ההשבה למקורו ושרשו<sup data-n=\"2227\">70</sup>. וענין המיצר דשופר הוא (לא מיצר של ועל עוונות, כי אם) זה שהוא \"עם\" ולא המרחב ששם מושרש<sup data-n=\"2228\">71</sup>. דזהו הקשר דשופר עם תמליכוני עליכם, דענין תמליכוני עליכם הוא המשכת המלכות משרשה ומקורה. והתשובה דעשרת ימי תשובה [שאז הוא בנין הי\"ס דמלכות<sup data-n=\"2229\">72</sup>, הפרטים דמלכות] שייכת לפרטים. והיא הקדמה להתורה ומצוות (מעשים טובים) שהתחלתם היא בד' הימים שבין יום הכפורים לסוכות, כדאיתא במדרש<sup data-n=\"2230\">73</sup> שבימים אלו זה עוסק בסוכתו וזה בלולבו, סוכה שהיא מקיף הו\"ע המצוות, לבושים<sup data-n=\"2231\">74</sup>, ולולב שענינו הוא ההמשכה בפנימיות [כידוע<sup data-n=\"2232\">75</sup> שע\"י נטילת ד' מינים נמשך המקיף דסוכה בפנימיות], הו\"ע התורה, ותורתך בתוך מעי<sup data-n=\"2233\">76</sup>. ובפרט שבד' המינים עצמם, והגבוה בהם הוא הלולבשיש בו טעם רומז על תורה<sup data-n=\"2234\">77</sup>. ושני ענינים אלו, שבד' הימים שלפני סוכות הם בתור הכנה (<i>עוסק</i> בסוכתו ובלולבו), בחג הסוכות הם בפועל<sup data-n=\"2235\">78</sup>.\nט) <b>והנה</b> בשמיני עצרת (שמיני מלשון שומן<sup data-n=\"2236\">79</sup>) הוא התמצית והעסענץ<sup data-n=\"2237\">80</sup> של כל הענינים דחודש תשרי<sup data-n=\"2238\">81</sup>, ובו נקלטים (עצרת מלשון קליטה&lt;5&gt;) כל ענינים אלו. ועי\"ז נמשכים (כל הענינים דחודש תשרי) על כל השנה, כמ\"ש אדמו\"ר הצ\"צ<sup data-n=\"2239\">82</sup> ד\"בו (בשמיני עצרת) מקבלים כל ישראל שפע הנהגתם בתורתם ועבודתם כל השנה\". וזהו ביום השמיני שלח (המלך) את העם גו' וילכו לאהליהם, דמבחינת המלכות שנמשכה בראש השנה עשי\"ת וכו' ניתן הכח (שלח<sup data-n=\"2240\">83</sup>) לכל ישראל ללכת לאהליהם, לעניני העולם שעוסקים בהם במשך השנה, ולעשות מהם אהל ומשכן לו ית', דירה בתחתונים<sup data-n=\"2241\">84</sup>. וזהו שלח את העם (עם דייקא), שזהו ע\"ד \"למען<sup data-n=\"2242\">85</sup> הקים אותך היום לו לעם\" שבראש השנה, דמ\"ש \"לו לעם\" (דוקא) הוא כי אין<sup data-n=\"2243\">86</sup> מלך בלא עם<sup data-n=\"2244\">87</sup>. אלא שבראש השנה, הפירוש \"עם\" הוא (לא מלשון עוממות<sup data-n=\"2245\">88</sup> אלא אדרבא) עם מלשון עמו (שהם אנשים כמותו ומתייחסים אליו)<sup data-n=\"2246\">89</sup>, וענין שלח את העם דשמיני עצרת הוא שיהיו בחי' עם מלשון עוממות<sup data-n=\"2247\">90</sup>, וגם בזה יומשך מבחי' עם מלשון עמו<sup data-n=\"2248\">91</sup>,שעי\"ז נמשך הכח להיות \"וילכו לאהליהם\", לעשות מאהליהם כפשוטם, עניני העולם, אהל ומשכן לו ית'.\n<b>וממשיך</b> בכתוב שמחים וטובי לב על כל הטובה אשר עשה ה' לדוד עבדו ולישראל עמו, שמחים וטובי לב הוא גילוי האהבה דפנימיות נקודת הלב (כמבואר בהמאמר<sup data-n=\"2249\">92</sup>) [דלאחרי אמירת המזמור<sup data-n=\"2250\">93</sup> לדוד ה' אורי וישעי מר\"ח אלול עד הו\"ר<sup data-n=\"2251\">94</sup>, שני פעמים בכל יום, דנקודת המזמור היא לך אמר לבי בקשו פני גו'<sup data-n=\"2252\">95</sup>, האָט מען זיכער אויסגעבעטן שיהי' גילוי פנימיות נקודת הלב<sup data-n=\"2253\">96</sup>, ובשמיני עצרת נעשים כל ישראל שמחים וטובי לב], על כל הטובה אשר עשה ה' לדוד עבדו, בחי' מלכותו ית', ולישראל עמו, שעוסקים בבנינו של עולם (כמ\"ש<sup data-n=\"2254\">97</sup> וכל בניך לימודי הוי' אל תקרי בניך אלא בוניך<sup data-n=\"2255\">98</sup>), דבנינו של עולם הוא בחי' מלכותו ית'<sup data-n=\"2256\">99</sup>. ויש לומר, דישראל הוא בחי' בן (כידוע בענין יעקב וישראל, שיעקב הוא בחי' עבד וישראל הוא בחי' בן<sup data-n=\"2257\">100</sup>), ועם הוא מלשון עוממות (כנ\"ל), בחי' עבד שלמטה מבחי' בן. אבל יש יתרון גם בזה שישראל הם עמו ית' על זה שהם בניו ית' (כמשנ\"ת לעיל<sup data-n=\"2258\">101</sup>). ולכן אומר כאן ולישראל עמו, שתי המעלות<sup data-n=\"2259\">102</sup>. וע\"ד שנת\"ל בענין שלח את העם, שהוא חיבור ד\"עם\" מלשון עמו (אנשים כמותו) עם \"עם\" מלשון עוממות.\nיו\"ד) <b>וע\"פ</b> כל הנ\"ל יש לבאר גם זה שבדברי הימים כתיב וביום עשרים ושלשה לחודש השביעי שלח את העם גו' שזהו רמז ליו\"ט שני של גליות (כנ\"ל בתחלת המאמר דהצ\"צ), דענין יו\"ט שני הוא<sup data-n=\"2260\">103</sup> שגם יום שמצד עצמו הוא חול, עושים אותו ישראל ליו\"ט (קדושה), ולכן מרמז הכתוב הענין דיו\"ט שני בשמיני עצרת דוקא, ובשמיני עצרת גופא בהענין דשלח את העם, כי ענין שלח אתהעם גו' הוא (כנ\"ל בארוכה) הנתינת כח משמיני עצרת על כל השנה לעשות את עניני העולם (שמצד עצמם הם חול) לדירה לו ית'. ויש להוסיף, דנתינת כח הנ\"ל שנמשך ביו\"ט שני דשמיני עצרת (שמחת תורה) היא שייכת יותר להעולם מההמשכה שביו\"ט ראשון<sup data-n=\"2261\">104</sup>, מכיון שעוד לפני ההליכה לאהליהם, בשמיני עצרת גופא, נעשה כבר (ביו\"ט שני שבו) הפיכת חול לקודש. ולכן מוסיף (בדברי הימים) \"ולשלמה\", דהנתינת כח על עבודת הבירורים במשך כל השנה שנמשך מיו\"ט שני דשמיני עצרת [שבו נעשה כבר הענין דהפיכת חול לקודש, ובפרט שביום זה קוראין בתורה בראשית<sup data-n=\"2262\">105</sup> ברא אלקים את השמים ואת הארץ] הוא באופן שבירור הניצוצות יהי' כמו שהי' בימי שלמה, שעליו נאמר<sup data-n=\"2263\">106</sup> שלמה יהי' שמו ושלום ושקט אתן על ישראל בימיו, בירור בדרך שלום ומנוחה<sup data-n=\"2264\">107</sup>. וזה נעשה הכנה קרובה לביאת משיח צדקנו, שהוא מזרע דוד ושלמה<sup data-n=\"2265\">108</sup>, שאז יהי' אמיתית ושלימות השלום, באופן נעלה יותר גם מכמו שהי' בימי שלמה, שהשלום שהי' בימי שלמה הוא שכולם נתבטלו מצד הגילוי אור (אבל לא נהפכו לקדושה), משא\"כ לע\"ל יהי' אהפוך<sup data-n=\"2266\">109</sup> אל עמים שפה ברורה גו' לעבדו שכם אחד<sup data-n=\"2267\">110</sup>, בביאת משיח צדקנו בקרוב ממש.\n**********",[["2157","*","יצא לאור ב<b>קונטרס שמע\"צ ושמח\"ת – תשמ\"ח</b>, \"לקראת שמע\"צ ושמח\"ת . . <i>ערחה\"ס שנת תשמח</i>\"."],["2158","1","מלכים-א ח, סו."],["2159","2","ראה מצודת דוד עה\"פ: שלח את העם ר\"ל נטלו ממנו רשות. וכ\"ה בפירש\"י ורד\"ק לדברי הימים שבהערה 10. וראה גם מו\"ק ט, א."],["2160","3","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381038\" data-slug=\"likkutei-torah\" data-id=\"4001381038\">לקו\"ת</a> דרושים לשמע\"צ רד\"ה זה (פו, ג). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381042\" data-slug=\"likkutei-torah\" data-id=\"4001381042\">לקו\"ת</a> דרושים לסוכות עח, סע\"ג וריש ע\"ד. שם עט, ג. פא, ג."],["2161","4","רד\"ה זה תקס\"ג (נדפס בסה\"מ תקס\"ב ח\"ב ע' תקנו ואילך. והגהות עליו – באוה\"ת שמע\"צ ס\"ע א'תתיח ואילך). תרע\"ח (סה\"מ תרע\"ח ע' לט). תרצ\"ג (סה\"מ קונטרסים ח\"א רנד, א). וראה גם אוה\"ת סוכות ס\"ע א'תשסו ואילך. רד\"ה ביום השמיני עצרת ה'תש\"מ (לעיל ע' רטו) ובהנסמן שם בהערה 5."],["2162","5","לקו\"ת דרושים לשמע\"צ פה, ג. שם פח, ד. צא, א. סידור (עם דא\"ח) שער הלולב רסג, ג. מאמרי אדמו\"ר האמצעי ויקרא ח\"א ס\"ע שצ. וש\"נ. אוה\"ת סוכות שם. שם (הוספות) ס\"ע א'תתקמו. ובכ\"מ."],["2163","6","ר\"ה טז, א. לד, ב."],["2164","7","שמואל-א ט, יז ובפרש\"י."],["2165","8","אוה\"ת שמע\"צ ע' א'תשע (מזח\"ג רנו, ריש ע\"ב). שם ע' א'תשעו-ז. ד\"ה ביום השמיני עצרת ה'תש\"מ (לעיל ס\"ע רכד) ובהנסמן שם בהערה 123.\nובאוה\"ת שם (בהוספות) ע' א'תתקמז: עצרת פי' במאור עינים זה יעצור, והוא ממשלה ובחירה <i>שמתחיל בר\"ה ומסתיים שמע\"צ</i> כו'."],["2166","9","סד\"ה ביום השמיני עצרת תרס\"ז (המשך תרס\"ו ע' שעט)."],["2167","10","ב' ז, י."],["2168","11","לקו\"ת דרושים לשמע\"צ פז, סע\"ד. אוה\"ת שמע\"צ ס\"ע א'תתט ואילך."],["2169","12","אבות פ\"ד מי\"ז."],["2170","13","ד\"ה ביום השמיני עצרת גו' שמאלו כו' (פג, א ואילך). ד\"ה זה תקס\"ד (נדפס בסה\"מ תקס\"ג ח\"ב ע' תשעח ואילך). ובאוה\"ת שמע\"צ ע' א'תתכ (בהגהות לד\"ה ביום השמיני שלח תקס\"ג הנ\"ל) דדרוש זה והדרוש ביום השמיני שלח \"שייכי אהדדי, ומדברים בענין אחד\"."],["2171","14","כן מפרש באוה\"ת שם הכוונה בלקו\"ת שם. וכ\"ה גם בלקו\"ת ד\"ה ביום השמיני עצרת גו' כנישין כו' (פה, א)."],["2172","15","ראה לקו\"ת שם רד\"ה ביום השמיני עצרת גו' שמאלו כו' (פג, א). וראה אוה\"ת שם, ד\"ענין שהתלמוד מביא לידי מעשה\" הוא \"כמו שהקדים תשובה למעשים טובים\"."],["2173","16","קידושין מ, ב. וש\"נ. וראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ג."],["2174","17","לקו\"ת שם רפ\"ד (פג, ד)."],["2175","18","לקו\"ת שם. ובארוכה יותר – באוה\"ת שם ע' א'תתכא. וראה לקמן סעיף ז."],["2176","19","אבות פ\"ב מי\"ב. רמב\"ם הל' דעות ספ\"ג. טושו\"ע או\"ח סרל\"א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241661\" data-slug=\"likkutei-sichot\" data-id=\"1300241661\">לקו\"ש חכ\"ד ע' 646</a> בהערה ד\"ה כל מעשיך לשם שמים."],["2177","20","ראה לקו\"ש ח\"ג ע' 907. שם ע' 932. ח\"י ע' 104 ואילך. ובכ\"מ."],["2178","21","משלי ג, ו. רמב\"ם וטושו\"ע שם. שו\"ע אדה\"ז או\"ח סקנ\"ו ס\"ב."],["2179","22","קהלת יב, ז. וראה לקו\"ת ר\"פ האזינו. הנסמן להלן בהערה 38."],["2180","23","ראה תו\"ח ויצא כז, א דענין הבירורים הוא \"אור חוזר דתשובה\". וראה המשך יונתי תר\"ם פכ\"א (ס\"ע לד) \"ענין תשובה להשיב הניצוץ שבצמר וקלף כו'\"."],["2181","24","להעיר מלקו\"ת ר\"פ פינחס."],["2182","25","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו\"ת בלק עג, סע\"א</a>. מאמרי אדמו\"ר הזקן על פרשיות התורה ח\"ב ע' תשכז. ובכ\"מ. ובלקו\"ת שם, שזהו \"התירוץ האמיתי\" למה ירדה הנשמה לעולם הזה. וראה ד\"ה מים רבים ה'תשל\"ח ס\"ד (לקמן ע' רמח)."],["2183","26","רמב\"ם הל' תשובה פ\"ז ה\"ד, מברכות לד, ב."],["2184","27","ראה המשך יונתי הנ\"ל פט\"ו ואילך. וראה גם לעיל ד\"ה בסוכות תשבו שנה זו – ה'תשמ\"א (לעיל ע' קסז ואילך) ס\"ה."],["2185","28","פ\"ז (יב, א)."],["2186","29","תו\"כ (הובא בפרש\"י) עה\"פ ויקרא א, ט. ספרי (הובא בפרש\"י) עה\"פ פינחס כח, ח."],["2187","30","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, סע\"א</a> ואילך). לקו\"ת ד\"ה ביום השמיני עצרת שבהערה 13 פ\"ד (פג, ד). אוה\"ת שמע\"צ שם ע' א'תתכא."],["2188","31","לקו\"ת דרושים לשבת שובה סה, א. וראה בארוכה ד\"ה שובה ישראל ה'תשל\"ו (לעיל ע' פג ואילך)."],["2189","32","הל' תשובה פ\"ב ה\"ד. ועד\"ז בסמ\"ג מ\"ע טז; ר\"ן לר\"ה טז, ב – הובא בחדא\"ג מהרש\"א לר\"ה שם."],["2190","33","יומא פו, ב. וראה ד\"ה ביום השמיני עצרת ה'תש\"מ ס\"ה (לעיל ע' רכ) ובהערות שם."],["2191","34","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א ויצא כא, ג</a>. תו\"ח תולדות יא, א. ויצא כד, סע\"ג ואילך. ובכ\"מ."],["2192","35","קהלת ז, כט."],["2193","36","ב\"ר פ\"ח, ז. רות רבה פ\"ב, א (ג)."],["2194","37","ד\"ה מי יתנך תקס\"ה (סה\"מ תקס\"ה ח\"א ע' תפז. ועם הגהות – ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770266\" data-slug=\"or-hatorah-hb\" data-id=\"8316770266\">אוה\"ת שה\"ש כרך ב ס\"ע תרלד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770307\" data-slug=\"or-hatorah-hb\" data-id=\"8316770307\">שם ריש ע' תרעה</a>). המשך תרס\"ו ע' כ. שם ע' שנא. ובכ\"מ."],["2195","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380815\" data-slug=\"likkutei-torah\" data-id=\"4001380815\">לקו\"ת ראה כד, ד</a>. דרושים לשבת שובה סו, ג. ובכ\"מ."],["2196","39","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, א</a>). ובהמשך הענין שם \"גם שיהי' צדיק גמור כו'\"."],["2197","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381013\" data-slug=\"likkutei-torah\" data-id=\"4001381013\">לקו\"ת האזינו עב, רע\"ג</a>."],["2198","41","ראה לקו\"ת שם \"שנפרד מן החיים האמיתיים\" – אף שמדובר שם ב\"מי שלא חטא מימיו\"."],["2199","42","ראה סה\"מ ה'תש\"י ע' 7 (ובכ\"מ) בענין ההפרש בין תשובה לרעו\"ד, דבתשובה, העיקר היא (לא זה שנמשך אל השוב והחיים, כי אם) \"הבריחה מהמות והסכנה\". דיש לומר, שכן הוא גם בתשובה דצדיקים, שעיקרה הבריחה מהמות (מזה ש\"נפרד מן החיים האמיתיים\")."],["2200","43","לשון רש\"י על הפסוק שמות ג, ג. וראה סה\"ש ה'תש\"ב ע' 47: משה רבינו איז זיין אופן תשובה אסורה מכאן להתקרב לשם, וואָס די כוונה איז אַז מען באַדאַרף זיך ניט מסתפק זיין מיט דעם מעמד ומצב וואָס מען שטייט. אפילו אַ צדיק גמור ווי משה רבינו דאַרף האָבן די עבודה פון אסורה מכאן להתקרב לשם וואָס דאָס איז די תנועה פון תשובה."],["2201","44","להעיר מסה\"מ ה'תש\"ט ע' 183, שהעילוי דתשובה שנעשה בהנשמה ע\"י ירידתה למטה, הוא \"<i>ע\"ד</i> במקום שבעלי תשובה עומדים כו'\" (ע\"ד ולא ממש)."],["2202","45","בדוגמת המבואר בד\"ה והי' עקב ה'תשכ\"ז (לקמן ח\"ד ע' קצב ואילך) סעיף ה בענין מס\"נ, דאף שענין המס\"נ הוא ביטול בתכלית, מ\"מ, מכיון שזהו טבע הנשמה, אין זה חידוש (כ\"כ)."],["2203","46","ואף שגם לפני התשובה לא עבר על רצונו ית' בעבירות חמורות – מ\"מ, מכיון שעשיית התשובה שלו (אח\"כ) היא על עבירות אלו שבהם <i>לא</i> עשה קודם רצון הקב\"ה, הרי התשובה אינה המשך מצבו הקודם."],["2204","47","תקו\"ז ת\"ה (יט, סע\"ב). ת\"מ (פ, א). מאמרי אדמו\"ר האמצעי דברים ח\"א ע' שיט. וש\"נ. וראה שם ח\"ג ס\"ע א'קלב ואילך."],["2205","48","ראה בארוכה המשך וככה תרל\"ז פצ\"ז."],["2206","49","בנוגע להניצוצות שבגקה\"ט מבואר בכ\"מ (נסמן לעיל ע' קסו הערה 42. וראה גם ד\"ה זאת תורת הבית שבהערה הבאה) שהניצוצות עצמם נעשו כמו רע. אבל אין זה שייך לכאן, כיון שהמדובר כאן הוא בהעלאת הניצוצות ע\"י \"מעשים טובים\" שזהו בדברים המותרים דוקא."],["2207","50","ד\"ה זאת תורת הבית תרפ\"ט פ\"ו (סה\"מ קונטרסים ח\"א מב, א)."],["2208","51","וע\"ד המבואר בכ\"מ (וראה גם לקמן ס\"ז) דעשיית העולם לדירה לו ית' הוא חידוש (ועד שהוא בדוגמת החידוש דבריאה יש מאין) – אף שבכל נברא יש חיות אלקי, שהוא (החיות האלקי) אמיתית מציאותו של הנברא – דמכיון שענין וגדר העולם (מלשון העלם והסתר) הוא שהוא <i>מעלים ומסתיר</i> על האלקות שבו, לכן, זה שמתגלה בו החיות אלקי שבו, הוא <i>חידוש</i>."],["2209","52","דהרי הנשמה גם בעת החטא היתה באמנה אתו ית' – <a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא ספכ\"ד</a>."],["2210","53","רמב\"ם הל' גירושין ספ\"ב."],["2211","54","אבל לא חידוש ממש. וראה ד\"ה זאת תורת הבית שבהערה 50 (בענין ההפרש בין ניצוצות דתהו לנשמות), דנשמה, \"גם כשנפלה ח\"ו ר\"ל בגקה\"ט ה\"ה בבחי' אור\" ולכן \"שייך בה התעוררות שתתעורר ע\"י גילוי אור מלמעלה\"."],["2212","55","ראה יד, א."],["2213","56","ראה ד\"ה זה היום תחלת מעשיך דיום ב' דראש השנה שנה זו – ה'תשמ\"א ס\"ד (לעיל ע' לב)."],["2214","57","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. ד\"ה הנ\"ל שם."],["2215","58","כתורת הבעש\"ט דכאו\"א מישראל הוא כבנו יחידו של הקב\"ה (כתר שם טוב – הוצאת קה\"ת תשנ\"ט – הוספות סי' קסז)."],["2216","59","אוה\"ת שמע\"צ ע' א'תתכא."],["2217","60","כ\"ה בהמשך וככה תרל\"ז שם."],["2218","61","ראה גם מאמרי אדמו\"ר הזקן אתהלך לאזניא ע' א. מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תרצו ואילך. ועוד."],["2219","62","ראה אוה\"ת שם."],["2220","63","וצע\"ק מז\"מ ב\"נ. ומכללות הענין שמקיימין בהעולם הרצון דלשבת יצרה."],["2221","64","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061024\" data-slug=\"likkutei-sichot\" data-id=\"1300061024\">לקו\"ש ח\"ו ע' 24</a>."],["2222","65","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380463\" data-slug=\"likkutei-torah\" data-id=\"4001380463\">לקו\"ת שלח לז, ד</a>. מאמרי אדמו\"ר האמצעי דברים ח\"א ע' שג. ח\"ג ע' א'נט. לקו\"ש חל\"ד ע' 112 הערה 63. <i>וש\"נ</i>."],["2223","66","ראה גם ד\"ה והי' עקב ה'תשכ\"ז (לקמן ח\"ד ע' קצ ואילך) ס\"ד."],["2224","67","אגה\"ק ס\"ך (קל, סע\"א ואילך)."],["2225","68","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>) שזהו הכוונה בירידת הנשמה למטה. וזה בא בהמשך להמבואר שם פל\"ו שתכלית בריאת כל העולמות הוא שיהי' \"דירה <i>בתחתונים</i>\"."],["2226","69","רמב\"ם הל' תשובה פ\"ג ה\"ד."],["2227","70","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380895\" data-slug=\"likkutei-torah\" data-id=\"4001380895\">לקו\"ת ר\"פ נצבים (מד, א</a>) \"בראש השנה הוא בחי' התשובה, שכללות נש\"י תשובנה <i>למקורם ושרשם</i>\"."],["2228","71","ראה לקו\"ש ח\"ד ע' 1147 הערה 19."],["2229","72","פע\"ח שער כד (שער ר\"ה) פ\"ה, הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380925\" data-slug=\"likkutei-torah\" data-id=\"4001380925\">לקו\"ת נצבים נא, רע\"ג</a>."],["2230","73","ויק\"ר פ\"ל, ז."],["2231","74","<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא ספ\"ה</a>. ובכ\"מ."],["2232","75","ראה ד\"ה בסוכות תשבו שנה זו – ה'תשמ\"א (לעיל ע' קסז) ס\"ד ובהנסמן שם בהערה 59."],["2233","76","תהלים מ, ט. תניא שם."],["2234","77","ראה ויק\"ר פ\"ל, יב."],["2235","78","וגם נטילת ד' מינים בפועל (שבסוכות) שייך לתורה, כי (נוסף על זה שנטילת ד' מינים היא המשכה בפנימיות, כנ\"ל) בנטילת ד' מינים העיקר הוא הלולב [שעליו מברכים \"אקב\"ו על נטילת לולב, לפי שהלולב גבוה מכולן חשוב הוא ונקראת כל האגודה על שמו\" – שו\"ע אדה\"ז סוף הל' לולב (סתרנ\"א סי\"ז), מסוכה לז, ב], שמרמז על תורה, כנ\"ל."],["2236","79","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080435\" data-slug=\"or-hatorah-hb\" data-id=\"8160080435\">אוה\"ת שמע\"צ ע' א'תתיז</a>; סד\"ה ביום השמיני עצרת עדר\"ת (המשך תער\"ב ח\"א ע' תלה); סד\"ה ביום השמיני שלח תרע\"ח (סה\"מ תרע\"ח ע' מה), ועוד – בשם הה\"מ – דשמיני הוא ל' שמן. ובסד\"ה ביום השמיני עצרת תרצ\"ד (תשי\"א) (סה\"מ ה'תשי\"א ע' 60), תש\"ב (סה\"מ ה'תש\"ב ס\"ע 35), תש\"ג (סה\"מ ה'תש\"ג ע' 53) הוא כבפנים. וראה גם אוה\"ת שם ריש ע' א'תתיח."],["2237","80","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830240\" data-slug=\"or-hatorah-hb\" data-id=\"8158830240\">אוה\"ת בלק ע' תתקכו</a>: אַסענצייע, כן אמר אדמ\"ו נ\"ע על בחי' שמיני עצרת."],["2238","81","ראה ד\"ה ביום השמיני שלח תקס\"ג (סה\"מ תקס\"ב ח\"ב ע' תקנו), תרע\"ח (סה\"מ תרע\"ח ע' לט), תרצ\"ג (סה\"מ קונטרסים ח\"א רנד, א). ועוד."],["2239","82","ב\"קיצור מתורה ע\"פ ביום השמיני שילח וגו' . . תקס\"ג\" – אוה\"ת שמע\"צ ס\"ע א'תתיח. וראה רד\"ה זה תקס\"ג שם."],["2240","83","ועפ\"ז מובן הלשון שלח – אף שלכאורה הוא רק נטילת רשות (כבתחילת המאמר) – ראה סד\"ה ביום השמיני שלח תרצ\"ג (סה\"מ קונטרסים שם רנז, ב)."],["2241","84","סד\"ה ביום השמיני שלח בלקו\"ת דרושים לשמע\"צ פח, א. אוה\"ת ב\"קיצור\" הנ\"ל – ע' א'תתכ."],["2242","85","נצבים כט, יב."],["2243","86","רבינו בחיי עה\"פ וישב לח, ל. שם ר\"פ בלק. כד הקמח ר\"ה (ב) ד\"ה ועוד (בהוצאת שעוועל – ע' שעט). ספר החיים (לאחי המהר\"ל) ספר גאולה וישועה פ\"ב. עמק המלך שער א (שער שעשועי המלך) רפ\"א. שעהיוה\"א רפ\"ז (פא, ב). אגה\"ק ס\"כ (קל, ב). לקו\"ת שם פז, סע\"ג. וראה פרקי דר\"א פ\"ג. רבינו בחיי עה\"פ וירא כב, יג."],["2244","87","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380898\" data-slug=\"likkutei-torah\" data-id=\"4001380898\">לקו\"ת נצבים מד, ד</a> – הובא בלקו\"ת דרושים לשמע\"צ שם פז, סע\"ג."],["2245","88","שעהיוה\"א שם. ובכ\"מ."],["2246","89","לקו\"ת נצבים שם."],["2247","90","ראה לקו\"ת דרושים לשמע\"צ שם (פז, ריש ע\"ד) ד\"שלח את העם\" דשמע\"צ הוא \"להיות בבחי' שוב כדי להיות בחי' עם\" – שהכוונה ב\"בחי' עם\" כאן היא לבחי' עוממות."],["2248","91","ראה לקו\"ת שם בה\"קיצור\" (פח, ב) \"שגם בהשוב (דשמע\"צ) יהי' כלול רצוא (דר\"ה)\"."],["2249","92","לקו\"ת דרושים לשמע\"צ שם פח, א. וראה גם באוה\"ת ב\"קיצור\" שם."],["2250","93","תהלים מזמור כז."],["2251","94","סידור האריז\"ל להר\"ש מרשקוב סדר כוונת ר\"ח אלול. סידור קול יעקב וסידור אדמו\"ר הזקן אחר שיר של יום. מטה אפרים או\"ח סתקפ\"א ס\"ו*. וראה מאמרי אדמו\"ר האמצעי דברים ח\"ב ע' תצב. וש\"נ."],["2252","95","תהלים שם, ח. וראה מאמרי אדמו\"ר האמצעי שם ע' תקו: שאו' לדוד ה' אורי . . והעיקר הוא בפסוק לך אמר לבי בקשו פני כו'."],["2253","96","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380897\" data-slug=\"likkutei-torah\" data-id=\"4001380897\">לקו\"ת נצבים מד, ג</a>. וראה גם ד\"ה כי תצא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380859\" data-slug=\"likkutei-torah\" data-id=\"4001380859\">לקו\"ת (תצא לה, ג</a> ואילך), ובמאמרי אדמו\"ר האמצעי שם פ\"ה ואילך (ריש ע' תפט ואילך). שם פ\"ח-ט (ע' תצב). פ\"כ-כא (ע' תקו). וש\"נ."],["2254","97","ישעי' נד, יג."],["2255","98","מסכת ברכות בסופה."],["2256","99","לקו\"ת דרושים לשמע\"צ שם פח, א."],["2257","100","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, רע\"ג</a>. ובארוכה ד\"ה ומקנה רב תרס\"ו ובהמאמרים שלאחריו (המשך תרס\"ו ע' שח ואילך). ועוד."],["2258","101","בד\"ה זה היום תחלת מעשיך דיום ב' דר\"ה שנה זו – ה'תשמ\"א (לעיל ס\"ע לז ואילך) ס\"י."],["2259","102","ועפ\"ז יומתק הלשון בלקו\"ת דרושים לשמע\"צ שם \"ולישראל עמו שהם בניך בוניך\" – אף שלכאורה נוגע כאן רק \"בוניך\" – די\"ל שבזה מרמז ש\"ולישראל עמו\" כולל ב' הענינים, \"בניך\" ו\"בוניך\"."],["2260","103","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041297\" data-slug=\"likkutei-sichot\" data-id=\"1300041297\">לקו\"ש ח\"ד ע' 1298</a> הערה 6. ח\"ט ע' 235.\n*) <i>בסידור הר\"ש מרשקוב שם</i>:<i> עד אחר שמחת תורה</i>.<i> ובסידור קול יעקב שם</i>:<i> עד אחר שמיני עצרת</i>.<i> אבל בסידור אדמו\"ר הזקן שם הוא כבפנים</i>."],["2261","104","ויש לומר, דזהו מה שבדברי הימים כתיב \"שלח את העם לאהליהם\" – ולא \"וילכו לאהליהם\" כבמלכים – כי הנתינת כח שביו\"ט שני דשמע\"צ על העבודה ד\"אהליהם\" (עשיית דירה לו ית' בתחתונים), היא באופן שאין צריך להשתדלות נוספת, \"וילכו\"."],["2262","105","בראשית א, א."],["2263","106","דברי הימים-א כב, ט."],["2264","107","שערי תשובה לאדמו\"ר האמצעי ח\"א (שער התפלה) פי\"א (נו, א). המשך פדה בשלום תרנ\"ט (סה\"מ תרנ\"ט ע' קסד) ותש\"ד (פכ\"א – סה\"מ ה'תש\"ד ע' 11-110). ועוד."],["2265","108","פירוש המשניות להרמב\"ם סנהדרין פ' חלק יסוד הי\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081225\" data-slug=\"likkutei-sichot\" data-id=\"1300081225\">לקו\"ש ח\"ח ע' 215</a> הערה 53. וש\"נ."],["2266","109","צפני' ג, ט."],["2267","110","ד\"ה פדה בשלום תרע\"ה (המשך תער\"ב ח\"ב פ' שעד – ע' תשסט). וראה גם שערי תשובה שם (נה, ד ואילך)."]]]]});
